```apex
/**
 * ContactTriggerHandler
 *
 * Bulk-safe implementation of the Contact trigger logic.
 *
 * Behaviour (unchanged from the original trigger):
 *  - BEFORE INSERT / BEFORE UPDATE:
 *      * if Contact.MailingCountry is blank, copy Account.BillingCountry onto it
 *      * on INSERT only: if Contact.LeadSource is blank, copy Account.AccountSource onto it
 *  - AFTER INSERT:
 *      * if the Contact has an Account and a phone, and the Account has no phone,
 *        the Account phone is set from the contact.
 *      * when several new contacts of the same account carry a phone and the
 *        account has none, the FIRST such contact (in trigger order) sets the
 *        account phone; the following ones are ignored.
 *
 * Governor-limit profile for a batch of up to 200 contacts:
 *  - 1 SOQL query (the Account lookup, shared by the before and after contexts)
 *  - 1 DML statement (the single bulk Account update)
 */
public with sharing class ContactTriggerHandler {

    /**
     * Transaction-scoped cache of the Account records touched by this logic.
     * It is populated with a single SOQL query and reused by the before and
     * after contexts of the same execution, so the batch never issues a query
     * per contact.
     */
    private static Map<Id, Account> accountCache = new Map<Id, Account>();

    /**
     * Entry point called by ContactTrigger.
     */
    public static void handle() {
        if (Trigger.isBefore) {
            // A new execution starts here: drop anything cached earlier in the
            // transaction so we never work with stale Account data.
            accountCache = new Map<Id, Account>();
            applyAccountDefaultsToContacts();
        }
        if (Trigger.isAfter && Trigger.isInsert) {
            propagateContactPhoneToAccounts();
        }
    }

    /**
     * BEFORE INSERT / BEFORE UPDATE
     * Copies account defaults onto the contacts that do not have a value yet.
     */
    private static void applyAccountDefaultsToContacts() {
        List<Contact> contacts = getTriggerContacts();
        Map<Id, Account> accounts = getAccounts(collectAccountIds(contacts));

        for (Contact contact : contacts) {
            if (contact.AccountId == null) {
                continue;
            }
            Account account = accounts.get(contact.AccountId);
            if (account == null) {
                continue;
            }
            if (String.isBlank(contact.MailingCountry)) {
                contact.MailingCountry = account.BillingCountry;
            }
            if (Trigger.isInsert && String.isBlank(contact.LeadSource)) {
                contact.LeadSource = account.AccountSource;
            }
        }
    }

    /**
     * AFTER INSERT
     * Copies the contact phone onto the account when the account has no phone.
     * Only the first qualifying contact per account (in trigger order) wins,
     * and all changes are saved with a single DML statement.
     */
    private static void propagateContactPhoneToAccounts() {
        List<Contact> contacts = getTriggerContacts();
        Map<Id, Account> accounts = getAccounts(collectAccountIds(contacts));

        Set<Id> handledAccountIds = new Set<Id>();
        List<Account> accountsToUpdate = new List<Account>();

        for (Contact contact : contacts) {
            if (contact.AccountId == null || String.isBlank(contact.Phone)) {
                continue;
            }
            // The first contact (in trigger order) of an account decides the phone.
            if (handledAccountIds.contains(contact.AccountId)) {
                continue;
            }
            Account account = accounts.get(contact.AccountId);
            if (account == null) {
                continue;
            }
            handledAccountIds.add(contact.AccountId);
            if (String.isNotBlank(account.Phone)) {
                // Account already has a phone - nothing to do (and the account
                // is handled, so later contacts of the same account are skipped).
                continue;
            }
            account.Phone = contact.Phone;
            accountsToUpdate.add(account);
        }

        if (!accountsToUpdate.isEmpty()) {
            // Single DML statement for the whole batch.
            update accountsToUpdate;
        }
    }

    /**
     * Returns the Account records for the given ids, querying only the records
     * that are not already cached. At most one SOQL query per batch.
     */
    private static Map<Id, Account> getAccounts(Set<Id> accountIds) {
        Set<Id> missingIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (!accountCache.containsKey(accountId)) {
                missingIds.add(accountId);
            }
        }
        if (!missingIds.isEmpty()) {
            List<Account> accounts = [
                SELECT Id, BillingCountry, AccountSource, Phone
                FROM Account
                WHERE Id IN :missingIds
            ];
            for (Account account : accounts) {
                accountCache.put(account.Id, account);
            }
        }
        return accountCache;
    }

    /**
     * Collects the distinct account ids referenced by the given contacts.
     */
    private static Set<Id> collectAccountIds(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact contact : contacts) {
            if (contact.AccountId != null) {
                accountIds.add(contact.AccountId);
            }
        }
        return accountIds;
    }

    /**
     * Inside a class, Trigger.new is typed as List<SObject>, so the records
     * are read as SObject and cast to Contact.
     */
    private static List<Contact> getTriggerContacts() {
        List<Contact> contacts = new List<Contact>();
        for (SObject record : Trigger.new) {
            contacts.add((Contact) record);
        }
        return contacts;
    }
}
