```apex
/**
 * ExchangeRateClient
 *
 * Thin, stateless client for the FX rates provider that is exposed through the
 * Named Credential `FB_Exchange_Rates` (the Named Credential holds the base URL
 * and the authentication, so no secret ever lives in this class).
 *
 * Public API:
 *   public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies)
 *
 * Behaviour:
 *   - All currency codes are normalised (trimmed + upper-cased) and validated
 *     as exactly three letters A-Z *before* any callout is made.
 *   - Exactly one GET request is issued per call, with a single retry when the
 *     provider answers 503.
 *   - Any final non-200 status, unparsable body, or missing quote rate is
 *     surfaced as an ExchangeRateException.
 */
public with sharing class ExchangeRateClient {

    /** Exception raised for every failure condition of this client. */
    public class ExchangeRateException extends Exception {
    }

    /** Typed shape of the provider payload. */
    public class RateResponse {
        public String base;
        public String rateDate;
        public Map<String, Decimal> rates;
    }

    private static final String NAMED_CREDENTIAL = 'FB_Exchange_Rates';
    private static final String ENDPOINT = 'callout:' + NAMED_CREDENTIAL + '/v1/latest';
    private static final String CURRENCY_REGEX = '^[A-Z]{3}$';
    private static final Integer TIMEOUT_MS = 10000;

    /**
     * Retrieves the latest FX rates for the requested quote currencies.
     *
     * @param baseCurrency     Base currency code, e.g. 'EUR'.
     * @param quoteCurrencies  Quote currency codes, e.g. new Set<String>{'USD','GBP'}.
     * @return Map of normalised quote currency code -> rate (one entry per requested code).
     * @throws ExchangeRateException on invalid input, transport failure, non-200 status,
     *                               unparsable body, or a missing rate.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // ---------- Validate & normalise (no callout may happen before this succeeds) ----------
        String base = normaliseCurrency(baseCurrency);
        if (base == null) {
            throw new ExchangeRateException(
                'Invalid base currency: ' + safeToString(baseCurrency)
            );
        }

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency must be supplied.');
        }

        // Normalised, de-duplicated quote codes.
        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalised = normaliseCurrency(quote);
            if (normalised == null) {
                throw new ExchangeRateException(
                    'Invalid quote currency: ' + safeToString(quote)
                );
            }
            quotes.add(normalised);
        }

        // Deterministic ordering of the `symbols` parameter.
        List<String> quoteList = new List<String>(quotes);
        quoteList.sort();
        String symbols = String.join(quoteList, ',');

        // ---------- Call the provider through the Named Credential ----------
        HttpResponse response = send(buildRequest(base, symbols));

        // Retry exactly once on 503, with an identical request.
        if (response.getStatusCode() == 503) {
            response = send(buildRequest(base, symbols));
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException(
                'FX rates request failed with HTTP status code ' + statusCode
            );
        }

        // ---------- Parse the payload ----------
        RateResponse payload;
        try {
            payload = (RateResponse) JSON.deserialize(response.getBody(), RateResponse.class);
        } catch (Exception e) {
            throw new ExchangeRateException(
                'Unable to parse FX rates response: ' + e.getMessage()
            );
        }

        if (payload == null || payload.rates == null) {
            throw new ExchangeRateException('FX rates response did not contain any rates.');
        }

        // ---------- Map requested codes to rates, ignoring extra rates ----------
        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quoteList) {
            Decimal rate = payload.rates.get(code);
            if (rate == null) {
                throw new ExchangeRateException('No rate returned for currency: ' + code);
            }
            result.put(code, rate);
        }

        return result;
    }

    /**
     * Builds a fresh GET request for the Named Credential endpoint.
     * A new instance is used for the retry so the retried request is identical.
     */
    private static HttpRequest buildRequest(String base, String symbols) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT + '?base=' + base + '&symbols=' + symbols);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(TIMEOUT_MS);
        return request;
    }

    /** Sends the request, translating transport failures into ExchangeRateException. */
    private static HttpResponse send(HttpRequest request) {
        try {
            return new Http().send(request);
        } catch (CalloutException e) {
            throw new ExchangeRateException('FX rates callout failed: ' + e.getMessage());
        }
    }

    /**
     * Trims and upper-cases the code and validates that it is exactly three letters A-Z.
     * @return the normalised code, or null when the code is not valid.
     */
    private static String normaliseCurrency(String code) {
        if (code == null) {
            return null;
        }
        String normalised = code.trim().toUpperCase();
        if (!Pattern.matches(CURRENCY_REGEX, normalised)) {
            return null;
        }
        return normalised;
    }

    /** Null-safe rendering of an invalid input value for error messages. */
    private static String safeToString(String value) {
        return (value == null) ? 'null' : value;
    }
}
