/**
 * ContactDomainService
 *
 * Groups the contacts of the given accounts by the domain part of their email
 * address (lower-cased, e.g. Jane@Example.COM -> example.com).
 *
 * Design notes:
 *  - Bulk safe: account ids are queried in chunks (200 ids per SOQL bind) and
 *    only the fields that are needed (Id, Email, AccountId) are selected.
 *  - Sharing safe: the class is declared `with sharing` and the query runs with
 *    `WITH USER_MODE`, so the running user's record sharing (and object/field
 *    permissions) are enforced by the platform.
 *  - Defensive: null / empty input returns an empty map; contacts without an
 *    email (or without a usable domain part) are skipped.
 */
public with sharing class ContactDomainService {
    /** Max number of ids bound per SOQL IN clause (keeps queries small and well below the bind limit). */
    private static final Integer ID_CHUNK_SIZE = 200;

    /**
     * @param accountIds Ids of the accounts whose contacts should be grouped.
     * @return Map of lower-cased email domain -> list of Contacts (Id, Email, AccountId populated).
     *         Never null; empty when there is nothing to return.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        List<Id> ids = new List<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                ids.add(accountId);
            }
        }
        if (ids.isEmpty()) {
            return contactsByDomain;
        }

        for (List<Id> chunk : chunkIds(ids)) {
            // USER_MODE enforces the running user's record sharing and field/object permissions.
            List<Contact> contacts = [
                SELECT Id, Email, AccountId
                FROM Contact
                WHERE AccountId IN :chunk
                  AND Email != null
                WITH USER_MODE
            ];

            for (Contact contact : contacts) {
                String domain = extractDomain(contact.Email);
                if (domain == null) {
                    continue;
                }
                if (!contactsByDomain.containsKey(domain)) {
                    contactsByDomain.put(domain, new List<Contact>());
                }
                contactsByDomain.get(domain).add(contact);
            }
        }

        return contactsByDomain;
    }

    /**
     * Extracts the lower-cased domain of an email address.
     * @return the domain, or null when the email is blank or has no domain part.
     */
    private static String extractDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        String trimmedEmail = email.trim();
        Integer atIndex = trimmedEmail.indexOf('@');
        if (atIndex < 0) {
            return null;
        }
        String domain = trimmedEmail.substring(atIndex + 1).trim().toLowerCase();
        return String.isBlank(domain) ? null : domain;
    }

    /**
     * Splits a list of ids into chunks so that no single SOQL statement
     * exceeds the bind-variable limit.
     */
    private static List<List<Id>> chunkIds(List<Id> ids) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> current = new List<Id>();

        for (Id id : ids) {
            current.add(id);
            if (current.size() >= ID_CHUNK_SIZE) {
                chunks.add(current);
                current = new List<Id>();
            }
        }

        if (!current.isEmpty()) {
            chunks.add(current);
        }

        return chunks;
    }
}
