/**
 * Parsing helpers for supplier invoice payment terms (free text).
 *
 * Supported formats (case-insensitive, surrounding whitespace ignored):
 *   - 'NET 30', 'net30', 'Net  45'  -> 30 / 30 / 45 net days
 *   - 'DUE ON RECEIPT'              -> 0 net days
 *
 * Errors:
 *   - more than 180 net days -> TermsOutOfRangeException  ('Net days out of range: 365')
 *   - anything else         -> UnsupportedTermsException  ('Unsupported payment terms: <input>')
 *
 * Both errors extend PaymentTermsException, so callers can handle every
 * terms problem with a single catch block.
 */
public class PaymentTerms {

    /** Maximum number of net days that may be applied to an invoice. */
    private static final Integer MAX_NET_DAYS = 180;

    /** 'NET' followed by 1 to 3 digits, with optional whitespace in between. */
    private static final Pattern NET_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');

    /** 'DUE ON RECEIPT' in any capitalisation. */
    private static final Pattern DUE_ON_RECEIPT_PATTERN = Pattern.compile('(?i)^DUE\\s+ON\\s+RECEIPT$');

    /**
     * Converts free-text payment terms into the number of net days.
     *
     * @param terms Raw payment terms, e.g. 'NET 30'.
     * @return Number of net days (0 for 'DUE ON RECEIPT').
     * @throws TermsOutOfRangeException when the day count exceeds MAX_NET_DAYS.
     * @throws UnsupportedTermsException when the terms cannot be parsed.
     */
    public static Integer parseNetDays(String terms) {
        // Null and blank input are not supported terms.
        if (String.isBlank(terms)) {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + describe(terms));
        }

        String normalized = terms.trim();

        // Pay on receipt / due immediately.
        if (DUE_ON_RECEIPT_PATTERN.matcher(normalized).matches()) {
            return 0;
        }

        // Standard net-day terms.
        Matcher matcher = NET_PATTERN.matcher(normalized);
        if (matcher.matches()) {
            Integer netDays = Integer.valueOf(matcher.group(1));
            if (netDays > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + netDays);
            }
            return netDays;
        }

        // Anything else is not a recognised payment term.
        throw new UnsupportedTermsException('Unsupported payment terms: ' + describe(terms));
    }

    /**
     * Calculates the invoice due date from the invoice date and the payment terms.
