     * @return The due date (invoice date plus the net days).
     * @throws TermsOutOfRangeException when the day count exceeds MAX_NET_DAYS.
     * @throws UnsupportedTermsException when the terms cannot be parsed.
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);

        if (invoiceDate == null) {
            throw new PaymentTermsException('Invoice date is required to calculate the due date.');
        }

        return invoiceDate.addDays(netDays);
    }

