/**
 * Service that powers the admin "record finder" Lightning component.
 *
 * The service validates the request, builds one safe dynamic SOQL query and runs it:
 *
 *   SELECT Id, <fields> FROM <object> [WHERE f1 = v1 AND f2 = v2] [ORDER BY <field> ASC] LIMIT <maxRows>
 *
 * Design notes / security
 * - Object and field API names are resolved through the Schema describe API, so only real
 *   API names ever reach the query (and the case used by the UI is irrelevant).
 * - All filter values are converted into properly escaped SOQL literals, so no user supplied
 *   value can break out of the query (SOQL injection).
 * - Record level access is honoured because the class is declared `with sharing`: the query
 *   runs with the running user's OWD, sharing rules and manual/Apex sharing.
 * - Object and field level security are enforced explicitly with the describe API
 *   (isAccessible()). Fields the user may not read are rejected with a SearchException
 *   instead of being silently dropped from the query.
 * - Every failure is reported as a SearchException so callers only ever catch one type.
 */
public with sharing class RecordSearchService {

    /** Smallest number of rows the finder may return. */
    private static final Integer MIN_ROWS = 1;
    /** Largest number of rows the finder may return. */
    private static final Integer MAX_ROWS = 200;

    /**
     * Single exception type thrown by this service for every error condition
     * (invalid object/fields/filters, missing permissions, invalid row limit, ...).
     */
    public class SearchException extends Exception {
    }

    /**
     * Runs a single equality filtered SOQL query and returns the matching records.
     *
     * @param objectApiName API name of the object to search (case-insensitive).
     * @param fields        Fields to return in addition to Id. Must not be null/empty.
     * @param filters       Map of field API name -> filter value. May be null/empty.
     *                      Values may be String, Boolean, Date, Datetime, Decimal, Integer,
     *                      Long, Double, Id or null.
     * @param orderByField  Field to sort on (ascending). May be null/blank.
     * @param maxRows       Maximum number of records to return (1..200).
     * @return              The matching records.
     * @throws SearchException When anything about the request is invalid or not permitted.
     */
    @AuraEnabled(cacheable = true)
    public static List<SObject> search(String objectApiName,
                                       List<String> fields,
                                       Map<String, Object> filters,
                                       String orderByField,
                                       Integer maxRows) {

        // ------------------------------------------------------------------
        // 1. Validate the row limit
        // ------------------------------------------------------------------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + ' (received: ' + maxRows + ').');
        }

        // ------------------------------------------------------------------
        // 2. Resolve the object (case-insensitive) and check read access
        // ------------------------------------------------------------------
        Schema.SObjectType sobjectType = resolveSObjectType(objectApiName);
        Schema.DescribeSObjectResult objectDescribe = sobjectType.getDescribe();

        if (!objectDescribe.isAccessible()) {
            throw new SearchException(
                'You do not have read access to object "' + objectDescribe.getName() + '".');
        }

        String objectName = objectDescribe.getName();
        Map<String, Schema.DescribeFieldResult> fieldsByName = describeFields(objectDescribe);

        // ------------------------------------------------------------------
        // 3. Validate / collect the requested fields
        // ------------------------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        Set<String> alreadySelected = new Set<String>();
        List<String> selectFields = new List<String>();
        for (String requestedField : fields) {
            Schema.DescribeFieldResult fieldDescribe = describeField(fieldsByName, requestedField, objectName);
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to field "' + fieldDescribe.getName()
                        + '" on object "' + objectName + '".');
            }
            String canonicalName = fieldDescribe.getName();
            // Id is always part of the SELECT clause - do not add it twice.
            if (canonicalName.equalsIgnoreCase('Id')) {
                continue;
            }
            if (alreadySelected.add(canonicalName.toLowerCase())) {
                selectFields.add(canonicalName);
            }
        }

        // ------------------------------------------------------------------
        // 4. Build the WHERE clause (one equality condition per filter entry)
        // ------------------------------------------------------------------
        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterField : filters.keySet()) {
                Schema.DescribeFieldResult fieldDescribe = describeField(fieldsByName, filterField, objectName);
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('You do not have read access to field "' + fieldDescribe.getName()
                            + '" on object "' + objectName + '".');
                }
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('Field "' + fieldDescribe.getName() + '" on object "' + objectName
                            + '" cannot be filtered on.');
                }
                conditions.add(fieldDescribe.getName() + ' = ' + toSoqlLiteral(filters.get(filterField), fieldDescribe));
            }
        }

        // ------------------------------------------------------------------
        // 5. Build the ORDER BY clause
        // ------------------------------------------------------------------
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult orderFieldDescribe = describeField(fieldsByName, orderByField, objectName);
            if (!orderFieldDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to field "' + orderFieldDescribe.getName()
                        + '" on object "' + objectName + '".');
            }
            if (!orderFieldDescribe.isSortable()) {
                throw new SearchException('Field "' + orderFieldDescribe.getName() + '" on object "' + objectName
                        + '" cannot be sorted.');
            }
            orderByClause = ' ORDER BY ' + orderFieldDescribe.getName() + ' ASC';
        }

        // ------------------------------------------------------------------
        // 6. Build and run the query (exactly one SOQL statement)
        // ------------------------------------------------------------------
        String query = 'SELECT Id';
        for (String field : selectFields) {
            query += ', ' + field;
        }
        query += ' FROM ' + objectName;
        if (!conditions.isEmpty()) {
            query += ' WHERE ' + String.join(conditions, ' AND ');
        }
        query += orderByClause;
        query += ' LIMIT ' + maxRows;

        try {
            return Database.query(query);
        } catch (Exception e) {
            // Never leak a QueryException (or any other type) to the caller.
            throw new SearchException('The search could not be executed: ' + e.getMessage());
        }
    }

    // ----------------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------------

    /**
     * Resolves an object API name (case-insensitive) against the global describe.
     */
    private static Schema.SObjectType resolveSObjectType(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }
        String requested = objectApiName.trim();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(requested)) {
                return globalDescribe.get(key);
            }
        }
        throw new SearchException('"' + objectApiName + '" is not a valid object API name.');
    }

    /**
     * Returns the fields of the object keyed by their lower cased API name.
     */
    private static Map<String, Schema.DescribeFieldResult> describeFields(Schema.DescribeSObjectResult objectDescribe) {
        Map<String, Schema.DescribeFieldResult> result = new Map<String, Schema.DescribeFieldResult>();
        for (Schema.SObjectField field : objectDescribe.fields.values()) {
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            result.put(fieldDescribe.getName().toLowerCase(), fieldDescribe);
        }
        return result;
    }

    /**
     * Resolves a field name (case-insensitive) and makes sure it belongs to the object.
     */
    private static Schema.DescribeFieldResult describeField(Map<String, Schema.DescribeFieldResult> fieldsByName,
                                                             String fieldName,
                                                             String objectName) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('A field name is required.');
        }
        Schema.DescribeFieldResult fieldDescribe = fieldsByName.get(fieldName.trim().toLowerCase());
        if (fieldDescribe == null) {
            throw new SearchException('"' + fieldName + '" is not a field of object "' + objectName + '".');
        }
        return fieldDescribe;
    }

    /**
     * Converts a filter value into a safe SOQL literal.
     *
     * The value is never interpolated verbatim: strings are escaped (backslash first,
     * then single quote) and quoted, numbers/booleans/dates are rendered as native
     * SOQL literals and Id values are rendered as (unquoted) Id literals.
     */
    private static String toSoqlLiteral(Object value, Schema.DescribeFieldResult fieldDescribe) {
        String fieldName = fieldDescribe.getName();
        String typeName = fieldDescribe.getType().name();

        if (value == null) {
            // Equality form of a null filter value.
            return 'null';
        }

        if (value instanceof Boolean) {
            if (typeName == 'BOOLEAN') {
                return ((Boolean) value).toString();
            }
            return stringLiteral(String.valueOf(value));
        }

        if (value instanceof Date) {
            Date dateValue = (Date) value;
            if (typeName == 'DATE') {
                return dateLiteral(dateValue);
            }
            if (typeName == 'DATETIME') {
                return dateTimeLiteral(DateTime.newInstanceGmt(dateValue, Time.newInstance(0, 0, 0, 0)));
            }
            return stringLiteral(dateString(dateValue));
        }

        if (value instanceof Datetime) {
            Datetime dateTimeValue = (Datetime) value;
            if (typeName == 'DATETIME') {
                return dateTimeLiteral(dateTimeValue);
            }
            if (typeName == 'DATE') {
                return dateLiteral(DateTime.newInstance(dateTimeValue, TimeZone.getTimeZone('UTC')).date());
            }
            return stringLiteral(dateTimeString(dateTimeValue));
        }

        if (value instanceof Integer || value instanceof Long || value instanceof Double || value instanceof Decimal) {
            if (isNumericTypeName(typeName)) {
                return numberLiteral(value);
            }
            return stringLiteral(String.valueOf(value));
        }

        if (value instanceof Id) {
            if (typeName == 'ID' || typeName == 'REFERENCE') {
                // Id literals are not quoted in SOQL.
                return ((Id) value).toString();
            }
            return stringLiteral(((Id) value).toString());
        }

        if (value instanceof String) {
            String text = (String) value;

            if (typeName == 'BOOLEAN') {
                String normalized = text.trim().toLowerCase();
                if (normalized == 'true' || normalized == 'false') {
                    return normalized;
                }
                throw new SearchException('"' + text + '" is not a valid Boolean value for field "' + fieldName + '".');
            }

            if (isNumericTypeName(typeName)) {
                return numberLiteralFromText(text, fieldName);
            }

            if (typeName == 'DATE') {
                return dateLiteral(parseDate(text, fieldName));
            }

            if (typeName == 'DATETIME') {
                return dateTimeLiteral(parseDatetime(text, fieldName));
            }

            if (typeName == 'ID' || typeName == 'REFERENCE') {
                String candidate = text.trim();
                if (candidate.length() == 15 || candidate.length() == 18) {
                    return candidate;
                }
                // Not a well formed Id - keep it as an escaped string literal.
                return stringLiteral(candidate);
            }

            return stringLiteral(text);
        }

        throw new SearchException('Filter values of type "' + value.getClass().getName()
                + '" are not supported for field "' + fieldName + '".');
    }

    /**
     * True for the SOQL numeric field types.
     */
    private static Boolean isNumericTypeName(String typeName) {
        return typeName == 'INTEGER'
                || typeName == 'DOUBLE'
                || typeName == 'LONG'
                || typeName == 'CURRENCY'
                || typeName == 'PERCENT'
                || typeName == 'NUMBER';
    }

    /**
     * Renders a numeric filter value as an unquoted SOQL number literal.
     */
    private static String numberLiteral(Object value) {
        if (value instanceof Integer) {
            return String.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return String.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return ((Double) value).format('0.#################');
        }
        return decimalLiteral((Decimal) value);
    }

    /**
     * Renders a decimal as a plain (never scientific notation) SOQL number literal.
     */
    private static String decimalLiteral(Decimal value) {
        String plain = value.setScale(value.scale() < 0 ? 0 : value.scale()).toString();
        if (!plain.contains('E') && !plain.contains('e')) {
            return plain;
        }
        return decimalPlainString(value);
    }

    /**
     * Builds a plain decimal representation from the unscaled value and the scale.
     */
    private static String decimalPlainString(Decimal value) {
        String digits = value.unscaledValue().toString();
        Boolean negative = digits.startsWith('-');
        if (negative) {
            digits = digits.substring(1);
        }
        Integer scale = value.scale();
        String result;
        if (scale <= 0) {
            result = digits + zeros(-scale);
        } else {
            if (digits.length() <= scale) {
                digits = zeros(scale - digits.length() + 1) + digits;
            }
            Integer split = digits.length() - scale;
            result = digits.substring(0, split) + '.' + digits.substring(split);
        }
        return negative ? '-' + result : result;
    }

    /**
     * Parses a numeric filter value that was supplied as text.
     */
    private static String numberLiteralFromText(String text, String fieldName) {
        String trimmed = text.trim();
        if (trimmed.matches('[-+]?[0-9]+(\\.[0-9]+)?')) {
            return trimmed;
        }
        throw new SearchException('"' + text + '" is not a valid numeric value for field "' + fieldName + '".');
    }

    /**
     * Renders a date filter value as an unquoted SOQL date literal.
     */
    private static String dateLiteral(Date dateValue) {
        return dateString(dateValue);
    }

    /**
     * Renders a date as yyyy-MM-dd.
     */
    private static String dateString(Date dateValue) {
        return DateTime.newInstanceGmt(dateValue, Time.newInstance(0, 0, 0, 0)).format('yyyy-MM-dd');
    }

    /**
     * Renders a date/time filter value as an unquoted SOQL date-time literal (always UTC).
     */
    private static String dateTimeLiteral(Datetime dateTimeValue) {
        return dateTimeString(dateTimeValue);
    }

    /**
     * Renders a date/time as yyyy-MM-ddTHH:mm:ssZ (UTC).
     */
    private static String dateTimeString(Datetime dateTimeValue) {
        Datetime utc = dateTimeValue.setTimeZone(TimeZone.getTimeZone('UTC'));
        return utc.format('yyyy-MM-dd HH:mm:ss') + 'Z';
    }

    /**
     * Parses a date filter value that was supplied as text (yyyy-MM-dd).
     */
    private static Date parseDate(String text, String fieldName) {
        try {
            return Date.valueOf(text.trim());
        } catch (Exception e) {
            throw new SearchException('"' + text + '" is not a valid date value for field "' + fieldName + '".');
        }
    }

    /**
     * Parses a date/time filter value that was supplied as text.
     */
    private static Datetime parseDatetime(String text, String fieldName) {
        try {
            return Datetime.valueOf(text.trim());
        } catch (Exception ignored) {
            try {
                return DateTime.newInstanceGmt(Date.valueOf(text.trim()), Time.newInstance(0, 0, 0, 0));
            } catch (Exception e) {
                throw new SearchException('"' + text + '" is not a valid date/time value for field "' + fieldName + '".');
            }
        }
    }

    /**
     * Quotes and escapes a text filter value so that it can never alter the query.
     */
    private static String stringLiteral(String value) {
        return '\'' + escapeSoqlString(value) + '\'';
    }

    /**
     * Escapes a string for use inside a single quoted SOQL literal.
     * The backslash is the SOQL escape character, so backslashes are escaped first and
     * single quotes afterwards (otherwise the backslash added by the quote escape would
     * be escaped twice).
     */
    private static String escapeSoqlString(String value) {
        String escaped = value.replace('\\', '\\\\');
        escaped = escaped.replace('\'', '\\\'');
        return escaped;
    }

    /**
     * Returns a string with the given number of zeros.
     */
    private static String zeros(Integer count) {
        if (count == null || count <= 0) {
            return '';
        }
        String result = '';
        for (Integer i = 0; i < count; i++) {
            result += '0';
        }
        return result;
    }
