/**
 * ContactLookupAction
 *
 * Flow action (label: "Find Contact by Email") that resolves Contacts by email
 * address for an entire batch of requests using a single SOQL query.
 *
 * Design notes
 * - Case-insensitive matching: SOQL string equality (and the IN operator) are
 *   case-sensitive, while the LIKE operator is not. Every requested email is
 *   therefore matched with a LIKE clause, and each candidate row is re-verified
 *   in Apex with an exact, normalized (trimmed + lower-cased) comparison, so
 *   LIKE wildcards can never produce a false positive.
 * - One query per call: the whole batch is folded into a single OR'ed WHERE
 *   clause, so even 200 lookups cost exactly one query.
 * - Earliest contact wins: rows are ordered by CreatedDate (Id as a stable
 *   tie-breaker) and the first row seen for a given email is kept.
 * - Sharing: the class is declared `with sharing`, so the running user's
 *   record visibility is honoured even though Flow executes Apex in system
 *   context.
 */
public with sharing class ContactLookupAction {

    /** Upper bound on rows pulled by the single query (batch size is <= 200). */
    private static final Integer MAX_ROWS = 20000;

    /**
     * Invocable method used by Flow.
     *
     * @param requests Batch of email lookups (Flow may pass up to 200).
     * @return         Exactly one Result per Request, in the same order as the
     *                 incoming list.
     */
    @InvocableMethod(
        label = 'Find Contact by Email'
        description = 'Finds an existing Contact by email address. Matching is case-insensitive and ignores leading/trailing spaces in the supplied email. If several Contacts share the same email, the one created earliest is returned. Returns found = false when no Contact matches.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // ------------------------------------------------------------------
        // 1. Normalize the requested emails and keep the distinct set.
        //    Key  = normalized (trimmed + lower-cased) email.
        //    Value = the trimmed email used as the LIKE pattern.
        // ------------------------------------------------------------------
        Map<String, String> patternByKey = new Map<String, String>();

        for (Request request : requests) {
            if (request == null) {
                continue;
            }
            String trimmed = trimToNull(request.email);
            if (trimmed == null) {
                continue;
            }
            String key = trimmed.toLowerCase();
            if (!patternByKey.containsKey(key)) {
                patternByKey.put(key, trimmed);
            }
        }

        // ------------------------------------------------------------------
        // 2. One single SOQL query for the entire batch.
        // ------------------------------------------------------------------
        Map<String, Contact> oldestContactByKey = new Map<String, Contact>();

        if (!patternByKey.isEmpty()) {
            List<String> filters = new List<String>();
            for (String pattern : patternByKey.values()) {
                filters.add('Email LIKE \'' + String.escapeSingleQuotes(pattern) + '\'');
            }

            String soql = 'SELECT Id, Email, CreatedDate '
                        + 'FROM Contact '
                        + 'WHERE ' + String.join(filters, ' OR ')
                        + ' ORDER BY CreatedDate ASC, Id ASC '
                        + 'LIMIT ' + MAX_ROWS;

            for (SObject row : Database.query(soql)) {
                Contact contact = (Contact) row;

                // Exact, normalized verification: guards against LIKE
                // wildcards (_ and %) matching an unrelated email.
                String key = normalize(contact.Email);
                if (key == null || !patternByKey.containsKey(key)) {
                    continue;
                }

                // Rows arrive oldest first, so the first hit per email wins.
                if (!oldestContactByKey.containsKey(key)) {
                    oldestContactByKey.put(key, contact);
                }
            }
        }

        // ------------------------------------------------------------------
        // 3. Project the lookups back onto the original request order so the
        //    caller always receives exactly one Result per Request, in order.
        // ------------------------------------------------------------------
        for (Request request : requests) {
            Result result = new Result();
            result.contactId = null;
            result.found = false;

            if (request != null) {
                String key = normalize(request.email);
                if (key != null && oldestContactByKey.containsKey(key)) {
                    result.contactId = oldestContactByKey.get(key).Id;
                    result.found = true;
                }
            }

            results.add(result);
        }

        return results;
    }

    /**
     * Normalizes an email address for comparison: trims leading/trailing
     * whitespace and lower-cases the value.
     *
     * @param value Raw email value (may be null).
     * @return      Normalized key, or null when the value is null/blank.
     */
    private static String normalize(String value) {
        String trimmed = trimToNull(value);
        return trimmed == null ? null : trimmed.toLowerCase();
    }

    /**
     * Trims an email address and converts blank values to null.
     *
     * @param value Raw email value (may be null).
     * @return      Trimmed value, or null when the value is null/blank.
     */
    private static String trimToNull(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return String.isBlank(trimmed) ? null : trimmed;
    }

    /**
     * Input model for the "Find Contact by Email" action.
     */
    public class Request {
        @InvocableVariable(
            label = 'Email'
            description = 'Email address of the Contact to look up. Matching is case-insensitive and ignores leading/trailing spaces.'
            required = true
        )
        public String email;
    }

    /**
     * Output model for the "Find Contact by Email" action.
     */
    public class Result {
        @InvocableVariable(
            label = 'Contact Id'
            description = 'Id of the matching Contact, or null when no Contact was found.'
        )
        public Id contactId;

        @InvocableVariable(
            label = 'Found'
            description = 'True when a Contact with the supplied email address exists.'
        )
        public Boolean found;
    }
}
