/**
 * Parses the JSON order documents posted by the e-commerce platform and renders
 * a compact acknowledgement document.
 *
 * Design notes
 * ------------
 * - The parser is defensive: every malformed payload surfaces as an
 *   OrderPayloadParser.PayloadException. Low level errors such as
 *   JSONException or TypeCastException never escape the public API.
 * - Unknown properties (for example "meta") are ignored at every level, so the
 *   sending platform can add fields without breaking the integration.
 * - All monetary arithmetic uses Decimal (never Double) and is rounded half up
 *   to two decimal places, as required by the platform contract.
 */
public with sharing class OrderPayloadParser {

    /**
     * Raised for every invalid or unsupported payload.
     *
     * Note: no constructor is declared on purpose. Apex implicitly provides the
     * system exception constructors to Exception subclasses, so declaring a
     * (String) constructor again would fail to compile ("System exception
     * constructor already defined"). Instances are therefore created with
     * "new PayloadException('...')".
     */
    public class PayloadException extends Exception {
    }

    /** A single order line. */
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /** A parsed order. */
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<OrderPayloadParser.Line> lines = new List<OrderPayloadParser.Line>();
        public Decimal total;
    }

    /** Status returned in every acknowledgement. */
    private static final String STATUS_RECEIVED = 'RECEIVED';

    /**
     * Parses the raw request body into an Order.
     *
     * @param body raw JSON payload
     * @return the parsed order
     * @throws PayloadException when the payload is null/blank, is not valid
     *         JSON, is not a JSON object, has no usable "number", or contains an
     *         invalid line
     */
    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Payload body is null or blank.');
        }

        Object raw;
        try {
            raw = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Payload is not valid JSON: ' + e.getMessage());
        }

        if (!(raw instanceof Map)) {
            throw new PayloadException('Payload must be a JSON object.');
        }
        Map<String, Object> root = (Map<String, Object>) raw;

        OrderPayloadParser.Order order = new OrderPayloadParser.Order();

        // "number" is the only mandatory property.
        String orderNumber = toText(root.get('number'));
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Payload is missing a non-blank "number".');
        }
        order.orderNumber = orderNumber;

        // "date" is optional and ISO formatted (yyyy-MM-dd). A value that cannot
        // be understood is treated as "not supplied" rather than as fatal.
        String dateText = toText(root.get('date'));
        if (String.isNotBlank(dateText)) {
            try {
                order.orderDate = Date.valueOf(dateText);
            } catch (Exception e) {
                order.orderDate = null;
            }
        }

        order.currencyCode = toText(root.get('currency'));

        // "customer" is optional.
        Object customerValue = root.get('customer');
        if (customerValue instanceof Map) {
            Map<String, Object> customer = (Map<String, Object>) customerValue;
            order.customerEmail = toText(customer.get('email'));
        }

        order.lines = parseLines(root.get('lines'));

        Decimal total = Decimal.valueOf('0');
        for (OrderPayloadParser.Line line : order.lines) {
            total = total.add(line.lineTotal);
        }
        order.total = total;

        return order;
    }

    /**
     * Renders the acknowledgement document for a parsed order.
     *
     * The result is a JSON object with exactly four keys: number, status,
     * lineCount and total.
     *
     * @param order a parsed order
     * @return the acknowledgement JSON
     * @throws PayloadException when the order is null
     */
    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null) {
            throw new PayloadException('Cannot acknowledge a null order.');
        }

        Integer lineCount = (order.lines == null) ? 0 : order.lines.size();
        Decimal total = (order.total == null) ? Decimal.valueOf('0') : order.total;
        String numberJson = (order.orderNumber == null) ? 'null' : JSON.serialize(order.orderNumber);

        return '{"number":' + numberJson
            + ',"status":"' + STATUS_RECEIVED + '"'
            + ',"lineCount":' + lineCount
            + ',"total":' + String.valueOf(total)
            + '}';
    }

    /* ------------------------------------------------------------------ */
    /* Private helpers                                                     */
    /* ------------------------------------------------------------------ */

    /** Parses the optional "lines" array. */
    private static List<OrderPayloadParser.Line> parseLines(Object linesValue) {
        List<OrderPayloadParser.Line> lines = new List<OrderPayloadParser.Line>();
        if (linesValue == null) {
            return lines;
        }
        if (!(linesValue instanceof List)) {
            throw new PayloadException('"lines" must be a JSON array.');
        }
        List<Object> rawLines = (List<Object>) linesValue;
        for (Object item : rawLines) {
            if (!(item instanceof Map)) {
                throw new PayloadException('Every entry of "lines" must be a JSON object.');
            }
            Map<String, Object> lineData = (Map<String, Object>) item;
            lines.add(parseLine(lineData));
        }
        return lines;
    }

    /** Parses and validates a single order line. */
    private static OrderPayloadParser.Line parseLine(Map<String, Object> data) {
        OrderPayloadParser.Line line = new OrderPayloadParser.Line();

        String sku = toText(data.get('sku'));
        if (String.isBlank(sku)) {
            throw new PayloadException('Every line must have a non-blank "sku".');
        }
        line.sku = sku;

        Object quantityValue = data.get('quantity');
        if (quantityValue == null) {
            throw new PayloadException('Line "' + sku + '" is missing "quantity".');
        }
        Integer quantity = toInteger(quantityValue);
        if (quantity == null) {
            throw new PayloadException('Line "' + sku + '" has an invalid "quantity".');
        }
        if (quantity <= 0) {
            throw new PayloadException('Line "' + sku + '" must have a positive "quantity".');
        }
        line.quantity = quantity;

        Object unitPriceValue = data.get('unitPrice');
        if (unitPriceValue == null) {
            throw new PayloadException('Line "' + sku + '" is missing "unitPrice".');
        }
        Decimal unitPrice = toDecimal(unitPriceValue);
        if (unitPrice == null) {
            throw new PayloadException('Line "' + sku + '" has an invalid "unitPrice".');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Line "' + sku + '" must not have a negative "unitPrice".');
        }
        line.unitPrice = unitPrice;

        // A missing or null discount means "no discount" and is stored as 0.
        Decimal discount = Decimal.valueOf('0');
        Object discountValue = data.get('discount');
        if (discountValue != null) {
            Decimal parsedDiscount = toDecimal(discountValue);
            if (parsedDiscount != null) {
                // A discount is a fraction between 0 and 1; out of range values
                // are clamped instead of rejected.
                if (parsedDiscount < Decimal.valueOf('0')) {
                    discount = Decimal.valueOf('0');
                } else if (parsedDiscount > Decimal.valueOf('1')) {
                    discount = Decimal.valueOf('1');
                } else {
                    discount = parsedDiscount;
                }
            }
        }
        line.discount = discount;

        // lineTotal = quantity x unitPrice x (1 - discount), rounded half up to
        // two decimal places (1.005 -> 1.01).
        Decimal gross = Decimal.valueOf(String.valueOf(line.quantity));
        gross = gross.multiply(line.unitPrice);
        Decimal netFactor = Decimal.valueOf('1').subtract(line.discount);
        line.lineTotal = gross.multiply(netFactor).setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    /**
     * Best effort conversion of a JSON scalar to text. Structured values
     * (objects/arrays) and null return null.
     */
    private static String toText(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        if (value instanceof Integer || value instanceof Long
                || value instanceof Decimal || value instanceof Double) {
            return String.valueOf(value);
        }
        return null;
    }

    /** Best effort conversion of a JSON scalar to Decimal; null when not numeric. */
    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf(String.valueOf(((Integer) value).intValue()));
        }
        if (value instanceof Long) {
            return Decimal.valueOf(String.valueOf(((Long) value).longValue()));
        }
        if (value instanceof Double) {
            return decimalFromText(String.valueOf(((Double) value).doubleValue()));
        }
        if (value instanceof String) {
            return decimalFromText((String) value);
        }
        return null;
    }

    /** Best effort conversion of a JSON scalar to Integer; null when not a whole number. */
    private static Integer toInteger(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Integer) {
            return (Integer) value;
        }
        if (value instanceof Long) {
            return ((Long) value).intValue();
        }
        Decimal numeric = toDecimal(value);
        if (numeric == null) {
            return null;
        }
        numeric = numeric.stripTrailingZeros();
        if (numeric.scale() > 0) {
            return null;
        }
        return numeric.intValue();
    }

    /** Parses a numeric literal into a Decimal, returning null when impossible. */
    private static Decimal decimalFromText(String text) {
        if (text == null) {
            return null;
        }
        String trimmed = text.trim();
        if (trimmed.isNumeric()) {
            try {
                return Decimal.valueOf(trimmed);
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }
