/**
 * Unit tests for AddressVerificationService.
 *
 * The tests are self contained (no SeeAllData) and use an inner HttpCalloutMock
 * implementation so that the full request contract (endpoint, method, headers, body)
 * and every documented outcome (SKIPPED / VERIFIED / CORRECTED / INVALID / HTTP error)
 * are asserted.
 */
@IsTest
private class AddressVerificationServiceTest {

    private static final String ENDPOINT = 'callout:FB_Address_API/v2/verify';
    private static final String CONTENT_TYPE = 'application/json';

    private static final String STREET = '221B Baker Street';
    private static final String CITY = 'London';
    private static final String POSTAL_CODE = 'NW1 6XE';
    private static final String COUNTRY = 'United States';

    /**
     * Configurable HttpCalloutMock: records the request that was sent and returns
     * the configured status code / body.
     */
    private class AddressApiMock implements HttpCalloutMock {
        Integer statusCode = 200;
        String responseBody = '{"status":"VERIFIED"}';

        HttpRequest lastRequest;
        Integer callCount = 0;

        public HttpResponse respond(HttpRequest request) {
            this.lastRequest = request;
            this.callCount += 1;

            HttpResponse res = new HttpResponse();
            res.setStatusCode(this.statusCode);
            res.setStatus(this.statusCode == 200 ? 'OK' : 'ERROR');
            res.setHeader('Content-Type', CONTENT_TYPE);
            res.setBody(this.responseBody);
            return res;
        }
    }

    private static Account newAccount(String street, String city, String postalCode, String country) {
        Account acct = new Account(
            Name = 'Address Verification Test Account',
            BillingStreet = street,
            BillingCity = city,
            BillingPostalCode = postalCode,
            BillingCountry = country
        );
        insert acct;
        return acct;
    }

    @IsTest
    static void verifySkipsAccountWithBlankBillingStreet() {
        AddressApiMock mock = new AddressApiMock();
        Test.setMock(HttpCalloutMock.class, mock);

        Account noStreet = newAccount(null, CITY, POSTAL_CODE, COUNTRY);
        Account emptyStreet = newAccount('', CITY, POSTAL_CODE, COUNTRY);
        Account whitespaceStreet = newAccount('   ', CITY, POSTAL_CODE, COUNTRY);

        AddressVerificationService.Result r1 = AddressVerificationService.verify(noStreet);
        AddressVerificationService.Result r2 = AddressVerificationService.verify(emptyStreet);
        AddressVerificationService.Result r3 = AddressVerificationService.verify(whitespaceStreet);

        Assert.areEqual('SKIPPED', r1.status, 'Null BillingStreet must be skipped');
        Assert.areEqual('SKIPPED', r2.status, 'Empty BillingStreet must be skipped');
        Assert.areEqual('SKIPPED', r3.status, 'Whitespace only BillingStreet must be skipped');

        Assert.isFalse(r1.changed, 'Skipped result must not be flagged as changed');
        Assert.isFalse(r2.changed, 'Skipped result must not be flagged as changed');
        Assert.isFalse(r3.changed, 'Skipped result must not be flagged as changed');

        Assert.areEqual(0, mock.callCount, 'No callout may be made when BillingStreet is blank');
    }

    @IsTest
    static void verifySendsDocumentedRequestContract() {
        AddressApiMock mock = new AddressApiMock();
        mock.statusCode = 200;
        mock.responseBody = '{"status":"VERIFIED","address":{'
            + '"street":"221B Baker Street","city":"London",'
            + '"postalCode":"NW1 6XE","country":"United States"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = newAccount(STREET, CITY, POSTAL_CODE, COUNTRY);
        AddressVerificationService.verify(acct);

        Assert.areEqual(1, mock.callCount, 'Exactly one callout is expected');
        Assert.isNotNull(mock.lastRequest, 'The callout request should have been recorded');

        Assert.areEqual(
            ENDPOINT,
            mock.lastRequest.getEndpoint(),
            'The service must call POST callout:FB_Address_API/v2/verify'
        );
        Assert.areEqual('POST', mock.lastRequest.getMethod(), 'The callout must use the POST method');
        Assert.areEqual(
            CONTENT_TYPE,
            mock.lastRequest.getHeader('Content-Type'),
            'The callout must send the Content-Type: application/json header'
        );

        Map<String, Object> sent = (Map<String, Object>) JSON.deserializeUntyped(mock.lastRequest.getBody());
        Assert.isNotNull(sent, 'The request body must be valid JSON');
        Assert.areEqual(4, sent.size(), 'The request body must contain exactly street, city, postalCode and country');
        Assert.areEqual(STREET, sent.get('street'), 'street must be the account BillingStreet');
        Assert.areEqual(CITY, sent.get('city'), 'city must be the account BillingCity');
        Assert.areEqual(POSTAL_CODE, sent.get('postalCode'), 'postalCode must be the account BillingPostalCode');
        Assert.areEqual(COUNTRY, sent.get('country'), 'country must be the account BillingCountry');
    }

    @IsTest
    static void verifyReturnsVerifiedWithoutChangingAccount() {
        AddressApiMock mock = new AddressApiMock();
        mock.statusCode = 200;
        mock.responseBody = '{"status":"VERIFIED","address":{'
            + '"street":"99 Wrong St","city":"Wrongville","postalCode":"00000","country":"United States"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = newAccount(STREET, CITY, POSTAL_CODE, COUNTRY);
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        Assert.areEqual('VERIFIED', result.status, 'The response status must be returned');
        Assert.isFalse(result.changed, 'A VERIFIED address must not be flagged as changed');

        Assert.areEqual(STREET, acct.BillingStreet, 'BillingStreet must be untouched for VERIFIED');
        Assert.areEqual(CITY, acct.BillingCity, 'BillingCity must be untouched for VERIFIED');
        Assert.areEqual(POSTAL_CODE, acct.BillingPostalCode, 'BillingPostalCode must be untouched for VERIFIED');
        Assert.areEqual(COUNTRY, acct.BillingCountry, 'BillingCountry must be untouched for VERIFIED');
    }

    @IsTest
    static void verifyReturnsInvalidWithoutChangingAccount() {
        AddressApiMock mock = new AddressApiMock();
        mock.statusCode = 200;
        mock.responseBody = '{"status":"INVALID","address":{'
            + '"street":"99 Wrong St","city":"Wrongville","postalCode":"00000","country":"United States"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = newAccount(STREET, CITY, POSTAL_CODE, COUNTRY);
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        Assert.areEqual('INVALID', result.status, 'The response status must be returned');
        Assert.isFalse(result.changed, 'An INVALID address must not be flagged as changed');

        Assert.areEqual(STREET, acct.BillingStreet, 'BillingStreet must be untouched for INVALID');
        Assert.areEqual(CITY, acct.BillingCity, 'BillingCity must be untouched for INVALID');
        Assert.areEqual(POSTAL_CODE, acct.BillingPostalCode, 'BillingPostalCode must be untouched for INVALID');
        Assert.areEqual(COUNTRY, acct.BillingCountry, 'BillingCountry must be untouched for INVALID');
    }

    @IsTest
    static void verifyAppliesCorrectedAddressInMemoryOnly() {
        AddressApiMock mock = new AddressApiMock();
        mock.statusCode = 200;
        mock.responseBody = '{"status":"CORRECTED","address":{'
            + '"street":"1 Corrected Street","city":"Correctville",'
            + '"postalCode":"54321","country":"United States"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = newAccount(STREET, CITY, POSTAL_CODE, COUNTRY);
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        Assert.areEqual('CORRECTED', result.status, 'The response status must be returned');
        Assert.isTrue(result.changed, 'A CORRECTED address must be flagged as changed');

        Assert.areEqual('1 Corrected Street', acct.BillingStreet, 'BillingStreet must be overwritten');
        Assert.areEqual('Correctville', acct.BillingCity, 'BillingCity must be overwritten');
        Assert.areEqual('54321', acct.BillingPostalCode, 'BillingPostalCode must be overwritten');
        Assert.areEqual('United States', acct.BillingCountry, 'BillingCountry must be overwritten');

        Account persisted = [
            SELECT BillingStreet, BillingCity, BillingPostalCode, BillingCountry
            FROM Account
            WHERE Id = :acct.Id
        ];
        Assert.areEqual(STREET, persisted.BillingStreet, 'The account must not be saved to the database');
        Assert.areEqual(CITY, persisted.BillingCity, 'The account must not be saved to the database');
        Assert.areEqual(POSTAL_CODE, persisted.BillingPostalCode, 'The account must not be saved to the database');
        Assert.areEqual(COUNTRY, persisted.BillingCountry, 'The account must not be saved to the database');
    }

    @IsTest
    static void verifyThrowsOnNotFoundResponse() {
        AddressApiMock mock = new AddressApiMock();
        mock.statusCode = 404;
        mock.responseBody = '{"error":"not found"}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = newAccount(STREET, CITY, POSTAL_CODE, COUNTRY);

        try {
            AddressVerificationService.verify(acct);
            Assert.fail('An AddressVerificationException should have been thrown for HTTP 404');
        } catch (AddressVerificationService.AddressVerificationException e) {
            Assert.isTrue(
                e.getMessage() != null && e.getMessage().contains('404'),
                'The exception message must contain the status code, but was: ' + e.getMessage()
            );
        }
        Assert.areEqual(1, mock.callCount, 'Exactly one callout is expected');
    }

    @IsTest
    static void verifyThrowsOnServerErrorResponse() {
        AddressApiMock mock = new AddressApiMock();
        mock.statusCode = 500;
        mock.responseBody = '{"error":"server error"}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = newAccount(STREET, CITY, POSTAL_CODE, COUNTRY);

        try {
            AddressVerificationService.verify(acct);
            Assert.fail('An AddressVerificationException should have been thrown for HTTP 500');
        } catch (AddressVerificationService.AddressVerificationException e) {
            Assert.isTrue(
                e.getMessage() != null && e.getMessage().contains('500'),
                'The exception message must contain the status code, but was: ' + e.getMessage()
            );
        }
        Assert.areEqual(1, mock.callCount, 'Exactly one callout is expected');
    }
}
