/**
 * Test class for ShippingCostCalculator.
 *
 * Covers:
 *  - weight validation (null / zero / negative -> ShippingException)
 *  - base price weight tiers and their exact boundaries (1 / 5 / 20 kg and the
 *    "started kilogram" rule above 20 kg)
 *  - zone multipliers (DOMESTIC 1.0, EU 1.4, WORLD 2.2) and case-insensitive zone names
 *  - express surcharge (+50%)
 *  - free shipping for DOMESTIC standard orders with orderValue >= 100
 *  - rounding to 2 decimal places, half up
 *  - unknown / null zone -> ShippingException
 *
 * Self-contained: no SeeAllData, no org data and no Apex source inspection.
 */
@IsTest
public class ShippingCostCalculatorTest {

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static Decimal quote(Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        return ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
    }

    private static void assertShippingException(Decimal weightKg, String zone, Boolean express, Decimal orderValue, String expectedMessageFragment) {
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
            System.assert(false, 'Expected a ShippingException for weightKg=' + weightKg + ', zone=' + zone);
        } catch (ShippingCostCalculator.ShippingException e) {
            String message = e.getMessage();
            System.assert(message != null && !String.isEmpty(message), 'ShippingException should carry a message');
            System.assert(
                message.contains(expectedMessageFragment),
                'Unexpected message: ' + message
            );
        }
    }

    // ------------------------------------------------------------------
    // Weight validation
    // ------------------------------------------------------------------

    @IsTest
    static void weightMustBeGreaterThanZero() {
        assertShippingException(null, 'DOMESTIC', false, null, 'Weight must be greater than 0');
        assertShippingException(0, 'DOMESTIC', false, null, 'Weight must be greater than 0');
        assertShippingException(0.000, 'DOMESTIC', false, null, 'Weight must be greater than 0');
        assertShippingException(-1, 'DOMESTIC', false, null, 'Weight must be greater than 0');
        assertShippingException(-0.5, 'EU', true, 500, 'Weight must be greater than 0');
        // Weight is validated before the zone.
        assertShippingException(null, 'NOT_A_ZONE', false, null, 'Weight must be greater than 0');
        assertShippingException(-2, 'NOT_A_ZONE', true, 500, 'Weight must be greater than 0');
    }

    // ------------------------------------------------------------------
    // Zone validation
    // ------------------------------------------------------------------

    @IsTest
    static void unknownOrNullZoneThrows() {
        assertShippingException(1, null, false, null, 'Unknown zone');
        assertShippingException(1, '', false, null, 'Unknown zone');
        assertShippingException(1, 'US', false, null, 'Unknown zone');
        assertShippingException(1, 'dom', false, null, 'Unknown zone');
        assertShippingException(1, 'E U', true, 100, 'Unknown zone');
        assertShippingException(20.1, 'MOON', false, null, 'Unknown zone');
        // An invalid zone must not be short-circuited by the free-shipping rule.
        assertShippingException(1, 'US', false, 1000, 'Unknown zone');
    }

    // ------------------------------------------------------------------
    // Base price tiers
    // ------------------------------------------------------------------

    @IsTest
    static void basePriceByWeightTiers() {
        // Up to and including 1 kg -> 5.00
        System.assertEquals(5.00, quote(0.001, 'DOMESTIC', false, null));
        System.assertEquals(5.00, quote(0.5, 'DOMESTIC', false, null));
        System.assertEquals(5.00, quote(1, 'DOMESTIC', false, null));

        // Above 1 kg up to and including 5 kg -> 9.50
        System.assertEquals(9.50, quote(1.01, 'DOMESTIC', false, null));
        System.assertEquals(9.50, quote(2.5, 'DOMESTIC', false, null));
        System.assertEquals(9.50, quote(3, 'DOMESTIC', false, null));
        System.assertEquals(9.50, quote(5, 'DOMESTIC', false, null));

        // Above 5 kg up to and including 20 kg -> 18.00
        System.assertEquals(18.00, quote(5.01, 'DOMESTIC', false, null));
        System.assertEquals(18.00, quote(12.5, 'DOMESTIC', false, null));
        System.assertEquals(18.00, quote(20, 'DOMESTIC', false, null));

        // Above 20 kg -> 18.00 + 0.75 per started kilogram above 20
        System.assertEquals(18.75, quote(20.001, 'DOMESTIC', false, null));
        System.assertEquals(18.75, quote(20.01, 'DOMESTIC', false, null));
        System.assertEquals(18.75, quote(20.1, 'DOMESTIC', false, null));
        System.assertEquals(18.75, quote(21, 'DOMESTIC', false, null));
        System.assertEquals(19.50, quote(21.01, 'DOMESTIC', false, null));
        System.assertEquals(19.50, quote(21.5, 'DOMESTIC', false, null));
        System.assertEquals(19.50, quote(22, 'DOMESTIC', false, null));
        System.assertEquals(78.00, quote(100, 'DOMESTIC', false, null));
    }

    // ------------------------------------------------------------------
    // Zone multipliers
    // ------------------------------------------------------------------

    @IsTest
    static void zoneMultipliers() {
        // DOMESTIC x1.0
        System.assertEquals(5.00, quote(1, 'DOMESTIC', false, null));
        System.assertEquals(9.50, quote(5, 'DOMESTIC', false, null));
        System.assertEquals(18.00, quote(20, 'DOMESTIC', false, null));

        // EU x1.4
        System.assertEquals(7.00, quote(1, 'EU', false, null));
        System.assertEquals(13.30, quote(5, 'EU', false, null));
        System.assertEquals(25.20, quote(20, 'EU', false, null));
        System.assertEquals(26.25, quote(20.1, 'EU', false, null));
        System.assertEquals(26.25, quote(21, 'EU', false, null));

        // WORLD x2.2
        System.assertEquals(11.00, quote(1, 'WORLD', false, null));
        System.assertEquals(20.90, quote(5, 'WORLD', false, null));
        System.assertEquals(39.60, quote(20, 'WORLD', false, null));
        System.assertEquals(41.25, quote(20.1, 'WORLD', false, null));
        System.assertEquals(41.25, quote(21, 'WORLD', false, null));
    }

    @IsTest
    static void zoneNamesAreCaseInsensitive() {
        System.assertEquals(5.00, quote(1, 'domestic', false, null));
        System.assertEquals(5.00, quote(1, 'Domestic', false, null));
        System.assertEquals(5.00, quote(1, 'DOMESTIC', false, null));
        System.assertEquals(7.00, quote(1, 'eu', false, null));
        System.assertEquals(7.00, quote(1, 'Eu', false, null));
        System.assertEquals(7.00, quote(1, 'EU', false, null));
        System.assertEquals(11.00, quote(1, 'world', false, null));
        System.assertEquals(11.00, quote(1, 'WoRlD', false, null));
        System.assertEquals(11.00, quote(1, 'WORLD', false, null));
    }

    // ------------------------------------------------------------------
    // Express delivery
    // ------------------------------------------------------------------

    @IsTest
    static void expressAddsFiftyPercent() {
        System.assertEquals(7.50, quote(1, 'DOMESTIC', true, null));
        System.assertEquals(14.25, quote(5, 'DOMESTIC', true, null));
        System.assertEquals(27.00, quote(20, 'DOMESTIC', true, null));
        System.assertEquals(10.50, quote(1, 'EU', true, null));
        System.assertEquals(19.95, quote(5, 'EU', true, null));
        System.assertEquals(37.80, quote(20, 'EU', true, null));
        System.assertEquals(16.50, quote(1, 'WORLD', true, null));
        System.assertEquals(31.35, quote(5, 'WORLD', true, null));
        System.assertEquals(59.40, quote(20, 'WORLD', true, null));
        System.assertEquals(28.13, quote(21, 'DOMESTIC', true, null));
    }

    @IsTest
    static void nullExpressFlagMeansStandardDelivery() {
        System.assertEquals(5.00, quote(1, 'DOMESTIC', null, null));
        System.assertEquals(7.00, quote(1, 'EU', null, null));
        System.assertEquals(11.00, quote(1, 'WORLD', null, null));
        System.assertEquals(9.50, quote(5, 'DOMESTIC', null, null));
        System.assertEquals(18.00, quote(20, 'DOMESTIC', null, null));
        System.assertEquals(18.75, quote(20.1, 'DOMESTIC', null, null));
    }

    // ------------------------------------------------------------------
    // Free shipping
    // ------------------------------------------------------------------

    @IsTest
