        System.assertEquals(TASK_SUBJECT, t.Subject, 'The task subject must be "Customer kick-off"');
        System.assertEquals(opp.Id, t.WhatId, 'The task must be linked to the opportunity');
        System.assertEquals(opp.OwnerId, t.OwnerId, 'The task owner must be the opportunity owner');
        System.assertEquals(EXPECTED_ACTIVITY_DATE, t.ActivityDate,
            'The task activity date must be the opportunity close date plus 7 days');
        System.assertEquals(opp.CloseDate.addDays(7), t.ActivityDate,
            'The task activity date must be the opportunity close date plus 7 days');
        System.assertEquals(TASK_PRIORITY, t.Priority, 'The task priority must be High');
    }

    private static Id createOtherUser() {
        try {
            Profile profile = [SELECT Id FROM Profile WHERE UserType = 'Standard' AND UserLicenseId != null LIMIT 1];
            String suffix = EncodingUtil.convertToHex(Crypto.generateRandomBytes(8));
            User u = new User(
                FirstName = 'Other',
                LastName = 'Owner',
                Alias = 'oth' + suffix.substring(suffix.length() - 5),
                Email = 'otherowner' + suffix + '@example.com',
                Username = 'otherowner' + suffix + '@example.com',
                ProfileId = profile.Id,
                TimeZoneSidKey = 'America/Los_Angeles',
                LocaleSidKey = 'en_US',
                EmailEncodingKey = 'UTF-8',
                LanguageLocaleKey = 'en_US'
            );
            insert u;
            return u.Id;
        } catch (Exception e) {
            return null;
        }
    }

    private static Boolean probeOpportunityOwnerAssignment() {
        if (otherUserId == null) {
            return false;
        }
        try {
            Opportunity probe = buildOpportunity(OPEN_STAGE, warmAccountId);
            probe.OwnerId = otherUserId;
            insert probe;
            Boolean assigned = probe.OwnerId == otherUserId;
            delete probe;
            return assigned;
        } catch (Exception e) {
            return false;
        }
    }

    private static Boolean probeTaskOwnerAssignment() {
        if (otherUserId == null) {
            return false;
        }
        try {
            Task probe = new Task(
                Subject = 'Permission probe',
                OwnerId = otherUserId,
                ActivityDate = Date.today(),
                Status = 'Not Started'
            );
            insert probe;
            delete probe;
            return true;
        } catch (Exception e) {
            return false;
        }
    }
