/**
 * LeadImportService
 *
 * Imports Leads captured from marketing trade-show spreadsheets.
 *
 * Design notes:
 *  - Partial success: a single `Database.insert(..., false)` call is used, so valid
 *    Leads are inserted even when other Leads in the same batch are rejected.
 *  - Duplicate detection happens in memory (case-insensitive, whitespace trimmed) and
 *    duplicates are never sent to the database. Duplicate detection is based purely on
 *    input order, so it also holds when the first Lead with that email later fails to
 *    insert.
 *  - Exactly one DML statement is executed per `importLeads` call.
 *  - The class is declared `with sharing`, so the running user's sharing rules are
 *    respected (both for queries and for the DML).
 */
public with sharing class LeadImportService {

    /** LeadSource picklist value applied to Leads that arrive without a source. */
    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /** Error message prefix used for in-batch duplicate e-mail addresses. */
    private static final String DUPLICATE_EMAIL_PREFIX = 'Duplicate email in import: ';

    /**
     * Result of a lead import.
     * All members are always initialized (never null).
     */
    public class ImportResult {
        /** Number of Leads that were successfully inserted. */
        public Integer successCount = 0;

        /** Ids of the inserted Leads, in the order of the input list. */
        public List<Id> insertedIds = new List<Id>();

        /** 0-based input position -> error message for the Leads that were not imported. */
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();

        /** Convenience flag: true when at least one Lead failed to import. */
        public Boolean hasErrors() {
            return !errorsByIndex.isEmpty();
        }
    }

    /**
     * Imports the given Leads.
     *
     * @param leads Leads to import. May contain nulls; individual invalid Leads are
     *              reported through ImportResult.errorsByIndex instead of throwing.
     * @return an ImportResult describing what was inserted and what failed.
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Leads that are actually sent to the database and their original input position.
        List<Lead> recordsToInsert = new List<Lead>();
        List<Integer> originalIndexes = new List<Integer>();

        // Normalized e-mail addresses already seen in this batch.
        Set<String> seenEmails = new Set<String>();

        for (Integer index = 0; index < leads.size(); index++) {
            Lead lead = leads[index];

            if (lead == null) {
                result.errorsByIndex.put(index, 'Lead record is null');
                continue;
            }

            // Default the lead source before inserting.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }

            // In-batch duplicate detection (case-insensitive, surrounding whitespace ignored).
            String email = (lead.Email == null) ? null : lead.Email.trim();
            if (String.isNotBlank(email)) {
                String normalizedEmail = email.toLowerCase();
                if (seenEmails.contains(normalizedEmail)) {
                    // Not sent to the database at all.
                    result.errorsByIndex.put(index, DUPLICATE_EMAIL_PREFIX + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            recordsToInsert.add(lead);
            originalIndexes.add(index);
        }

        // Nothing left to insert (all duplicates / nulls).
        if (recordsToInsert.isEmpty()) {
            return result;
        }

        // Single DML statement, partial success allowed.
        List<Database.SaveResult> saveResults;
        try {
            saveResults = Database.insert(recordsToInsert, false);
        } catch (Exception e) {
            // Safety net: a batch-level failure (for example an unhandled trigger
            // exception) must not escape the service.
            String message = e.getMessage();
            if (String.isBlank(message)) {
                message = e.getTypeName();
            }
            for (Integer index : originalIndexes) {
                result.errorsByIndex.put(index, message);
            }
            result.successCount = 0;
            result.insertedIds = new List<Id>();
            return result;
        }

        // Map the per-record results back onto the original input positions.
        for (Integer i = 0; i < recordsToInsert.size(); i++) {
            Integer originalIndex = originalIndexes[i];
            Database.SaveResult saveResult = saveResults[i];

            if (saveResult.isSuccess()) {
                result.insertedIds.add(recordsToInsert[i].Id);
            } else {
                result.errorsByIndex.put(originalIndex, buildErrorMessage(saveResult));
            }
        }

        result.successCount = result.insertedIds.size();
        return result;
    }

    /**
     * Builds the error message for a rejected record: the database error messages for
     * that record, joined with '; '.
     */
    private static String buildErrorMessage(Database.SaveResult saveResult) {
        List<String> messages = new List<String>();

        for (Database.Error dbError : saveResult.getErrors()) {
            String message = dbError.getMessage();
            if (String.isBlank(message)) {
                // Fall back to the status code and the offending fields.
                message = '' + dbError.getStatusCode();
                List<String> fields = dbError.getFields();
                if (fields != null && !fields.isEmpty()) {
                    message += ': ' + String.join(fields, ', ');
                }
            }
            messages.add(message);
        }

        if (messages.isEmpty()) {
            return 'Unknown error';
        }

        return String.join(messages, '; ');
    }
}
