/**
 * AccountScoringJob
 *
 * Queueable Apex job that (re)rates Accounts based on their AnnualRevenue:
 *
 *      AnnualRevenue >= 1,000,000  ->  Hot
 *      AnnualRevenue >=   100,000  ->  Warm
 *      anything else (incl. blank) ->  Cold
 *
 * Design notes
 * ------------
 * * One execution rates at most 200 Accounts and uses exactly ONE SOQL query
 *   and ONE DML statement.
 * * If Ids are left over, the execution enqueues the next AccountScoringJob
 *   with the remaining Ids, so a single start() call walks the entire list
 *   through a chain of jobs.
 * * The chaining is deliberately NOT skipped while a test is running: in a
 *   test context the queued jobs are executed synchronously, which is exactly
 *   what allows the complete chain to be verified inside a single test
 *   (Test.startTest() / Test.stopTest()).
 * * The QueueableContext is never dereferenced, so the job can also be driven
 *   directly (execute(null)) from a test or from other code.
 */
public class AccountScoringJob implements Queueable {

    /** Maximum number of Accounts rated by a single execution. */
    @TestVisible
    private static final Integer BATCH_SIZE = 200;

    /** Ids that still have to be processed by this job and its successors. */
    private final List<Id> accountIds;

    /**
     * @param accountIds Ids of the Accounts to rate. Null entries are ignored.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = new List<Id>();
        if (accountIds != null) {
            for (Id accountId : accountIds) {
                if (accountId != null) {
                    this.accountIds.add(accountId);
                }
            }
        }
    }

    /**
     * Enqueues the first job of the chain.
     *
     * @param accountIds Ids of the Accounts to rate. Null entries are ignored.
     * @return Id of the enqueued job, or null when there was nothing to enqueue.
     */
    public static Id start(List<Id> accountIds) {
        List<Id> ids = new List<Id>();
        if (accountIds != null) {
            for (Id accountId : accountIds) {
                if (accountId != null) {
                    ids.add(accountId);
                }
            }
        }

        if (ids.isEmpty()) {
            // Nothing to do: enqueue nothing and report no job.
            return null;
        }

        // System.enqueueJob(Queueable) returns the Id of the enqueued job.
        return System.enqueueJob(new AccountScoringJob(ids));
    }

    /**
     * Rates the first BATCH_SIZE Accounts of the list and enqueues the rest.
     *
     * @param context Queueable context supplied by the platform. It is not
     *                used, which allows direct invocation (execute(null)).
     */
    public void execute(QueueableContext context) {
        Integer batchSize = accountIds.size() > BATCH_SIZE ? BATCH_SIZE : accountIds.size();

        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < batchSize) {
                batchIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        if (!batchIds.isEmpty()) {
            // ONE SOQL query for this execution.
            List<Account> accounts = [
                SELECT Id, Name, AnnualRevenue, Rating
                FROM Account
                WHERE Id IN :batchIds
            ];

            for (Account account : accounts) {
                account.Rating = ratingFor(account.AnnualRevenue);
            }

            // ONE DML statement for this execution.
            update accounts;
        }

        // Chain the remaining Ids into the next job of the chain.
        // This happens in tests as well so that the whole chain can be
        // verified inside a single test method.
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    /**
     * Maps AnnualRevenue onto the Account Rating picklist.
     */
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }
}
