/**
 * Queueable job that flags Accounts as synchronized with the ERP.
 *
 * Design notes
 * -----------
 * * The ErpSyncFinalizer is attached as the very first thing the job does, so that
 *   EVERY run (successful or failed) is written to FB_Job_Log__c.
 * * The Accounts are saved with a single `update` statement. A single DML statement is
 *   atomic: if one of the records cannot be saved the whole statement is rolled back.
 *   The exception is deliberately NOT caught, so the transaction fails, no partial
 *   change is kept and the finalizer records the failure (and schedules a retry).
 */
public with sharing class ErpAccountSyncJob implements Queueable {

    /** Value written to Account.Description for a synchronized account. */
    private static final String SYNCED_DESCRIPTION = 'Synced to ERP';

    /** Attempt used for the first run. */
    private static final Integer DEFAULT_ATTEMPT = 1;

    private final Set<Id> accountIds;
    private final Integer attempt;

    /**
     * @param accountIds Ids of the Accounts to flag as synced.
     * @param attempt    1 for the first run, incremented by the finalizer on every retry.
     */
    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = (accountIds == null) ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = (attempt == null) ? DEFAULT_ATTEMPT : attempt;
    }

    /**
     * Queued entry point.
     *
     * @param context Standard queueable context (not used here).
     */
    public void execute(QueueableContext context) {
        // 1. Attach the finalizer BEFORE doing any work: it must run for this
        //    transaction whatever the outcome is.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        if (accountIds.isEmpty()) {
            // Nothing to synchronize - the finalizer still logs the run.
            return;
        }

        // 2. Build the records to update. Only Id and Description are set, so every
        //    other field of the Account is left untouched.
        List<Account> accounts = new List<Account>();
        for (Id accountId : accountIds) {
            accounts.add(new Account(Id = accountId, Description = SYNCED_DESCRIPTION));
        }

        // 3. Single, all-or-nothing DML statement.
        //    If any account cannot be saved an uncaught DmlException is raised: the
        //    transaction is rolled back (none of the changes are kept) and the
        //    finalizer records the failure and schedules the next attempt.
        update accounts;
    }
}
