/**
 * Transaction finalizer for ErpAccountSyncJob.
 *
 * The finalizer runs after the queued transaction has finished and is responsible for:
 *   - writing exactly one FB_Job_Log__c row per run (Success or Failed),
 *   - re-enqueueing the job (same accounts, attempt + 1) when the run failed and less
 *     than 3 attempts have been made. Nothing is enqueued after the third failed attempt.
 */
public with sharing class ErpSyncFinalizer implements Finalizer {

    /** Job_Name__c value written to the log. */
    private static final String JOB_NAME = 'ErpAccountSyncJob';

    /** Status__c values. */
    private static final String STATUS_SUCCESS = 'Success';
    private static final String STATUS_FAILED = 'Failed';

    /** Maximum number of attempts in total (initial run + retries). */
    private static final Integer MAX_ATTEMPTS = 3;

    /** Length of the Error__c text field - longer messages are cut to this length. */
    private static final Integer MAX_ERROR_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    /**
     * @param accountIds Ids of the Accounts processed by the job.
     * @param attempt    Attempt number of the run this finalizer belongs to.
     */
    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = (accountIds == null) ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = (attempt == null) ? 1 : attempt;
    }

    /**
     * Called by the platform once the transaction is complete.
     *
     * @param context Provides the exception when the transaction failed, null otherwise.
     */
    public void execute(FinalizerContext context) {
        Exception failure = (context == null) ? null : context.getException();
        Boolean failed = (failure != null);

        // 1. Always log the run - success or failure.
        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Status__c = failed ? STATUS_FAILED : STATUS_SUCCESS,
            Attempt__c = attempt,
            Error__c = failed ? truncate(failure.getMessage()) : null
        );
        insert jobLog;

        // 2. Retry a failed run, but never more than MAX_ATTEMPTS times in total:
        //    after the third failed attempt nothing more is enqueued.
        if (failed && attempt < MAX_ATTEMPTS) {
            // Enqueued without a chain id so the retry runs in its own chain and is
            // never blocked by the chain that has just failed.
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }

    /**
     * Cuts the error message to the length of the Error__c field (255 characters).
     */
    private static String truncate(String message) {
        if (message == null) {
            return null;
        }
        if (message.length() > MAX_ERROR_LENGTH) {
            return message.substring(0, MAX_ERROR_LENGTH);
        }
        return message;
    }
}
