        System.assertNotEquals(selectorMock.requestedIds, null, 'The selector should receive the requested ids');
        System.assertEquals(selectorMock.requestedIds.size(), 1, 'Only the requested id should be passed on');
        System.assert(selectorMock.requestedIds.contains(original.Id), 'The requested id should be passed on');

