@IsTest
public class OpportunityForecastServiceTest {
    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_QUALIFICATION = 'Qualification';
    private static final String STAGE_PROPOSAL = 'Proposal';

    /**
     * The weighted amount (Amount * Probability / 100, rounded to 2 decimals) is
     * summed per StageName over the opportunities returned by the selector.
     */
    @IsTest
    static void weightedAmountByStage_sumsWeightedAmountsPerStage() {
        Id accountOne = fakeId('Account');
        Id accountTwo = fakeId('Account');
        Set<Id> accountIds = new Set<Id>{ accountOne, accountTwo };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountOne, STAGE_PROSPECTING, 1000.00, 50),
            buildOpportunity(accountOne, STAGE_PROSPECTING, 200.55, 33),
            buildOpportunity(accountTwo, STAGE_QUALIFICATION, 5000.00, 25),
            buildOpportunity(accountTwo, STAGE_PROPOSAL, 1200.00, 75)
        };

        startMocks(accountIds, opportunities);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(3, result.size(), 'One entry is expected per stage that has opportunities');
        Assert.areEqual(566.18, result.get(STAGE_PROSPECTING), '1000.00 * 50% + 200.55 * 33%');
        Assert.areEqual(1250.00, result.get(STAGE_QUALIFICATION), '5000.00 * 25%');
        Assert.areEqual(900.00, result.get(STAGE_PROPOSAL), '1200.00 * 75%');
    }

    /**
     * Opportunities without an Amount or without a Probability are ignored, so they
     * do not even create an entry for their stage.
     */
    @IsTest
    static void weightedAmountByStage_ignoresOpportunitiesMissingAmountOrProbability() {
        Id accountId = fakeId('Account');
        Set<Id> accountIds = new Set<Id>{ accountId };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_PROSPECTING, null, 50),
            buildOpportunity(accountId, STAGE_QUALIFICATION, 1000.00, null),
            buildOpportunity(accountId, STAGE_PROPOSAL, 1000.00, 40)
        };

        startMocks(accountIds, opportunities);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(1, result.size(), 'Only the stage of the complete opportunity is expected');
        Assert.isFalse(result.containsKey(STAGE_PROSPECTING), 'Opportunity without amount must be ignored');
        Assert.isFalse(
            result.containsKey(STAGE_QUALIFICATION),
            'Opportunity without probability must be ignored'
        );
        Assert.areEqual(400.00, result.get(STAGE_PROPOSAL), '1000.00 * 40%');
    }

    /**
     * A null set of account ids returns an empty map without calling the selector.
     */
    @IsTest
    static void weightedAmountByStage_returnsEmptyMapForNullAccountIds() {
        Set<Id> accountIds = null;

        // Trap: if the selector is called, opportunities are returned and the
        // result would not be empty.
        startMocks(accountIds, new List<Opportunity>{
            buildOpportunity(fakeId('Account'), STAGE_PROSPECTING, 1000.00, 50)
        });

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(0, result.size(), 'No weighted amount is expected for null account ids');
        Assert.isTrue(result.isEmpty(), 'The result must be empty for null account ids');
    }

    /**
     * An empty set of account ids returns an empty map without calling the selector.
     */
    @IsTest
    static void weightedAmountByStage_returnsEmptyMapForEmptyAccountIds() {
        Set<Id> accountIds = new Set<Id>();

        // Trap: if the selector is called, opportunities are returned and the
        // result would not be empty.
        startMocks(accountIds, new List<Opportunity>{
            buildOpportunity(fakeId('Account'), STAGE_PROSPECTING, 1000.00, 50)
        });

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(0, result.size(), 'No weighted amount is expected for empty account ids');
        Assert.isTrue(result.isEmpty(), 'The result must be empty for empty account ids');
    }

    /**
     * Creates the ApexMocks mock for IOpportunitiesSelector, registers it through
     * Application.Selector.setMock and stubs selectOpenByAccountIds.
     */
    private static void startMocks(Set<Id> accountIds, List<Opportunity> opportunities) {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        mocks.startStubbing();
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();
    }

    /**
     * Builds an in-memory (never persisted) opportunity with a fake id.
     */
    private static Opportunity buildOpportunity(
        Id accountId,
        String stageName,
        Decimal amount,
        Decimal probability
    ) {
        return new Opportunity(
            Id = fakeId('Opportunity'),
            Name = 'Test Opportunity ' + stageName,
            AccountId = accountId,
            StageName = stageName,
            Amount = amount,
            Probability = probability
        );
    }

    /**
     * Fake (never persisted) Id for the given object name, created with
     * fflib_IDGenerator. A deterministic fallback is used in case the generator
     * does not return a usable Id.
     */
    private static Id fakeId(String objectName) {
        String keyPrefix = Schema.getGlobalDescribe().get(objectName).getKeyPrefix();
        try {
            String candidate = (String) fflib_IDGenerator.generateId(objectName);
            if (candidate != null && candidate.length() == 18 && candidate.startsWith(keyPrefix)) {
                return (Id) candidate;
            }
        } catch (Exception e) {
            // Fall through to the deterministic fake id below.
        }
        return (Id) (keyPrefix + '000000000000001');
    }
}
