/**
 * Domain class for Opportunity.
 *
 * Encapsulates the business rules applied to Opportunity records on creation:
 *  - CloseDate defaults to today + 30 days when it is not supplied
 *  - Type defaults to 'New Customer' when it is not supplied
 *
 * Values already populated are always kept, and the defaults are applied on
 * insert only (never on update).
 */
public with sharing class Opportunities extends fflib_SObjectDomain {

    /**
     * Standard fflib constructor hook, used by fflib_SObjectDomain.triggerHandler()
     * to build the domain object for the records handed over by the trigger.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    /**
     * @param records The Opportunity records this domain operates on.
     */
    public Opportunities(List<SObject> records) {
        super(records);
    }

    /**
     * Applies the creation defaults. Invoked for inserts only.
     */
    public override void beforeInsert() {
        for (SObject record : getRecords()) {
            Opportunity opportunity = (Opportunity) record;

            // Default the close date to 30 days from today when it was not supplied.
            if (opportunity.CloseDate == null) {
                opportunity.CloseDate = Date.today().addDays(30);
            }

            // Default the opportunity type when it was not supplied.
            if (String.isBlank(opportunity.Type)) {
                opportunity.Type = 'New Customer';
            }
        }
    }
}
