    private static void assertFutureBirthdateRejected(Contact contact, Exception thrown) {
        List<Database.Error> errors = contact.getErrors();

        if (!errors.isEmpty()) {
            Boolean messageFound = false;
            for (Database.Error recordError : errors) {
                String message = recordError.getMessage();
                if (message != null && message.contains(Contacts.FUTURE_BIRTHDATE)) {
                    messageFound = true;
                    String fieldName = recordError.getField();
                    System.assert(
                        fieldName != null,
                        'The error should be reported on the Birthdate field'
                    );
                    System.assert(
                        fieldName.contains('Birthdate'),
                        'The error should be reported on the Birthdate field but was on: ' + fieldName
                    );
                }
            }
            System.assert(
                messageFound,
                'Expected the error "' + Contacts.FUTURE_BIRTHDATE + '" but got: ' + errors
            );
            return;
        }

        // The domain may surface the rejection by throwing instead of by
        // leaving a field error on the record.
        System.assert(
            thrown != null,
            'A Birthdate in the future should have been rejected with the error: '
                + Contacts.FUTURE_BIRTHDATE
        );
        System.assert(
            thrown.getMessage() != null && thrown.getMessage().contains(Contacts.FUTURE_BIRTHDATE),
            'Expected the error "' + Contacts.FUTURE_BIRTHDATE + '" but got: ' + thrown.getMessage()
        );
    }
