/**
 * Domain class for Opportunity.
 *
 * Business rules enforced here (both bulk safe, no SOQL is performed):
 *  1. Amount may never be negative (checked on insert and on update).
 *  2. On update, the Amount of an Opportunity whose Stage was already
 *     'Closed Won' *before* the update may not be changed.
 *     Closing an Opportunity as won while changing its Amount in the same
 *     update is allowed.
 *
 * The rules live in the fflib validation hooks, so they are executed
 * automatically by fflib_SObjectDomain.triggerHandler().
 * Every error is attached to the Amount field of the offending record only,
 * which means the remaining records of the same DML statement are still saved.
 */
public class Opportunities extends fflib_SObjectDomain {

    private static final String AMOUNT_FIELD = 'Amount';
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    private static final String ERROR_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    private static final String ERROR_AMOUNT_CHANGED_ON_WON = 'Amount cannot change on a won opportunity.';

    /**
     * fflib instantiates the domain through this inner Constructor class.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public Opportunities(List<SObject> records) {
        super(records);
    }

    ///////////////////////////////
    // fflib validation hooks
    ///////////////////////////////

    /**
     * Rule 1 applies to newly created Opportunities.
     */
    public override void validateCreate() {
        for (Opportunity opportunity : getOpportunities()) {
            validateAmountIsNotNegative(opportunity);
        }
    }

    /**
     * Rule 1 and rule 2 apply to updated Opportunities.
     */
    public override void validateUpdate() {
        for (Opportunity opportunity : getOpportunities()) {
            validateAmountIsNotNegative(opportunity);
            validateAmountIsNotChangedOnWonOpportunity(opportunity);
        }
    }

    ///////////////////////////////
    // Rules
    ///////////////////////////////

    /**
     * Amount cannot be negative.
     */
    private void validateAmountIsNotNegative(Opportunity opportunity) {
        if (opportunity.Amount != null && opportunity.Amount < 0) {
            addAmountError(opportunity, ERROR_NEGATIVE_AMOUNT);
        }
    }

    /**
     * The Amount of an Opportunity that was already Closed Won before the
     * update cannot be changed.
     */
    private void validateAmountIsNotChangedOnWonOpportunity(Opportunity opportunity) {
        Opportunity oldOpportunity = getOldOpportunity(opportunity);

        if (oldOpportunity == null) {
            // No old state available (nothing to compare against).
            return;
        }
        if (!STAGE_CLOSED_WON.equals(oldOpportunity.StageName)) {
            // The Opportunity was not won before the update: changing the
            // Amount (including closing it as won in the same update) is fine.
            return;
        }
        if (oldOpportunity.Amount == opportunity.Amount) {
            // Amount untouched.
            return;
        }

        addAmountError(opportunity, ERROR_AMOUNT_CHANGED_ON_WON);
    }

    ///////////////////////////////
    // Helpers
    ///////////////////////////////

    /**
     * The records of this domain, typed as Opportunity.
     */
    private List<Opportunity> getOpportunities() {
        List<Opportunity> opportunities = new List<Opportunity>();

        for (SObject record : getRecords()) {
            opportunities.add((Opportunity) record);
        }

        return opportunities;
    }

    /**
     * The pre update state of the Opportunity, taken from Trigger.oldMap.
     * This keeps the rule bulk safe and free of any SOQL.
     */
    private static Opportunity getOldOpportunity(Opportunity opportunity) {
        if (!Trigger.isUpdate || opportunity.Id == null) {
            return null;
        }

        Map<Id, SObject> oldRecords = Trigger.oldMap;

        if (oldRecords == null) {
            return null;
        }

        return (Opportunity) oldRecords.get(opportunity.Id);
    }

    /**
     * Registers the error through the fflib helper (so that it is captured in
     * fflib_SObjectDomain.Errors and can be asserted in unit tests) and makes
     * sure the message ends up on the Amount field of the offending record.
     * addError(..., false) is used on purpose: the offending record is
     * rejected while all other records of the same DML statement are saved.
     */
    private void addAmountError(Opportunity opportunity, String message) {
        error(message, opportunity, AMOUNT_FIELD);

        for (Database.Error recordError : opportunity.getErrors()) {
            if (AMOUNT_FIELD.equals(recordError.getField())
                && message.equals(recordError.getMessage())) {
                // The very same error has already been attached to the field.
                return;
            }
        }

        opportunity.addError(message, false);
    }
}
