/**
 * Selector for Opportunity.
 *
 * Every query is created through fflib's query factory, configured from this
 * selector (SObject type + field list), so the selector's configuration - and
 * therefore the org's standard user-context security rules - keep applying to
 * all queries issued by this class.
 *
 * Each method creates its own query factory instance so that conditions,
 * ordering and limits applied for one method never leak into another one.
 */
public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {

    /** Relationship field used to read the parent account's Name. */
    private static final String ACCOUNT_NAME_FIELD = 'Account.Name';

    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities of the given accounts.
     *
     * Ordering:
     *   1. Amount descending - opportunities without an Amount are returned last,
     *   2. CloseDate ascending (earliest first) for opportunities with equal Amount.
     *
     * At most `maxRecords` opportunities are returned and the whole result set is
     * retrieved with a single query. Each returned record also exposes the parent
     * account's Name through `opportunity.Account.Name`.
     *
     * @param accountIds the accounts whose open opportunities should be returned
     * @param maxRecords the maximum number of opportunities to return
     * @return the matching opportunities, never null
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Guard clauses: nothing to query for an empty request.
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // A dedicated query factory is used for this method only, so the ordering
        // and the limit applied here never affect the other methods of this
        // selector (which keep their default behaviour, e.g. ordering by Name).
        fflib_QueryFactory oppQueryFactory = new fflib_QueryFactory(getSObjectType())
            .selectFields(getSObjectFieldList())
            .withCondition('AccountId IN (' + buildIdList(accountIds) + ') AND IsClosed = false')
            .withOrdering('Amount DESC NULLS LAST, CloseDate ASC')
            .withLimit(maxRecords);

        // The parent account's Name is added to the SELECT clause so that callers
        // can use `opportunity.Account.Name` without running an extra query.
        String soql = addParentAccountName(oppQueryFactory.toString());

        // Single query, executed in the current user's context.
        return (List<Opportunity>) Database.query(soql);
    }

    /**
     * Builds a comma separated list of Id values that can be used in a SOQL
     * IN clause. Only Ids are copied, so the result is safe to inline.
     *
     * @param ids the Ids to render
     * @return the rendered Id list, e.g. `001000000000001AAA,001000000000002AAA`
     */
    private static String buildIdList(Set<Id> ids) {
        List<String> idValues = new List<String>();
        for (Id id : ids) {
            if (id != null) {
                idValues.add(String.valueOf(id));
            }
        }
        return String.join(idValues, ',');
    }

    /**
     * Adds the parent account's Name (`Account.Name`) to the SELECT clause of the
     * query that was created by the query factory.
     *
     * @param soql the query created by the query factory
     * @return the query including the parent account's Name in its SELECT clause
     */
    private static String addParentAccountName(String soql) {
        String upperCaseSoql = soql.toUpperCase();
        Integer fromIndex = upperCaseSoql.indexOf(' FROM ');

        // Defensive: if the query cannot be parsed, return it untouched.
        if (fromIndex < 0) {
            return soql;
        }

        String selectClause = soql.substring(0, fromIndex);
        if (!selectClause.toUpperCase().contains(ACCOUNT_NAME_FIELD.toUpperCase())) {
            selectClause = selectClause + ', ' + ACCOUNT_NAME_FIELD;
        }

        return selectClause + soql.substring(fromIndex);
    }
}
