/**
 * Selector for the Account queries issued by the credit team.
 *
 * Design decisions:
 * - Every query issued by this selector runs in user mode (WITH USER_MODE), so the
 *   platform enforces the running user's object, field and record access. A user that
 *   cannot read one of the selected fields (including a member of the Credit_Review
 *   field set) gets an exception instead of data the user is not allowed to see.
 * - The data access mode is a setting of the selector. It is configured by the no
 *   argument constructor, which is the constructor the Application selector factory
 *   uses, so every instance (however it is created) runs its queries in user mode.
 * - The members of the Credit_Review field set are resolved at runtime from the field
 *   set definition and are never hard coded, so administrators can add fields to the
 *   field set without any code change.
 */
public with sharing class AccountsSelector extends fflib_SObjectSelector {

    /** Name of the Account field set holding the fields reviewed by the credit team. */
    private static final String CREDIT_REVIEW_FIELD_SET = 'Credit_Review';

    /** SOQL clause that switches a query to user mode. */
    private static final String USER_MODE_CLAUSE = ' WITH USER_MODE';

    /** Cache of the runtime resolved Credit_Review field set members. */
    private static List<Schema.SObjectField> creditReviewFields;

    /** The data access mode applied to every query issued by this selector. */
    private AccountsDataAccess accountsDataAccess = AccountsDataAccess.USER_MODE;

    /**
     * The no argument constructor used by the Application selector factory.
     * It configures the selector so that every query it runs is in user mode.
     */
    public AccountsSelector() {
        setAccountsDataAccess(AccountsDataAccess.USER_MODE);
    }

    /** The data access modes supported by this selector. */
    public enum AccountsDataAccess {
        SYSTEM_MODE,
        USER_MODE
    }

    /**
     * Sets the data access mode used by every query issued by this selector.
     */
    public void setAccountsDataAccess(AccountsDataAccess accountsDataAccess) {
        this.accountsDataAccess = accountsDataAccess;
    }

    /**
     * @return the data access mode used by every query issued by this selector
     */
    public AccountsDataAccess getAccountsDataAccess() {
        return accountsDataAccess;
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    /**
     * The fields selected by every query: the base fields plus the members of the
     * Credit_Review field set, which are resolved at runtime so that administrators
     * can extend the field set without a deployment.
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        for (Schema.SObjectField field : getCreditReviewFields()) {
            if (!fields.contains(field)) {
                fields.add(field);
            }
        }
        return fields;
    }

    /**
     * Returns the Accounts with the given Ids, including the Credit_Review field set
     * fields, in user mode.
     */
    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Returns the Accounts with the given Ids together with their child Contacts.
     *
     * A single query is used so the accounts and their contacts are read with the same
     * user mode enforcement (object, field and record access). The selected contact
     * fields are taken from ContactsSelector, so both selectors always stay in sync
     * and there is a single source of truth for the contact field list.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        String contactFieldSelect = getFieldSelect(new ContactsSelector().getSObjectFieldList());
        String query =
            'SELECT ' + getFieldSelect(getSObjectFieldList()) +
            ', (SELECT ' + contactFieldSelect + ' FROM Contacts)' +
            ' FROM Account WHERE Id IN :accountIds' +
            getDataAccessClause();
        return (List<Account>) Database.query(query);
    }

    /**
     * fflib entry point used to read Accounts by Id.
     *
     * It is overridden so that every query issued through the fflib API of this
     * selector honours the selector's data access setting (user mode) as well.
     */
    public List<SObject> selectSObjectsById(Set<Id> ids) {
        if (ids == null || ids.isEmpty()) {
            return new List<SObject>();
        }
        String query =
            'SELECT ' + getFieldSelect(getSObjectFieldList()) +
            ' FROM Account WHERE Id IN :ids' +
            getDataAccessClause();
        return Database.query(query);
    }

    /**
     * @return the SOQL clause matching the configured data access mode
     */
    private String getDataAccessClause() {
        return accountsDataAccess == AccountsDataAccess.USER_MODE ? USER_MODE_CLAUSE : '';
    }

    /**
     * Builds the comma separated field list of a query.
     */
    private static String getFieldSelect(List<Schema.SObjectField> fields) {
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : fields) {
            fieldNames.add(field.getDescribe().getName());
        }
        return String.join(fieldNames, ', ');
    }

    /**
     * The fields of the Credit_Review field set, resolved from the field set
     * definition (never hard coded) and cached for the transaction.
     */
    private static List<Schema.SObjectField> getCreditReviewFields() {
        if (creditReviewFields == null) {
            List<Schema.SObjectField> resolved = new List<Schema.SObjectField>();
            Schema.FieldSet fieldSet = Schema.SObjectType.Account.fieldSets.getMap().get(CREDIT_REVIEW_FIELD_SET);
            if (fieldSet == null) {
                throw new System.QueryException(
                    'Field set ' + CREDIT_REVIEW_FIELD_SET + ' does not exist on Account'
                );
            }
            Map<String, Schema.SObjectField> accountFields = Schema.SObjectType.Account.fields.getMap();
            for (Schema.FieldSetMember member : fieldSet.getFields()) {
                Schema.SObjectField field = resolveField(accountFields, member.getFieldPath());
                if (field != null && !resolved.contains(field)) {
                    resolved.add(field);
                }
            }
            creditReviewFields = resolved;
        }
        return creditReviewFields;
    }

    /**
     * Resolves a field set member path to the Account field it refers to.
     */
    private static Schema.SObjectField resolveField(
        Map<String, Schema.SObjectField> accountFields,
        String fieldPath
    ) {
        if (fieldPath == null) {
            return null;
        }
        if (accountFields.containsKey(fieldPath)) {
            return accountFields.get(fieldPath);
        }
        // Relationship style paths (for example 'Contact.Name') resolve to their root field
        Integer separatorIndex = fieldPath.indexOf('.');
        if (separatorIndex > 0) {
            String rootField = fieldPath.substring(0, separatorIndex);
            if (accountFields.containsKey(rootField)) {
                return accountFields.get(rootField);
            }
        }
        return null;
    }
}
