/**
 * Escalates cases: flags them as escalated, raises their priority and creates a
 * follow-up Task for the case owner.
 *
 * All data access goes through the fflib selector factory and all persistence
 * goes through a single fflib unit of work, so the class is fully mockable
 * with fflib-apex-mocks (Application.Selector.setMock / Application.UnitOfWork.setMock).
 */
public with sharing class CaseEscalationService {
    /** Thrown when the escalation is requested without a usable reason. */
    public class EscalationException extends Exception {}

    private static final String CLOSED_STATUS = 'Closed';
    private static final String HIGH_PRIORITY = 'High';
    private static final String SUBJECT_PREFIX = 'Escalated: ';
    private static final Integer TASK_SUBJECT_MAX_LENGTH = 255;

    /**
     * @param caseIds Ids of the cases to escalate. Null/empty is a no-op.
     * @param reason  Mandatory reason; it becomes part of the Task subject.
     * @throws EscalationException when reason is blank.
     */
    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate first: nothing is read or written when the reason is missing.
        if (String.isBlank(reason)) {
            throw new EscalationException('Escalation reason is required.');
        }

        // Nothing to do for an empty request.
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        if (cases == null || cases.isEmpty()) {
            return;
        }

        Date activityDate = Date.today().addDays(1);
        String taskSubject = buildTaskSubject(reason);

        List<Case> casesToUpdate = new List<Case>();
        List<Task> tasksToCreate = new List<Task>();

        for (Case caseRecord : cases) {
            if (caseRecord == null || caseRecord.Id == null) {
                continue;
            }
            // Skip cases that are already closed ...
            if (CLOSED_STATUS.equalsIgnoreCase(caseRecord.Status)) {
                continue;
            }
            // ... and cases that have already been escalated.
            if (caseRecord.IsEscalated == true) {
                continue;
            }

            caseRecord.IsEscalated = true;
            caseRecord.Priority = HIGH_PRIORITY;
            casesToUpdate.add(caseRecord);

            Task escalationTask = new Task(
                Subject = taskSubject,
                WhatId = caseRecord.Id,
                OwnerId = caseRecord.OwnerId,
                ActivityDate = activityDate,
                Priority = HIGH_PRIORITY
            );
            tasksToCreate.add(escalationTask);
        }

        // No case needed escalation -> no unit of work, no commit.
        if (casesToUpdate.isEmpty()) {
            return;
        }

        fflib_UnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        for (Case caseRecord : casesToUpdate) {
            unitOfWork.registerDirty(caseRecord);
        }
        for (Task escalationTask : tasksToCreate) {
            unitOfWork.registerNew(escalationTask);
        }

        unitOfWork.commitWork();
    }

    private static String buildTaskSubject(String reason) {
        String subject = SUBJECT_PREFIX + reason.trim();
        return subject.length() > TASK_SUBJECT_MAX_LENGTH
            ? subject.substring(0, TASK_SUBJECT_MAX_LENGTH)
            : subject;
    }
}
```

Looking at the compile error, the deployed `fflib_SObjectUnitOfWork` does not expose a `Set<Schema.SObjectType>` constructor — the unit of work infers the SObject types from the records registered with it, so it is instantiated with its no-argument constructor and the types are declared implicitly by `registerNew(...)`.

The rest of the design stays intact: a single unit of work created inside the method, parents registered before children so the library can resolve `Contact.AccountId` from the in-memory `Account` instance, one `commitWork()` for the whole operation (one INSERT per type, so it stays bulk-safe), and the same `Account` instances returned with their Ids populated by the insert.

