```apex
/**
 * Closes won Opportunities and notifies Fulfilment by publishing a Deal_Won__e platform event.
 *
 * The Opportunity updates and the Deal_Won__e events are handled by a single fflib unit of work.
 * The unit of work performs the DML first and publishes the platform events only once that DML
 * has completed successfully, so Fulfilment can never hear about a deal that was not saved.
 * If anything fails, the transaction is rolled back, no event is published and the exception
 * propagates to the caller.
 */
public with sharing class OpportunityWinService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * Marks every Opportunity in the supplied set as Closed Won and publishes one Deal_Won__e
     * platform event for every Opportunity that was actually closed.
     *
     * @param opportunityIds Ids of the Opportunities to close as won. May be null or empty.
     * @return The number of Opportunities that were closed by this call.
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_UoW unitOfWork = Application.UnitOfWork.newInstance();
        Integer closedCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (STAGE_CLOSED_WON.equals(opportunity.StageName)) {
                // Already won: nothing to close, so no event is published for it.
                continue;
            }

            opportunity.StageName = STAGE_CLOSED_WON;
            opportunity.CloseDate = Date.today();

            // Register the update of the existing record. Nothing is written until commitWork().
            unitOfWork.registerSave(opportunity);

            // Register the event on the very same unit of work: the unit of work publishes it
            // only after the Opportunity updates have been committed successfully.
            unitOfWork.registerEvent(new Deal_Won__e(
                    Opportunity_Id__c = opportunity.Id,
                    Amount__c = opportunity.Amount
            ));

            closedCount++;
        }

        if (closedCount == 0) {
            // Nothing changed: there is nothing to commit and nothing to publish.
            return 0;
        }

        // Single commit for the updates and the events. If the save fails, the unit of work
        // throws, the transaction is rolled back and no Deal_Won__e is published.
        unitOfWork.commitWork();

        return closedCount;
    }
}
