/**
 * Normalizes Contact.Phone values so they can be pushed to the new dialer.
 *
 * Dialer format: digits only, optionally prefixed with a single leading '+'.
 *   '+44 (20) 7946-0018' -> '+442079460018'
 *   '020 7946 0018'      -> '02079460018'
 *
 * Behaviour
 * ---------
 * - Contacts without a phone are ignored.
 * - Contacts whose phone is already normalized are NOT updated (no pointless DML,
 *   no extra row locks, no trigger / flow re-run).
 * - Every contact is saved in a SINGLE Database.update(..., false) call, so one bad
 *   record (validation rule, trigger, required-field check) cannot block the others.
 * - The returned map holds one entry per contact that could NOT be saved, keyed by
 *   contact Id, with the first error message. An empty map means everything saved.
 *
 * Notes
 * -----
 * - All SOQL uses bind variables (no string concatenation), so the method is not
 *   vulnerable to SOQL injection.
 * - The query is chunked (200 ids per query) so the method stays safe even if it is
 *   called with more than 200 ids; keep the total number of records per call at or
 *   below the 10,000 DML row limit.
 * - `with sharing` is used so the class respects the running user's sharing rules.
 *   If it must run in system context, add `AccessLevel.USER_MODE`/SYSTEM_MODE
 *   explicitly rather than relying on the default.
 */
public with sharing class ContactPhoneCleanup {

    /** Maximum number of bind values per SOQL chunk (callers pass up to 200 ids). */
    private static final Integer QUERY_CHUNK_SIZE = 200;

    /** Regex matching every character that is not a digit. */
    private static final String NON_DIGIT = '[^0-9]';

    /**
     * Normalizes the phone of each contact in contactIds.
     *
     * @param contactIds Ids of the Contacts to normalize (may be null / contain nulls / duplicates).
     * @return Map of contact Id -> first error message for every contact that could not
     *         be saved. Empty map when all contacts were saved (or there was nothing to do).
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsById = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsById;
        }

        // De-duplicate and drop nulls: the same Id twice in the update list would fail
        // with DUPLICATE_DETAILS and would be reported as a bogus error.
        Set<Id> uniqueIds = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                uniqueIds.add(contactId);
            }
        }
        if (uniqueIds.isEmpty()) {
            return errorsById;
        }

        // Fetch only what is needed. Contacts without a phone are filtered out here.
        List<Contact> contacts = new List<Contact>();
        for (List<Id> idChunk : chunkIds(new List<Id>(uniqueIds))) {
            contacts.addAll([
                SELECT Id, Phone
                FROM Contact
                WHERE Id IN :idChunk
                  AND Phone != null
            ]);
        }

        // Build the records to save. Only the Id and the cleaned Phone are set,
        // so the update is a true partial update and never clobbers other fields.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : contacts) {
            String normalizedPhone = normalizePhone(contact.Phone);
            if (normalizedPhone == contact.Phone) {
                // Already in the dialer format (or nothing dialable to keep) -> no DML needed.
                continue;
            }
            contactsToUpdate.add(new Contact(Id = contact.Id, Phone = normalizedPhone));
        }

        if (contactsToUpdate.isEmpty()) {
            return errorsById;
        }

        // Single DML call, partial success: a record that fails validation or a trigger
        // must not prevent the remaining contacts from being saved.
        List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult saveResult = saveResults[i];
            if (!saveResult.isSuccess()) {
                errorsById.put(contactsToUpdate[i].Id, firstErrorMessage(saveResult));
            }
        }

        return errorsById;
    }

    /**
     * Strips every character that is not a digit and keeps at most one leading '+'.
     * Returns null when the value contains no digits at all (nothing dialable).
     */
    private static String normalizePhone(String phone) {
        if (String.isBlank(phone)) {
            return null;
        }

        String trimmed = phone.trim();
        Boolean hasLeadingPlus = trimmed.startsWith('+');

        // Remove every character that is not a digit (this also removes any '+'
        // that is not in the leading position).
        String digitsOnly = trimmed.replaceAll(NON_DIGIT, '');

        if (String.isEmpty(digitsOnly)) {
            // Nothing dialable left, e.g. 'ext. 123' -> the phone is cleared.
            return null;
        }

        return hasLeadingPlus ? '+' + digitsOnly : digitsOnly;
    }

    /** First error message of a failed save, with a safe fallback. */
    private static String firstErrorMessage(Database.SaveResult saveResult) {
        List<Database.Error> recordErrors = saveResult.getErrors();
        if (recordErrors.isEmpty()) {
            return 'Unknown save error';
        }
        Database.Error firstError = recordErrors[0];
        String message = firstError.getMessage();
        return String.isBlank(message)
            ? 'Save failed with status code: ' + firstError.getStatusCode()
            : message;
    }

    /** Splits a list of ids into chunks so a single query never exceeds the bind limit. */
    private static List<List<Id>> chunkIds(List<Id> ids) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> currentChunk = new List<Id>();

        for (Id recordId : ids) {
            currentChunk.add(recordId);
            if (currentChunk.size() == QUERY_CHUNK_SIZE) {
                chunks.add(currentChunk);
                currentChunk = new List<Id>();
            }
        }
        if (!currentChunk.isEmpty()) {
            chunks.add(currentChunk);
        }

        return chunks;
    }
}
```

