/**
 * Keeps Account.Rating in sync with the account's open Opportunity pipeline.
 *
 * All of the recalculation logic lives in AccountRatingService. This trigger only
 * works out WHICH accounts can be affected and hands them to the asynchronous
 * (@future) service method, so that saving Opportunities stays fast.
 *
 * Design notes:
 *  - One future call per trigger execution (not per Opportunity). Salesforce allows
 *    at most 50 future method calls per transaction, and a CPQ batch of 200
 *    Opportunities would blow that limit (and would fire several async jobs at the
 *    same Account row, which can end in UNABLE_TO_LOCK_ROW races).
 *  - Account Ids are de-duplicated, so an Account touched by 50 Opportunities is
 *    recalculated exactly once.
 *  - On update we only recalculate when something that can change the Rating changed
 *    (StageName, Amount or AccountId).
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {

        if (Trigger.isUpdate) {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

            Boolean stageChanged   = oldOpp.StageName != opp.StageName;
            Boolean amountChanged  = oldOpp.Amount != opp.Amount;
            Boolean accountChanged = oldOpp.AccountId != opp.AccountId;

            if (!stageChanged && !amountChanged && !accountChanged) {
                // Nothing that can change the Rating (e.g. a Description edit).
                continue;
            }

            if (accountChanged && oldOpp.AccountId != null) {
                // The Opportunity no longer contributes to the old Account's pipeline,
                // so that Account's Rating is stale too.
                accountIds.add(oldOpp.AccountId);
            }
        }

        if (opp.AccountId != null) {
            accountIds.add(opp.AccountId);
        }
    }

    if (accountIds.isEmpty()) {
        return;
    }

    // ONE asynchronous call for the whole batch.
    AccountRatingService.recalculate(accountIds);
}
