```apex
/**
 * CaseTrigger
 * ---------------------------------------------------------------------------
 * After-update trigger on Case that requests CSAT feedback for every case that
 * has just been closed (open -> closed) and that has a contact.
 *
 * Design notes
 *  - No DML and no SOQL in the trigger: it only reads Trigger.new / Trigger.oldMap
 *    and hands the work to Queueable Apex. A bulk close (mass close from a list
 *    view or a nightly API batch of up to 200 cases) therefore cannot exhaust
 *    CPU / heap / query limits in the user's transaction.
 *  - One job per case: every case is processed in its own queueable transaction,
 *    so a single failure can never affect the other cases.
 *  - The platform only allows 50 asynchronous jobs to be queued per transaction.
 *    The trigger therefore queues at most 49 per-case jobs and reserves the last
 *    slot for a continuation job (CaseSurveyJob with a List<Id>), which queues
 *    the remaining per-case jobs from the next transaction. Nothing is dropped.
 *  - Cases without a contact are ignored - no survey task is created for them.
 */
trigger CaseTrigger on Case (after update) {

    // Maximum number of asynchronous jobs that may be enqueued in one transaction.
    Integer maxJobsPerTransaction = 50;

    // ------------------------------------------------------------------
    // 1. Collect the cases that were just closed and that have a contact.
    // ------------------------------------------------------------------
    List<Case> newlyClosedCases = new List<Case>();

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);

        // Only a genuine open -> closed transition. Re-saving an already closed
        // case, or reopening one, must not trigger a survey.
        if (oldCase == null || oldCase.IsClosed || !newCase.IsClosed) {
            continue;
        }

        // No contact -> nobody to survey -> no task.
        if (newCase.ContactId == null) {
            continue;
        }

        newlyClosedCases.add(newCase);
    }

    // ------------------------------------------------------------------
    // 2. Queue one job per case, respecting the 50 jobs / transaction limit.
    // ------------------------------------------------------------------
    Integer total = newlyClosedCases.size();
    Integer index = 0;

    while (index < total) {
        Integer remaining = total - index;

        // If more cases are left than this transaction may queue, keep one slot
        // free for the continuation job.
        Boolean needsContinuation = remaining > maxJobsPerTransaction;
        Integer jobsThisTransaction = needsContinuation
            ? maxJobsPerTransaction - 1
            : remaining;

        // One job per case -> one transaction (and one failure domain) per case.
        for (Integer i = 0; i < jobsThisTransaction; i++) {
            Case closedCase = newlyClosedCases.get(index + i);
            System.enqueueJob(new CaseSurveyJob(closedCase.Id));
        }

        index += jobsThisTransaction;

        if (needsContinuation) {
            // Build the remainder without subList() (not available in Apex).
            List<Id> remainingCaseIds = new List<Id>();
            for (Integer i = index; i < total; i++) {
                remainingCaseIds.add(newlyClosedCases.get(i).Id);
            }

            // The continuation job queues the remaining per-case jobs in the
            // next transaction (and chains further continuations if needed).
            System.enqueueJob(new CaseSurveyJob(remainingCaseIds));
        }
    }
}
