```apex
/**
 * CaseSurveyJob
 * ---------------------------------------------------------------------------
 * Queueable job that creates the CSAT survey Task for a single closed Case.
 *
 *  - The job runs in its own transaction (one job per case), so a failure on
 *    one case never affects any other case.
 *  - The job re-reads the Case instead of trusting the trigger context, so it
 *    works from current data and never surveys a case that has been reopened
 *    or that lost its contact in the meantime.
 *  - The job is idempotent: if a CSAT survey task already exists for the case,
 *    nothing is created. This protects against platform retries of a job that
 *    failed after the insert.
 *  - A second constructor accepts a list of case ids. That variant does not
 *    create any task itself: it only enqueues the remaining per-case jobs from
 *    the next transaction. It exists because the platform allows a maximum of
 *    50 asynchronous jobs to be queued per transaction, so a bulk close of more
 *    than 50 cases has to be spread over several transactions.
 */
public with sharing class CaseSurveyJob implements Queueable {

    /** Prefix of the survey task subject. */
    private static final String SURVEY_SUBJECT_PREFIX = 'CSAT survey: ';

    /** Days between closing the case and the survey task being due. */
    private static final Integer SURVEY_DUE_IN_DAYS = 2;

    /** Status of the newly created task. */
    private static final String TASK_STATUS = 'Not Started';

    /** Maximum number of async jobs that may be enqueued in one transaction. */
    private static final Integer MAX_JOBS_PER_TRANSACTION = 50;

    /** The case this job has to survey (null for a continuation job). */
    private final Id caseId;

    /** Cases still to be enqueued (only set for a continuation job). */
    private final List<Id> pendingCaseIds;

    /**
     * Normal per-case job.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.pendingCaseIds = null;
    }

    /**
     * Continuation job: queues the remaining per-case jobs in a new transaction.
     */
    public CaseSurveyJob(List<Id> pendingCaseIds) {
        this.caseId = null;
        this.pendingCaseIds = pendingCaseIds;
    }

    public void execute(QueueableContext context) {
        if (this.pendingCaseIds != null) {
            enqueuePendingCases(this.pendingCaseIds);
            return;
        }

        createSurveyTask(this.caseId);
    }

    /**
     * Queues one job per case for the given ids, chaining continuation jobs
     * whenever the remaining ids do not fit into a single transaction.
     */
    private void enqueuePendingCases(List<Id> caseIds) {
        Integer total = caseIds.size();
        Integer index = 0;

        while (index < total) {
            Integer remaining = total - index;
            Boolean needsContinuation = remaining > MAX_JOBS_PER_TRANSACTION;
            Integer jobsThisTransaction = needsContinuation
                ? MAX_JOBS_PER_TRANSACTION - 1
                : remaining;

            // Still one job per case.
            for (Integer i = 0; i < jobsThisTransaction; i++) {
                System.enqueueJob(new CaseSurveyJob(caseIds.get(index + i)));
            }

            index += jobsThisTransaction;

            if (needsContinuation) {
                // Build the remainder without subList() (not available in Apex).
                List<Id> rest = new List<Id>();
                for (Integer i = index; i < total; i++) {
                    rest.add(caseIds.get(i));
                }
                System.enqueueJob(new CaseSurveyJob(rest));
            }
        }
    }

    /**
     * Creates the CSAT survey Task for a single case.
     */
    private void createSurveyTask(Id caseId) {
        if (caseId == null) {
            return;
        }

        // ------------------------------------------------------------------
        // 1. Re-read the case: the job may run some time after the close.
        // ------------------------------------------------------------------
        List<Case> surveyCases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (surveyCases.isEmpty()) {
            // Case was deleted, or is not visible to the running user.
            return;
        }

        Case surveyCase = surveyCases[0];

        // Case was reopened in the meantime -> no survey.
        if (!surveyCase.IsClosed) {
            return;
        }

        // No contact -> no survey task.
        if (surveyCase.ContactId == null) {
            return;
        }

        String expectedSubject = SURVEY_SUBJECT_PREFIX + surveyCase.CaseNumber;

        // ------------------------------------------------------------------
        // 2. Idempotency: never create a second survey task for the same case.
        // ------------------------------------------------------------------
        Boolean surveyAlreadyExists = false;

        try {
            List<Task> existingSurveys = [
                SELECT Id
                FROM Task
                WHERE WhatId = :surveyCase.Id
                  AND Subject = :expectedSubject
                LIMIT 1
            ];
            surveyAlreadyExists = !existingSurveys.isEmpty();
        } catch (QueryException e) {
            // The duplicate check is only a safety net: if it cannot be run,
            // the survey must still be created.
            System.debug(
                LoggingLevel.WARN,
                'CaseSurveyJob: duplicate check failed for case '
                + caseId + ' - ' + e.getMessage()
            );
        }

        if (surveyAlreadyExists) {
            return;
        }

        // ------------------------------------------------------------------
        // 3. Create the survey task.
        // ------------------------------------------------------------------
        Task surveyTask = new Task(
            Subject = expectedSubject,
            WhatId = surveyCase.Id,
            WhoId = surveyCase.ContactId,
            ActivityDate = Date.today().addDays(SURVEY_DUE_IN_DAYS),
            Status = TASK_STATUS
        );

        try {
            insert surveyTask;
        } catch (DmlException e) {
            // Log and re-throw: the job is then shown as failed in
            // Setup > Async Apex Jobs (and can be retried), while all other
            // cases keep running in their own transactions.
            System.debug(
                LoggingLevel.ERROR,
                'CaseSurveyJob: could not create CSAT survey task for case '
                + caseId + ' - ' + e.getMessage()
            );
            throw e;
        }
    }
}
```

**Assumptions**
- `IsClosed` is the standard read-only Case formula field derived from `Status`; it is used exactly as specified for the open → closed transition check (both in the trigger and as a re-validation in the job).
- `ActivityDate = today + 2 days` is computed when the job executes (`Date.today().addDays(2)`).
- The job is `with sharing` (secure default), so it respects the closing user's access to the case and contact. If surveys must be created even when the closing agent cannot read the case, switch the class to `without sharing` — that is the only deliberate trade-off here.

