```apex
/**
 * AccountCountrySync
 *
 * Keeps Contact.MailingCountry in step with the parent Account.BillingCountry
 * when the company moves its headquarters.
 *
 * Business rule
 * -------------
 * When an Account's BillingCountry changes, every Contact of that account whose
 * MailingCountry is either
 *     a) blank, or
 *     b) equal to the account's PREVIOUS BillingCountry
 * gets its MailingCountry set to the account's NEW BillingCountry.
 *
 * Contacts that carry a different MailingCountry (they work abroad) are never
 * touched, and accounts whose BillingCountry did not change are ignored.
 *
 * Bulk-safety
 * -----------
 *  - Exactly ONE SOQL statement, executed outside of any loop.
 *  - The query is scoped to the accounts that actually changed in this
 *    transaction and is filtered on the country, so it never loads the whole
 *    contact table (2.3M rows would breach the 50k row / 6MB heap limits).
 *  - Only the fields that must change are written (partial updates), and only
 *    for contacts that really need to change.
 *  - The number of DML rows is checked against the 10,000 row limit.
 */
public with sharing class AccountCountrySync {

    /** Raised when one or more contacts could not be synchronised. */
    public class AccountCountrySyncException extends Exception {}

    /** Maximum number of records that can be written in a single transaction. */
    private static final Integer MAX_DML_ROWS = 10000;

    /** Maximum number of individual failures quoted in the exception message. */
    private static final Integer MAX_REPORTED_FAILURES = 10;

    /**
     * Entry point for the trigger.
     *
     * @param newAccounts the post-update Account rows (Trigger.newMap)
     * @param oldAccounts the pre-update Account rows (Trigger.oldMap)
     */
    public static void run(Map<Id, Account> newAccounts, Map<Id, Account> oldAccounts) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccounts == null || oldAccounts.isEmpty()) {
            return;
        }

        // -------------------------------------------------------------------
        // 1. Delta: which accounts actually changed their country?
        //    Everything downstream is driven by this map, so accounts whose
        //    BillingCountry did not change are ignored completely.
        // -------------------------------------------------------------------
        Map<Id, String> previousCountryByAccount = new Map<Id, String>();
        Map<Id, String> currentCountryByAccount = new Map<Id, String>();

        for (Id accountId : newAccounts.keySet()) {
            Account oldAccount = oldAccounts.get(accountId);
            if (oldAccount == null) {
                continue; // defensive: no old image available
            }

            String previousCountry = oldAccount.BillingCountry;
            String currentCountry = newAccounts.get(accountId).BillingCountry;

            if (currentCountry == previousCountry) {
                continue; // country unchanged -> nothing to synchronise
            }

            previousCountryByAccount.put(accountId, previousCountry);
            currentCountryByAccount.put(accountId, currentCountry);
        }

        if (previousCountryByAccount.isEmpty()) {
            return;
        }

        // -------------------------------------------------------------------
        // 2. ONE query - only the candidate contacts of the accounts that
        //    changed. No query is issued inside a loop and the contact table is
        //    never loaded in full.
        //
        //    MailingCountry is a country picklist: a blank picklist is stored
        //    as NULL, so "= null" matches every blank contact. Contacts that
        //    carry a country are only returned when that country is one of the
        //    previous countries of the accounts we are syncing.
        //
        //    WITH USER_MODE enforces the running user's record-level access
        //    (e.g. the MDM integration user) and field-level access to
        //    Contact.MailingCountry.
        // -------------------------------------------------------------------
        Set<String> previousCountries = new Set<String>();
        for (String country : previousCountryByAccount.values()) {
            if (!String.isBlank(country)) {
                previousCountries.add(country);
            }
        }

        List<Contact> candidateContacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :previousCountryByAccount.keySet()
              AND (MailingCountry = null OR MailingCountry IN :previousCountries)
            WITH USER_MODE
        ];

        // -------------------------------------------------------------------
        // 3. Decide per contact whether it must follow the account.
        // -------------------------------------------------------------------
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : candidateContacts) {
            Id accountId = contact.AccountId;
            if (accountId == null || !currentCountryByAccount.containsKey(accountId)) {
                continue; // contact was re-parented / account not in scope
            }

            String previousCountry = previousCountryByAccount.get(accountId);
            String currentCountry = currentCountryByAccount.get(accountId);
            String contactCountry = contact.MailingCountry;

            // Does this contact follow the headquarters?
            Boolean followsHeadquarters = String.isBlank(contactCountry)
                || (previousCountry != null && contactCountry == previousCountry);

            if (!followsHeadquarters) {
                continue; // contact works abroad - leave it completely alone
            }

            if (contactCountry == currentCountry) {
                continue; // already in sync - no DML, no churn
            }

            // Partial update: only MailingCountry is written, so any concurrent
            // edit to other contact fields is not overwritten. A NULL
            // currentCountry deliberately clears the field, which keeps the
            // contact aligned with an account whose country was removed.
            Contact updated = new Contact(Id = contact.Id);
            updated.MailingCountry = currentCountry;
            contactsToUpdate.add(updated);
        }

        if (contactsToUpdate.isEmpty()) {
            return;
        }

        // -------------------------------------------------------------------
        // 4. DML - partial success handling so one bad contact does not hide
        //    the rest of the failures.
        // -------------------------------------------------------------------
        if (contactsToUpdate.size() > MAX_DML_ROWS) {
            throw new AccountCountrySyncException(
                'AccountCountrySync: ' + contactsToUpdate.size()
                + ' contacts need to be updated, which exceeds the ' + MAX_DML_ROWS
                + ' row DML limit of a single transaction. Reduce the integration batch size.'
            );
        }

        List<Database.SaveResult> results = Database.update(contactsToUpdate, false);

        List<String> failures = new List<String>();
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                Database.Error error = results[i].getErrors()[0];
                failures.add(
                    'Contact ' + contactsToUpdate[i].Id
                    + ' (MailingCountry -> "' + contactsToUpdate[i].MailingCountry + '"): '
                    + error.getStatusCode() + ' - ' + error.getMessage()
                );
            }
        }

        if (!failures.isEmpty()) {
            for (String failure : failures) {
                System.debug(LoggingLevel.ERROR, 'AccountCountrySync: ' + failure);
            }

            // Apex has no List.subList - copy the first MAX_REPORTED_FAILURES
            // entries into a new list instead.
            List<String> reportedFailures = new List<String>();
            Integer reportCount = Math.min(failures.size(), MAX_REPORTED_FAILURES);
            for (Integer i = 0; i < reportCount; i++) {
                reportedFailures.add(failures[i]);
            }
            String quotedFailures = String.join(reportedFailures, ' | ');

            // Throwing rolls the transaction back, which keeps accounts and
            // contacts consistent. Remove the throw if you prefer partial
            // success to be persisted (the errors are already logged above).
            throw new AccountCountrySyncException(
                'AccountCountrySync failed to synchronise ' + failures.size()
                + ' contact(s): ' + quotedFailures
            );
        }
    }
}
