export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    /** Id of the account the component is displayed on. */
    @api recordId;

    /** Resolved URL of the Case list view "My_Open_Cases" (empty until generated). */
    casesUrl;

    connectedCallback() {
        this.generateCasesUrl();
    }

    /**
     * Generates the URL of the "My_Open_Cases" Case list view using the
     * Lightning navigation service. The link is rendered only once the URL
     * has been generated.
     */
    generateCasesUrl() {
        let promise;
        try {
            promise = this[NavigationMixin.GenerateUrl]({
                type: 'standard__objectPage',
                attributes: {
                    objectApiName: 'Case',
                    actionName: 'list'
                },
                state: {
                    filterName: 'My_Open_Cases'
                }
            });
        } catch (error) {
            this.handleNavigationError('Error generating the "My_Open_Cases" list view URL.', error);
            return;
        }

        if (promise && typeof promise.then === 'function') {
            promise
                .then((url) => {
                    this.casesUrl = url;
                })
                .catch((error) => {
                    this.handleNavigationError(
                        'Error generating the "My_Open_Cases" list view URL.',
                        error
                    );
                });
        }
    }

    /**
     * Handles clicks on the quick action buttons.
     * @param {Event} event the click event
     */
    handleAction(event) {
        const action = event.currentTarget.dataset.action;

        switch (action) {
            case 'new-contact':
                this.navigate({
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Contact',
                        actionName: 'new'
                    },
                    state: {
                        defaultFieldValues: encodeDefaultFieldValues({
                            AccountId: this.recordId
                        })
                    }
                });
                break;

            case 'contacts':
                if (!this.recordId) {
                    return;
                }
                this.navigate({
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Account',
                        actionName: 'view',
                        recordId: this.recordId,
                        relationshipName: 'Contacts'
                    }
                });
                break;

            case 'edit':
                if (!this.recordId) {
                    return;
                }
                this.navigate({
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Account',
                        actionName: 'edit',
                        recordId: this.recordId
                    }
                });
                break;

            default:
                break;
        }
    }

    /**
     * Navigates using the Lightning navigation service.
     * @param {object} pageReference the page reference to navigate to
     */
    navigate(pageReference) {
        let promise;
        try {
            promise = this[NavigationMixin.Navigate](pageReference);
        } catch (error) {
            this.handleNavigationError('Navigation error.', error);
            return;
        }

        if (promise && typeof promise.then === 'function') {
            promise.catch((error) => {
                this.handleNavigationError('Navigation error.', error);
            });
        }
    }

    /**
     * Logs navigation errors.
     * @param {string} message the error message
     * @param {*} error the error details
     */
    handleNavigationError(message, error) {
        // eslint-disable-next-line no-console
        console.error(message, error);
    }
}
