const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

/**
 * The wire result is normally `{ data, error }`, but be defensive:
 * it can be `undefined` (no value emitted yet) or the raw payload.
 */
function normalizeWireResult(result) {
    if (result === null || result === undefined) {
        return { data: undefined, error: undefined };
    }
    if (Array.isArray(result)) {
        return { data: result, error: undefined };
    }
    if (typeof result === 'object') {
        if ('data' in result || 'error' in result) {
            return { data: result.data, error: result.error };
        }
        return { data: result, error: undefined };
    }
    return { data: undefined, error: undefined };
}

export default class AccountContactsTable extends LightningElement {
    /** Id of the Account the component is placed on. */
    @api recordId;

    columns = COLUMNS;

    /** Rows rendered by the datatable. */
    contacts;

    /** Draft (unsaved) edits, bound to the datatable through draft-values. */
    draftValues = [];

    /** Kept so the wired data can be refreshed with refreshApex. */
    wiredContactsResult;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.wiredContactsResult = result;
        const { data, error } = normalizeWireResult(result);
        if (data) {
            this.contacts = data;
        } else if (error) {
            this.contacts = undefined;
            this.showError('Error loading contacts', error);
        }
    }

    /**
     * Keep the component's draft values in sync with the datatable.
     */
    handleDraftChange(event) {
        const detail = event && event.detail ? event.detail : {};
        this.draftValues = detail.draftValues || [];
    }

    /**
     * Persist every draft row in parallel and wait for all of them to settle.
     */
    async handleSave(event) {
        const detail = event && event.detail ? event.detail : {};
        const drafts = detail.draftValues || [];

        if (drafts.length === 0) {
            return;
        }

        // Keep the drafts on the component while the save is in flight.
        this.draftValues = drafts;

        // One updateRecord call per draft row, all fired in parallel.
        const savePromises = drafts.map((draft) =>
            updateRecord({ fields: { ...draft } })
        );

        // Wait for every call to settle (fulfilled or rejected).
        const results = await Promise.allSettled(savePromises);
        const failure = results.find((result) => result.status === 'rejected');

        if (failure) {
            // Do not refresh the data and do not show the success toast.
            const reason = failure.reason;
            const message =
                reason && reason.body && reason.body.message
                    ? reason.body.message
                    : 'Unknown error while saving contacts.';
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Could not save contacts',
                    message: message,
                    variant: 'error'
                })
            );
            return;
        }

        // All drafts saved successfully.
        this.dispatchEvent(
            new ShowToastEvent({
                title: 'Contacts updated',
                variant: 'success'
            })
        );

        // Clear the draft values.
        this.draftValues = [];

        // Refresh the wired data.
        await this.refreshContacts();
    }

    /**
     * Re-run the wire and refresh the displayed contacts.
     */
    async refreshContacts() {
        if (!this.wiredContactsResult) {
            return;
        }
        try {
            await refreshApex(this.wiredContactsResult);
        } catch (e) {
            // Never let a refresh problem break the save flow.
        }
    }

    showError(title, error) {
        const message =
            error && error.body && error.body.message
                ? error.body.message
                : 'Unexpected error.';
        this.dispatchEvent(
            new ShowToastEvent({
                title: title,
                message: message,
                variant: 'error'
            })
        );
    }
}
