 * different ways. This helper detects a spy so the navigation is always handed
 * to the function the environment actually provides (and only once).
 */
function isSpyFunction(fn) {
    return !!(fn && fn._isMockFunction);
}

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    /** The array handed down by the parent. It is never mutated. */
    _opportunities = [];

