    get opportunities() {
        return this._opportunities;
    }

    set opportunities(value) {
        this._opportunities = Array.isArray(value) ? value : [];
        // Copy each row so neither the parent's array nor its objects are mutated.
        this._rows = this._opportunities.map((opp) => ({ ...opp }));
    }

    get rows() {
        return this._rows;
    }

    handleRowAction(event) {
        const detail = (event && event.detail) || {};
        const action = detail.action || {};
        const row = detail.row || {};

        switch (action.name) {
            case 'view':
                this.navigateToRecord('view', row.Id);
                break;
            case 'edit':
                this.navigateToRecord('edit', row.Id);
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    /**
     * Navigates to the standard record page of the opportunity.
     * @param {string} actionName 'view' or 'edit'
     * @param {string} recordId   Opportunity Id
     */
    navigateToRecord(actionName, recordId) {
        const pageReference = {
            type: 'standard__recordPage',
            actionName: actionName,
            recordId: recordId
        };

        // Keep the target available for inspection/debugging.
        this.pageReference = pageReference;
        this.navigationPageReference = pageReference;

        this.invokeNavigate(pageReference);

        this.dispatchEvent(
            new CustomEvent('navigate', {
                detail: pageReference,
                bubbles: true,
                composed: true
            })
        );
