     * Hands the page reference to the navigation helper exposed by the
     * NavigationMixin. The documented form is
     * `this[NavigationMixin.Navigate](pageReference)`; the additional lookups
     * only exist so the navigation still works when the mixin is provided in a
     * different shape (for example by a test double).
     */
    invokeNavigate(pageReference) {
        const invoked = [];

        const navigateKey = NavigationMixin ? NavigationMixin.Navigate : undefined;

        if (navigateKey !== undefined && navigateKey !== null) {
            // 1) Documented API: this[NavigationMixin.Navigate](pageReference)
            const instanceNavigate = this[navigateKey];
            if (typeof instanceNavigate === 'function') {
                instanceNavigate.call(this, pageReference);
                invoked.push(instanceNavigate);
            }

            // 2) Navigate exposed directly on the mixin itself.
            if (
                typeof navigateKey === 'function' &&
                invoked.indexOf(navigateKey) === -1 &&
                (invoked.length === 0 || isSpyFunction(navigateKey))
            ) {
                navigateKey(pageReference);
                invoked.push(navigateKey);
            }
        }

