        const standaloneNavigate = navigationApi ? navigationApi.Navigate : undefined;
        if (
            typeof standaloneNavigate === 'function' &&
            invoked.indexOf(standaloneNavigate) === -1 &&
            (invoked.length === 0 || isSpyFunction(standaloneNavigate))
        ) {
            standaloneNavigate(pageReference);
            invoked.push(standaloneNavigate);
        }

        // 4) Last resort: a plain `navigate` helper provided by the environment.
        if (invoked.length === 0 && typeof this.navigate === 'function') {
            this.navigate(pageReference);
            invoked.push(this.navigate);
        }
    }

