        const confirmed = await LightningConfirm.open({
            message: `Are you sure you want to delete the opportunity "${row.Name}"? This action cannot be undone.`,
            variant: 'headerless',
            label: 'Delete opportunity'
        });

        // The user dismissed the dialog - keep the row and do nothing else.
        if (!confirmed) {
            return;
        }

        try {
            const result = await deleteRecord(row.Id);

            // deleteRecord resolves with a result object; record level problems
            // are reported through isSuccess/errors instead of a rejection.
            if (result && result.isSuccess === false) {
                const firstError =
                    Array.isArray(result.errors) && result.errors.length > 0
                        ? result.errors[0]
