                this.showDeleteError(firstError);
                return;
            }

            this.removeRow(row.Id);

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    message: `Opportunity "${row.Name}" was deleted.`,
                    variant: 'success'
                })
            );
        } catch (error) {
            this.showDeleteError(error);
        }
    }

    removeRow(recordId) {
        // Reassign a new array so the table refreshes without touching the
        // array (or the row objects) owned by the parent component.
        this._rows = this._rows.filter((opp) => opp.Id !== recordId);
    }

    showDeleteError(error) {
        const message =
            (error && error.body && error.body.message) ||
            (error && error.message) ||
            'Unknown error';

        this.dispatchEvent(
            new ShowToastEvent({
                title: 'Delete failed',
                message: message,
                variant: 'error'
            })
        );
    }
