import { LightningElement, api } from 'lwc';

/**
 * StatusListbox
 * --------------
 * A single-select list box that follows the WAI-ARIA list box pattern:
 * the DOM focus always stays on the `<ul role="listbox">` element and the
 * "active" option is only *referenced* through `aria-activedescendant`.
 *
 * Keyboard support (handled on the list box itself):
 *   ArrowDown / ArrowUp  -> move the active option (no wrap-around)
 *   Home / End           -> jump to the first / last option
 *   Enter / Space        -> select the active option
 *   any other key        -> default browser behaviour is preserved (e.g. Tab)
 */

const KEY_ARROW_DOWN = 'ArrowDown';
const KEY_ARROW_UP = 'ArrowUp';
const KEY_HOME = 'Home';
const KEY_END = 'End';
const KEY_ENTER = 'Enter';
const KEY_SPACE = ' ';

// Used to build DOM ids that are unique per component instance.
let instanceCounter = 0;

export default class StatusListbox extends LightningElement {
    /**
     * Accessible name of the list box. Rendered as `aria-label`.
     * @type {string}
     */
    @api label = '';

    /**
     * The options to display: `[{ value, label }, ...]`.
     * @type {Array<{ value: any, label: string }>}
     */
    _options = [];

    /**
     * The currently selected value ('' when nothing is selected).
     * @type {any}
     */
    _value = '';

    /**
     * Index of the active option inside `_options`.
     * @type {number}
     */
    _activeIndex = 0;

    /**
     * Unique prefix used to build unique option ids.
     * @type {string}
     */
    _uid = `status-listbox-${++instanceCounter}`;

    /* ------------------------------------------------------------------ *
     * Public API
     * ------------------------------------------------------------------ */

    /**
     * The list of options to render.
     * @type {Array<{ value: any, label: string }>}
     */
    @api
    get options() {
        return this._options;
    }

    set options(options) {
        this._options = Array.isArray(options) ? options.slice() : [];
        this._syncActiveIndex();
    }

    /**
     * The selected value. The parent can change it at any time; the list box
     * then shows that selection and moves the active option to it.
     * @type {any}
     */
    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value === undefined || value === null ? '' : value;
        this._syncActiveIndex();
    }

    /* ------------------------------------------------------------------ *
     * Rendering helpers
     * ------------------------------------------------------------------ */

    /**
     * Options enriched with everything the template needs.
     * @type {Array<Object>}
     */
    get renderedOptions() {
        const selected = this._normalize(this._value);

        return this._options.map((option, index) => {
            const value = option ? option.value : '';
            const label =
                option && option.label !== undefined && option.label !== null ? option.label : value;
            const isSelected = this._normalize(value) === selected;
            const isActive = index === this._activeIndex;

            const styles = [];
            if (isSelected) {
                styles.push('font-weight: 600');
            }
            if (isActive) {
                styles.push('background-color: #f3f3f3', 'box-shadow: inset 0 0 0 2px #0176d3');
            }

            let className = 'slds-listbox__option';
            if (isSelected) {
                className += ' slds-is-selected';
            }
            if (isActive) {
                className += ' status-listbox__option_active';
            }

            return {
                value,
                label,
                id: this._optionId(index),
                selected: isSelected ? 'true' : 'false',
                className,
                style: styles.length ? `${styles.join('; ')};` : undefined
            };
        });
    }

    /**
     * Id of the active option, referenced by `aria-activedescendant`.
     * @type {string|undefined}
     */
    get activeDescendantId() {
        if (this._options.length === 0) {
            return undefined;
        }
        return this._optionId(this._clampIndex(this._activeIndex));
    }

    /* ------------------------------------------------------------------ *
     * Event handlers
     * ------------------------------------------------------------------ */

    /**
     * Keyboard interaction on the list box.
     * @param {KeyboardEvent} event
     */
    handleKeydown(event) {
        switch (event.key) {
            case KEY_ARROW_DOWN:
                event.preventDefault();
                this._setActiveIndex(this._activeIndex + 1);
                break;
            case KEY_ARROW_UP:
                event.preventDefault();
                this._setActiveIndex(this._activeIndex - 1);
                break;
            case KEY_HOME:
                event.preventDefault();
                this._setActiveIndex(0);
                break;
            case KEY_END:
                event.preventDefault();
                this._setActiveIndex(this._options.length - 1);
                break;
            case KEY_ENTER:
            case KEY_SPACE:
                event.preventDefault();
                this._selectActiveOption();
                break;
            default:
                // Every other key (Tab, printable characters, ...) keeps its
                // default behaviour.
                break;
        }
    }

    /**
     * Prevent the list box from losing focus when an option is clicked:
     * DOM focus must stay on the <ul role="listbox"> element.
     * @param {MouseEvent} event
     */
    handleOptionMouseDown(event) {
        event.preventDefault();
    }

    /**
     * Clicking an option selects it and makes it the active option.
     * @param {MouseEvent} event
     */
    handleOptionClick(event) {
        const index = this._indexOfOptionElement(event.currentTarget);
        if (index === -1) {
            return;
        }
        this._selectOption(index);
        this._focusListBox();
    }

    /* ------------------------------------------------------------------ *
     * Internals
     * ------------------------------------------------------------------ */

    /**
     * Move the active option without changing the selection.
     * @param {number} index
     */
    _setActiveIndex(index) {
        this._activeIndex = this._clampIndex(index);
    }

    /**
     * Select the active option.
     */
    _selectActiveOption() {
        if (this._options.length === 0) {
            return;
        }
        this._selectOption(this._clampIndex(this._activeIndex));
    }

    /**
     * Select the option at the given index and notify the parent.
     * @param {number} index
     */
    _selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }

        this._activeIndex = index;

        const value = option.value;
        if (this._normalize(value) === this._normalize(this._value)) {
            // Already selected: nothing changed, so no event is dispatched.
            return;
        }

        this._value = value;
        this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
    }

    /**
     * Keep the active option in sync with the selected value: the active
     * option is the selected one, or the first option when nothing is
     * selected.
     */
    _syncActiveIndex() {
        const index = this._options.findIndex(
            (option) => this._normalize(option && option.value) === this._normalize(this._value)
        );

        if (index !== -1) {
            this._activeIndex = index;
            return;
        }

        this._activeIndex = this._clampIndex(this._activeIndex);
    }

    /**
     * @param {number} index
     * @returns {number} the index clamped to the available options
     */
    _clampIndex(index) {
        const last = this._options.length - 1;
        if (last < 0) {
            return 0;
        }
        if (!Number.isFinite(index) || index < 0) {
            return 0;
        }
        if (index > last) {
            return last;
        }
        return index;
    }

    /**
     * @param {any} value
     * @returns {string} a comparable representation of a value
     */
    _normalize(value) {
        return value === undefined || value === null ? '' : String(value);
    }

    /**
     * @param {number} index
     * @returns {string} the DOM id of the option at the given index
     */
    _optionId(index) {
        return `${this._uid}-option-${index}`;
    }

    /**
     * Resolve the index of the option behind a rendered element.
     * @param {Element} element
     * @returns {number} the index, or -1 when it cannot be resolved
     */
    _indexOfOptionElement(element) {
        if (!element) {
            return -1;
        }

        const id = element.getAttribute('id') || '';
        const prefix = `${this._uid}-option-`;
        if (id.indexOf(prefix) === 0) {
            const index = parseInt(id.substring(prefix.length), 10);
            if (!Number.isNaN(index)) {
                return index;
            }
        }

        const value = element.getAttribute('data-value');
        return this._options.findIndex(
            (option) => this._normalize(option && option.value) === this._normalize(value)
        );
    }

    /**
     * Give the DOM focus back to the list box.
     */
    _focusListBox() {
        const listBox = this.template.querySelector('[role="listbox"]');
        if (listBox && typeof listBox.focus === 'function') {
            listBox.focus();
        }
    }
}
