/**
 * EmployerService
 *
 * Keeps the "current employer" of a donor in sync with the employer captured by the
 * donation / sign-up web form, on an org that runs NPSP in the Household Account
 * model with Affiliations enabled.
 *
 * For every contact passed in, after the call:
 *   - there is exactly one Current + Primary affiliation between the contact and the
 *     employer organization (no duplicate affiliation records are ever created),
 *   - the contact's Primary Affiliation lookup (Contact.npsp__Primary_Affiliation__c)
 *     points at that organization,
 *   - a previous primary employer is kept as a Former, non-primary affiliation that
 *     ended today (NPSP keeps the affiliation history consistent around the Primary /
 *     Status / End Date values written here),
 *   - the contact is NOT moved: the household AccountId is never touched,
 *   - the call is idempotent: if the organization already is the contact's primary
 *     affiliation, nothing is written at all.
 *
 * Bulk design (200 contacts in one call):
 *   - 2 SOQL queries (contacts, existing affiliations) - none inside a loop,
 *   - 2 DML statements (affiliations, contacts).
 */
public with sharing class EmployerService {

    /** NPSP affiliation status values used by this service. */
    private static final String STATUS_CURRENT = 'Current';
    private static final String STATUS_FORMER = 'Former';

    /**
     * Sets the current employer (NPSP affiliation) of every contact in the map.
     *
     * @param employerByContactId contact Id -> organization (employer) Account Id.
     *                            A null/empty map does nothing.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // ------------------------------------------------------------------
        // 0. Guard clauses / input normalisation
        // ------------------------------------------------------------------
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Map<Id, Id> requestedEmployers = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                requestedEmployers.put(contactId, orgId);
            }
        }
        if (requestedEmployers.isEmpty()) {
            return;
        }

        Set<Id> contactIds = requestedEmployers.keySet();

        // ------------------------------------------------------------------
        // 1. Read the current state - 2 SOQL queries
        // ------------------------------------------------------------------

        // Query 1: the contacts (household account + current primary affiliation).
        Map<Id, Contact> contactById = new Map<Id, Contact>([
            SELECT Id, AccountId, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        // Query 2: every affiliation the contacts already have.
        Map<Id, List<npe5__Affiliation__c>> affiliationsByContact =
            new Map<Id, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c affiliation : [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c,
                   npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
        ]) {
            if (!affiliationsByContact.containsKey(affiliation.npe5__Contact__c)) {
                affiliationsByContact.put(
                    affiliation.npe5__Contact__c,
                    new List<npe5__Affiliation__c>()
                );
            }
            affiliationsByContact.get(affiliation.npe5__Contact__c).add(affiliation);
        }

        // ------------------------------------------------------------------
        // 2. Work out the changes (no SOQL / DML inside the loop)
        // ------------------------------------------------------------------
        Date today = Date.today();

        // On some NPSP versions the contact lookup is maintained by NPSP itself and is
        // not directly writable - only write it when the field is updateable.
        Boolean canWritePrimaryAffiliation =
            Contact.npsp__Primary_Affiliation__c.getDescribe().isUpdateable();

        List<npe5__Affiliation__c> affiliationsToSave = new List<npe5__Affiliation__c>();
        List<Contact> contactsToSave = new List<Contact>();

        for (Id contactId : contactIds) {
            Contact contact = contactById.get(contactId);
            if (contact == null) {
                // The contact id is not valid any more - nothing we can do for it.
                continue;
            }
            Id orgId = requestedEmployers.get(contactId);

            List<npe5__Affiliation__c> existingAffiliations =
                affiliationsByContact.containsKey(contactId)
                    ? affiliationsByContact.get(contactId)
                    : new List<npe5__Affiliation__c>();

            // Split the existing records into "this employer" and "every other org".
            List<npe5__Affiliation__c> sameOrg = new List<npe5__Affiliation__c>();
            List<npe5__Affiliation__c> otherOrg = new List<npe5__Affiliation__c>();
            for (npe5__Affiliation__c affiliation : existingAffiliations) {
                if (affiliation.npe5__Organization__c == orgId) {
                    sameOrg.add(affiliation);
                } else {
                    otherOrg.add(affiliation);
                }
            }

            // The record we keep for the employer: prefer the one already flagged primary.
            npe5__Affiliation__c employerAffiliation = null;
            for (npe5__Affiliation__c affiliation : sameOrg) {
                if (employerAffiliation == null
                    || (affiliation.npe5__Primary__c == true
                        && employerAffiliation.npe5__Primary__c != true)) {
                    employerAffiliation = affiliation;
                }
            }

            if (employerAffiliation == null) {
                // No affiliation for this employer yet -> create one (Current + Primary).
                employerAffiliation = new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = STATUS_CURRENT,
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today
                );
                affiliationsToSave.add(employerAffiliation);
            } else if (employerAffiliation.npe5__Primary__c != true
                       || employerAffiliation.npe5__Status__c != STATUS_CURRENT) {
                // Re-use the existing record - never create a second one for the same
                // contact + organization - and make it Current + Primary again.
                employerAffiliation.npe5__Status__c = STATUS_CURRENT;
                employerAffiliation.npe5__Primary__c = true;
                employerAffiliation.npe5__EndDate__c = null;
                if (employerAffiliation.npe5__StartDate__c == null) {
                    employerAffiliation.npe5__StartDate__c = today;
                }
                affiliationsToSave.add(employerAffiliation);
            }

            // If historic duplicates for the same organization exist, only the record we
            // keep may stay primary.
            for (npe5__Affiliation__c duplicate : sameOrg) {
                if (duplicate.Id != employerAffiliation.Id && duplicate.npe5__Primary__c == true) {
                    duplicate.npe5__Primary__c = false;
                    affiliationsToSave.add(duplicate);
                }
            }

            // The previous primary employer becomes a Former, non-primary affiliation
            // that ended today.
            for (npe5__Affiliation__c previous : otherOrg) {
                if (previous.npe5__Primary__c == true) {
                    previous.npe5__Primary__c = false;
                    previous.npe5__Status__c = STATUS_FORMER;
                    previous.npe5__EndDate__c = today;
                    affiliationsToSave.add(previous);
                }
            }

            // The contact's primary affiliation lookup has to point at the employer.
            // Note: AccountId (the household account) is deliberately never changed.
            if (canWritePrimaryAffiliation && contact.npsp__Primary_Affiliation__c != orgId) {
                contact.npsp__Primary_Affiliation__c = orgId;
                contactsToSave.add(contact);
            }
        }

        // ------------------------------------------------------------------
        // 3. Persist - 2 DML statements
        // ------------------------------------------------------------------
        Database.DmlOptions dmlOptions = new Database.DmlOptions();
        dmlOptions.allOrNone = false;

        // DML 1 - affiliations. Database.save() updates the records that already have
        // an Id and inserts the new ones, so a single statement covers both cases and
        // the "no duplicate affiliation" rule is kept (we never insert a second record
        // for a contact + organization that already has one).
        if (!affiliationsToSave.isEmpty()) {
            List<String> errors = new List<String>();
            for (Database.SaveResult result : Database.save(affiliationsToSave, dmlOptions)) {
                if (!result.isSuccess()) {
                    for (Database.Error error : result.getErrors()) {
                        errors.add(error.getStatusCode() + ' - ' + error.getMessage());
                    }
                }
            }
            if (!errors.isEmpty()) {
                throw new EmployerServiceException(
                    'EmployerService could not save the employer affiliations: '
                    + buildMessage(errors)
                );
            }
        }

        // DML 2 - contacts. Done after the affiliation DML so that NPSP's own
        // affiliation automation (which also refreshes this lookup) cannot overwrite
        // the value written here.
        if (!contactsToSave.isEmpty()) {
            List<String> errors = new List<String>();
            for (Database.SaveResult result : Database.update(contactsToSave, dmlOptions)) {
                if (!result.isSuccess()) {
                    for (Database.Error error : result.getErrors()) {
                        errors.add(error.getStatusCode() + ' - ' + error.getMessage());
                    }
                }
            }
            if (!errors.isEmpty()) {
                // NPSP normally keeps this lookup in sync with the primary affiliation,
                // so a failure here is logged rather than fatal for the whole batch.
                System.debug(
                    LoggingLevel.WARN,
                    'EmployerService: could not update the primary affiliation lookup: '
                    + buildMessage(errors)
                );
            }
        }
    }

    /** Joins the collected error messages into one readable string. */
    private static String buildMessage(List<String> errors) {
        String result = '';
        for (String error : errors) {
            if (result.length() > 0) {
                result += ' | ';
            }
            result += error;
        }
        return result;
    }

    /** Exception raised by EmployerService when the affiliation data cannot be saved. */
    public class EmployerServiceException extends Exception {}
}
