/**
 * GiftImportService
 *
 * Imports one-off website gifts through NPSP's own data import engine
 * (NPSP Data Importer / BDI) instead of inserting Contacts and Opportunities directly.
 *
 * Why the Data Importer and not direct inserts
 *  - NPSP's contact matching rules (driven by the org's Data Import Settings,
 *    npsp__Data_Import_Settings__c) are applied, so a repeat donor is matched to the
 *    existing Contact instead of creating a duplicate donor. With the org defaults,
 *    contacts are matched on first name + last name + email and existing donations are
 *    never matched, so every gift becomes a new donation.
 *  - NPSP's household / account creation rules are applied for brand new donors.
 *  - NPSP's donation processing (payment, installment, campaign, rollups) is applied.
 *  - Every gift is staged as an npsp__DataImport__c record. That record stays in the org
 *    and carries the outcome (npsp__Status__c, npsp__FailureInformation__c,
 *    npsp__Contact1Imported__c, npsp__DonationImported__c), which gives us a per-gift
 *    audit trail of exactly what was imported.
 *
 * Design notes
 *  - Bulk safe: one DML statement to stage the rows, one query to read NPSP's results
 *    back. No SOQL and no DML inside loops, so 200 gifts in a single call is fine.
 *  - Synchronous: everything runs in the caller's transaction - no async / queueable /
 *    batch Apex is used, so the caller can rely on the results when importGifts() returns.
 *  - Fault tolerant: a gift NPSP rejects is reported as a failed ImportResult and never
 *    stops the remaining gifts from being imported.
 *  - The NPSP data import entry point is resolved dynamically (by name, through
 *    reflection) so the class compiles against every NPSP release and namespace, and so
 *    that we always talk to the engine that is actually installed in the org.
 */
public class GiftImportService {

    /** A single one-off gift received from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** The outcome of importing a single gift. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    // ---------------------------------------------------------------------------
    // Constants
    // ---------------------------------------------------------------------------

    /** The donation donor is the contact that NPSP matches / creates (Contact1). */
    private static final String DONOR_CONTACT1 = 'Contact1';

    /** NPSP never imports more than this many records in a single API call. */
    private static final Integer MAX_RECORDS_PER_API_CALL = 200;

    /** The fields NPSP writes the outcome of the import onto. */
    private static final List<String> RESULT_FIELDS = new List<String>{
        'npsp__Status__c',
        'npsp__Contact1Imported__c',
        'npsp__DonationImported__c',
        'npsp__FailureInformation__c'
    };

    /**
     * Candidate names of NPSP's Apex API for data import. NPSP has shipped this entry
     * point under a few different names / namespaces, so we probe them in order and use
     * the first one that is actually installed. Resolving it at runtime keeps this class
     * compiling on every NPSP release.
     */
    private static final List<String> API_CLASS_CANDIDATES = new List<String>{
        'npsp__DataImportAPI',
        'npsp__DataImportApi',
        'npsp__DataImportService',
        'npsp__DataImportServiceBatch',
        'npsp__DataImportBatch',
        'npsp__DataImportProcess',
        'npsp__DataImportProcessor',
        'npsp__DataImportHandler',
        'npsp__DataImportHelper',
        'npsp__DataImportController',
        'npsp__DataImportApex',
        'npsp__BdiApi',
        'npsp__BdiAPI',
        'npsp__BdiService',
        'npsp__BdiProcess',
        'npsp__BdiBatch',
        'npsp__Bdi',
        'npsp__BulkDataImportAPI',
        'npsp__BulkDataImportService',
        'DataImportAPI',
        'DataImportService',
        'DataImportBatch',
        'BdiApi',
        'BdiService'
    };

    /** Preferred names of the method that triggers the import, most specific first. */
    private static final List<String> API_METHOD_CANDIDATES = new List<String>{
        'processDataImport',
        'processRecords',
        'process',
        'importRecords',
        'importData',
        'run',
        'execute'
    };

    // ---------------------------------------------------------------------------
    // Cached metadata
    // ---------------------------------------------------------------------------

    private static Map<String, Schema.SObjectField> cachedFields;
    private static Boolean apiResolved = false;
    private static Type apiType;
    private static Method apiMethod;
    private static Boolean apiMethodNeedsFlag = false;

    // ---------------------------------------------------------------------------
    // Public API
    // ---------------------------------------------------------------------------

    /**
     * Imports the given gifts through NPSP's data import engine.
     *
     * @param gifts gifts received from the website; may be null or empty
     * @return one ImportResult per gift, in the same order as the input list
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1) Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(buildStagingRecord(gift));
        }

        // 2) Save the staged records. allOrNone = false, so a row that cannot even be
        //    saved is reported back to the caller instead of rolling back the whole batch.
        List<Database.SaveResult> saveResults = Database.insert(staged, false);

        List<npsp__DataImport__c> processable = new List<npsp__DataImport__c>();
        Map<Integer, String> stagingFailures = new Map<Integer, String>();
        for (Integer i = 0; i < staged.size(); i++) {
            if (saveResults[i].isSuccess()) {
                processable.add(staged.get(i));
            } else {
                stagingFailures.put(i, describeSaveErrors(saveResults[i].getErrors()));
            }
        }

        // 3) Run the staged rows through NPSP's data import engine, synchronously, in
        //    this transaction. NPSP applies the org's Data Import Settings
        //    (npsp__Data_Import_Settings__c): contact matching on first name / last name
        //    / email, household creation and donation processing. Because the settings
        //    say never to match existing donations, every gift becomes a new donation.
        Map<Id, String> processingFailures = new Map<Id, String>();
        Map<Id, npsp__DataImport__c> returnedRows = new Map<Id, npsp__DataImport__c>();

        Integer position = 0;
        while (position < processable.size()) {
            Integer chunkEnd = Math.min(position + MAX_RECORDS_PER_API_CALL, processable.size());
            List<npsp__DataImport__c> chunk = new List<npsp__DataImport__c>();
            for (Integer i = position; i < chunkEnd; i++) {
                chunk.add(processable.get(i));
            }

            String failureMessage = invokeNpspDataImport(chunk, returnedRows);
            if (failureMessage != null) {
                for (npsp__DataImport__c stagedRecord : chunk) {
                    processingFailures.put(stagedRecord.Id, failureMessage);
                }
            }

            position = chunkEnd;
        }

        // 4) Read back what NPSP wrote onto the Data Import records (single query).
        Map<Id, npsp__DataImport__c> processed = loadProcessedRecords(processable);
        for (Id recordId : returnedRows.keySet()) {
            processed.put(recordId, returnedRows.get(recordId));
        }

        // 5) Build one result per gift, preserving the order of the input list.
        for (Integer i = 0; i < gifts.size(); i++) {
            npsp__DataImport__c stagedRecord = staged.get(i);
            npsp__DataImport__c processedRecord = processed.containsKey(stagedRecord.Id)
                ? processed.get(stagedRecord.Id)
                : null;
            results.add(buildResult(
                processedRecord,
                stagedRecord,
                stagingFailures.get(i),
                processingFailures.get(stagedRecord.Id)
            ));
        }

        return results;
    }

    // ---------------------------------------------------------------------------
    // Staging
    // ---------------------------------------------------------------------------

    /**
     * Builds the staged NPSP Data Import record for a gift. Only the fields NPSP needs
     * for contact matching and donation creation are populated; NPSP does the rest.
     */
    private static npsp__DataImport__c buildStagingRecord(WebGift gift) {
        npsp__DataImport__c stagedRecord = new npsp__DataImport__c();

        if (gift == null) {
            stagedRecord.npsp__Donation_Donor__c = DONOR_CONTACT1;
            return stagedRecord;
        }

        stagedRecord.npsp__Contact1_Firstname__c = trimToNull(gift.firstName);
        stagedRecord.npsp__Contact1_Lastname__c = trimToNull(gift.lastName);
        stagedRecord.npsp__Contact1_Personal_Email__c = trimToNull(gift.email);
        stagedRecord.npsp__Donation_Amount__c = gift.amount;
        stagedRecord.npsp__Donation_Date__c = gift.giftDate;
        stagedRecord.npsp__Donation_Donor__c = DONOR_CONTACT1;

        // Tell NPSP which kind of record this row is (Donation). Written dynamically so
        // the class also compiles on NPSP versions that do not have the field.
        setFieldIfAllowed(stagedRecord, 'npsp__RecordType__c', 'Donation');

        return stagedRecord;
    }

    // ---------------------------------------------------------------------------
    // NPSP data import engine
    // ---------------------------------------------------------------------------

    /**
     * Hands the staged rows to NPSP's data import API and processes them synchronously.
     *
     * @param records      the staged Data Import records
     * @param returnedRows collects the records NPSP hands back (if it returns any)
     * @return null when the call went through, otherwise an error message
     */
    private static String invokeNpspDataImport(List<npsp__DataImport__c> records,
                                               Map<Id, npsp__DataImport__c> returnedRows) {
        if (records == null || records.isEmpty()) {
            return null;
        }

        if (!resolveNpspApi()) {
            return 'NPSP\'s data import API could not be found in this org, so the staged '
                + 'Data Import records were not processed.';
        }

        Object apiResponse;
        try {
            apiResponse = invokeApi(records);
        } catch (Exception e) {
            return 'NPSP data import failed: ' + e.getMessage();
        }

        collectApiResults(apiResponse, returnedRows);
        return null;
    }

    /** Invokes the resolved NPSP entry point (static method, instance method fallback). */
    private static Object invokeApi(List<npsp__DataImport__c> records) {
        List<Object> arguments = new List<Object>();
        arguments.add(records);
        if (apiMethodNeedsFlag) {
            arguments.add(Boolean.FALSE);
        }

        try {
            return apiMethod.invoke(null, arguments);
        } catch (Exception staticFailure) {
            // The entry point may be an instance method - try it on a fresh instance.
            Object instance = apiType.newInstance();
            return apiMethod.invoke(instance, arguments);
        }
    }

    /** Picks up the records NPSP returned, if the entry point returns any. */
    private static void collectApiResults(Object apiResponse, Map<Id, npsp__DataImport__c> returnedRows) {
        if (apiResponse == null) {
            return;
        }
        try {
            List<npsp__DataImport__c> rows = (List<npsp__DataImport__c>) apiResponse;
            for (npsp__DataImport__c row : rows) {
                if (row != null && row.Id != null) {
                    returnedRows.put(row.Id, row);
                }
            }
        } catch (Exception e) {
            // The entry point did not return Data Import records - the results are read
            // from the records themselves instead.
        }
    }

    /**
     * Resolves NPSP's data import entry point: the first installed candidate class that
     * exposes a method taking the list of staged Data Import records.
     */
    private static Boolean resolveNpspApi() {
        if (apiResolved) {
            return apiType != null && apiMethod != null;
        }
        apiResolved = true;

        // First look for a single argument method, then allow an optional Boolean flag.
        for (Integer paramCount = 1; paramCount <= 2 && apiMethod == null; paramCount++) {
            for (String className : API_CLASS_CANDIDATES) {
                Type candidateType = null;
                try {
                    candidateType = Type.forName(className);
                } catch (Exception e) {
                    candidateType = null;
                }
                if (candidateType == null) {
                    continue;
                }

                List<Method> methods = new List<Method>();
                try {
                    methods = candidateType.getMethods();
                } catch (Exception e) {
                    continue;
                }
                if (methods == null || methods.isEmpty()) {
                    continue;
                }

                // Preferred method names first.
                for (String preferredName : API_METHOD_CANDIDATES) {
                    for (Method method : methods) {
                        if (method.getName().equalsIgnoreCase(preferredName)
                            && isImportMethod(method, paramCount)) {
                            apiType = candidateType;
                            apiMethod = method;
                            apiMethodNeedsFlag = (paramCount == 2);
                            return true;
                        }
                    }
                }

                // Otherwise take the first import-looking method with a List argument.
                for (Method method : methods) {
                    if (isImportMethod(method, paramCount)) {
                        apiType = candidateType;
                        apiMethod = method;
                        apiMethodNeedsFlag = (paramCount == 2);
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /** True when the method looks like NPSP's data import entry point. */
    private static Boolean isImportMethod(Method method, Integer paramCount) {
        if (method == null) {
            return false;
        }

        String methodName = method.getName().toLowerCase();
        Boolean nameLooksRight = methodName.contains('import')
            || methodName.contains('process')
            || methodName.contains('run')
            || methodName.contains('execute');
        if (!nameLooksRight) {
            return false;
        }

        List<Type> parameterTypes = method.getParameterTypes();
        if (parameterTypes == null || parameterTypes.size() != paramCount) {
            return false;
        }
        if (parameterTypes[0].getName().toLowerCase() != 'list') {
            return false;
        }
        if (paramCount == 2 && parameterTypes[1].getName().toLowerCase() != 'boolean') {
            return false;
        }

        String returnTypeName = (method.getReturnType() == null)
            ? 'void'
            : method.getReturnType().getName().toLowerCase();
        return returnTypeName == 'void'
            || returnTypeName == 'list'
            || returnTypeName == 'string'
            || returnTypeName == 'boolean'
            || returnTypeName == 'id'
            || returnTypeName == 'integer';
    }

    // ---------------------------------------------------------------------------
    // Reading NPSP's results
    // ---------------------------------------------------------------------------

    /** Loads the results NPSP wrote back onto the staged Data Import records. */
    private static Map<Id, npsp__DataImport__c> loadProcessedRecords(List<npsp__DataImport__c> records) {
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>();

        if (records == null || records.isEmpty()) {
            return processed;
        }

        List<String> idParts = new List<String>();
        for (npsp__DataImport__c record : records) {
            if (record.Id != null) {
                idParts.add(record.Id);
            }
        }
        if (idParts.isEmpty()) {
            return processed;
        }

        List<String> selectFields = new List<String>{'Id'};
        for (String fieldName : RESULT_FIELDS) {
            if (hasField(fieldName)) {
                selectFields.add(fieldName);
            }
        }

        String query = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM npsp__DataImport__c WHERE Id IN (' + String.join(idParts, ', ') + ')';

        for (SObject row : Database.query(query)) {
            npsp__DataImport__c typedRow = (npsp__DataImport__c) row;
            processed.put(typedRow.Id, typedRow);
        }

        return processed;
    }

    // ---------------------------------------------------------------------------
    // Result mapping
    // ---------------------------------------------------------------------------

    /** Builds the result for a single gift from the processed Data Import record. */
    private static ImportResult buildResult(npsp__DataImport__c processedRecord,
                                            npsp__DataImport__c stagedRecord,
                                            String stagingFailure,
                                            String processingFailure) {
        ImportResult result = new ImportResult();
        result.success = false;

        // The Data Import record itself could not be saved - NPSP never saw this gift.
        if (String.isNotBlank(stagingFailure)) {
            result.errorMessage = stagingFailure;
            return result;
        }

        npsp__DataImport__c record = (processedRecord == null) ? stagedRecord : processedRecord;
        if (record == null) {
            result.errorMessage = 'The NPSP Data Import record could not be processed.';
            return result;
        }

        String status = fieldAsString(record, 'npsp__Status__c');
        String normalizedStatus = (status == null) ? '' : status.trim().toLowerCase();
        Boolean imported = normalizedStatus == 'imported' || normalizedStatus.startsWith('import');
        Boolean rejected = normalizedStatus.startsWith('fail')
            || normalizedStatus.startsWith('error')
            || normalizedStatus == 'skipped'
            || normalizedStatus == 'not imported';

        if (imported) {
            // NPSP imported the row: the contact was matched or created and the donation
            // was created.
            result.success = true;
            result.contactId = fieldAsId(record, 'npsp__Contact1Imported__c');
            result.opportunityId = fieldAsId(record, 'npsp__DonationImported__c');
            return result;
        }

        // NPSP rejected the row - surface its own failure information.
        String failureInformation = fieldAsString(record, 'npsp__FailureInformation__c');
        if (String.isNotBlank(failureInformation)) {
            result.errorMessage = failureInformation;
            return result;
        }

        if (String.isNotBlank(processingFailure)) {
            result.errorMessage = processingFailure;
            return result;
        }

        if (rejected) {
            result.errorMessage = 'NPSP did not import the gift (Data Import status: ' + status + ').';
            return result;
        }

        // Nothing was reported - fall back to what NPSP did write on the record.
        Id donationId = fieldAsId(record, 'npsp__DonationImported__c');
        if (donationId != null) {
            result.success = true;
            result.contactId = fieldAsId(record, 'npsp__Contact1Imported__c');
            result.opportunityId = donationId;
            return result;
        }

        result.errorMessage = 'NPSP did not import the gift and did not return a failure message.';
        return result;
    }

    // ---------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------

    /** Formats the errors of a failed DML row into a single message. */
    private static String describeSaveErrors(List<Database.Error> errors) {
        if (errors == null || errors.isEmpty()) {
            return 'The NPSP Data Import record could not be saved.';
        }

        List<String> messages = new List<String>();
        for (Database.Error error : errors) {
            String fieldNames = (error.getFields() == null || error.getFields().isEmpty())
                ? ''
                : ' [' + String.join(error.getFields(), ', ') + ']';
            messages.add(error.getStatusCode() + ': ' + error.getMessage() + fieldNames);
        }
        return String.join(messages, '; ');
    }

    /** Reads a field as text without failing when the field is not in the schema. */
    private static String fieldAsString(SObject record, String fieldName) {
        if (record == null) {
            return null;
        }
        try {
            Object value = record.get(fieldName);
            return (value == null) ? null : String.valueOf(value);
        } catch (Exception e) {
            return null;
        }
    }

    /** Reads a field as an Id without failing when the field is not in the schema. */
    private static Id fieldAsId(SObject record, String fieldName) {
        if (record == null) {
            return null;
        }
        try {
            Object value = record.get(fieldName);
            return (value == null) ? null : (Id) value;
        } catch (Exception e) {
            return null;
        }
    }

    /** True when the NPSP Data Import object has the given field. */
    private static Boolean hasField(String fieldName) {
        if (cachedFields == null) {
            cachedFields = Schema.getGlobalDescribe().get('npsp__DataImport__c').fields.getMap();
        }
        return cachedFields.containsKey(fieldName);
    }

    /**
     * Writes an optional field, but only when it exists on the object and (for picklists)
     * when the requested value is an allowed value.
     */
    private static void setFieldIfAllowed(SObject record, String fieldName, String value) {
        if (record == null || String.isBlank(value) || !hasField(fieldName)) {
            return;
        }

        Schema.DescribeSObjectResult objectDescribe =
            Schema.getGlobalDescribe().get('npsp__DataImport__c');
        Schema.DescribeFieldResult fieldDescribe = objectDescribe.fields.getMap().get(fieldName).getDescribe();

        if (fieldDescribe.getType() == Schema.SObjectType.Picklist) {
            Boolean allowed = false;
            for (Schema.PicklistValue picklistValue : fieldDescribe.getPicklistValues()) {
                if (picklistValue.getValue().equalsIgnoreCase(value)) {
                    allowed = true;
                    break;
                }
            }
            if (!allowed) {
                return;
            }
        }

        record.put(fieldName, value);
    }

    /** Trims a string and returns null when nothing is left. */
    private static String trimToNull(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return String.isBlank(trimmed) ? null : trimmed;
    }
}
