/**
 * @description
 * Replaces the GAU Allocations of an Opportunity with a percentage based split.
 *
 * Design notes
 * ------------
 * - The percentages supplied by the caller are the source of truth. Every allocation is
 *   stored with its npsp__Percent__c value and with the matching npsp__Amount__c value for
 *   the current Opportunity Amount.
 * - npsp__Payment__c is deliberately left empty. NPSP keeps percent based (that is, non
 *   payment) allocations in sync by itself: when the Amount of the Opportunity is corrected
 *   later - for example a $1,000 gift that is corrected to $2,000 - NPSP recalculates the
 *   allocation Amounts from the stored percentages, so the $600/$400 split becomes
 *   $1,200/$800 without any additional code from us. Because of that, the Amount and the
 *   Percentage of these allocations must not be edited by hand; there would be nothing left
 *   for NPSP to recalculate from.
 * - All validation happens before any data is changed. If a check fails an
 *   AllocationException is thrown and nothing is created, changed or deleted.
 */
public with sharing class GauAllocationService {

    /** Thrown when the request is invalid or when the allocations cannot be saved. */
    public class AllocationException extends Exception {}

    /** Number of decimals used for allocation amounts. */
    private static final Integer CURRENCY_SCALE = 2;

    /** The percentages of a single gift may never add up to more than 100%. */
    private static final Decimal MAX_TOTAL_PERCENT = 100;

    /** Fields that have to be writable in order to save a percentage based allocation. */
    private static final List<String> REQUIRED_ALLOCATION_FIELDS = new List<String>{
        'npsp__Opportunity__c',
        'npsp__General_Accounting_Unit__c',
        'npsp__Amount__c',
        'npsp__Percent__c'
    };

