/**
 * HouseholdService
 *
 * Creates a single NPSP Household Account (Household Account record type) together with
 * all of its contacts, in one transaction.
 *
 * Design notes / why it is written this way:
 *
 * 1. Record type Id is resolved at runtime from the record type's DeveloperName
 *    ('HH_Account'), so nothing is hard-coded and the class keeps working in every org.
 *
 * 2. The Household Account is created FIRST and every contact is inserted with that
 *    account's Id already populated.  If the contacts were inserted first (or without an
 *    AccountId) NPSP's automatic household naming could create an extra household for a
 *    contact, leaving stray accounts behind.
 *
 * 3. Only the foreign key AccountId is written on the contacts.  The Account
 *    relationship field itself is not writable on insert
 *    (INVALID_FIELD_FOR_INSERT_UPDATE: "bad field names on insert/update call: Account"),
 *    so it must never be assigned - not even to null.
 *
 * 4. Account.Name is a required field on insert, so a temporary seed value is written.
 *    It is only a seed: NPSP's household naming process replaces it with the configured
 *    household name (and generates the formal/informal greetings) as soon as the primary
 *    contact is known - which happens in step 5.  We never build a household name ourselves.
 *
 * 5. The first contact in the list becomes the household's primary contact
 *    (Account.npe01__One2OneContact__c).  NPSP's naming and greeting processes listen
 *    for that field, so setting it is what triggers NPSP to name the household and
 *    generate the greetings.
 *
 * 6. All DML runs in a single transaction and no exceptions are swallowed, so a failure
 *    anywhere rolls the whole thing back - it is impossible to leave an empty or extra
 *    household account behind.
 */
public with sharing class HouseholdService {

    /** DeveloperName of the Account record type used by NPSP for Household accounts. */
    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    /** Safety valve so a single call can never approach the DML row limits. */
    private static final Integer MAX_HOUSEHOLD_MEMBERS = 200;

    /** Thrown for configuration problems (for example a missing Household record type). */
    public class HouseholdException extends Exception {}

    /**
     * Creates one NPSP Household Account for the supplied contacts.
     *
     * @param members  New contacts (no Id, no AccountId). The first contact in the list
     *                 becomes the household's primary contact.
     * @return         The Id of the newly created Household Account.
     * @throws IllegalArgumentException if members is null, empty or contains null entries.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold: members must not be null or empty.'
            );
        }
        if (members.size() > MAX_HOUSEHOLD_MEMBERS) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold: a household may not have more than '
                + MAX_HOUSEHOLD_MEMBERS + ' members.'
            );
        }
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException(
                    'HouseholdService.createHousehold: members must not contain null entries.'
                );
            }
        }

        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // ------------------------------------------------------------------
        // 1. Create the (still empty) NPSP Household Account.
        // ------------------------------------------------------------------
        Account household = new Account(RecordTypeId = householdRecordTypeId);
        household.Name = getSeedName(members[0]);   // temporary - NPSP overwrites it
        insert household;                           // failure here rolls back everything

        // ------------------------------------------------------------------
        // 2. Attach every contact to that one household.
        //    Only AccountId is set: the Account relationship field is not writable
        //    on insert and assigning it (even to null) makes the insert fail.
        // ------------------------------------------------------------------
        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;   // all-or-nothing: a failure rolls the household account back too

        // ------------------------------------------------------------------
        // 3. First contact in the list = household primary contact.
        //    This is what makes NPSP name the household and build the greetings.
        // ------------------------------------------------------------------
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }

    /**
     * Resolves the Household Account record type Id from its DeveloperName.
     */
    private static Id getHouseholdRecordTypeId() {
        List<RecordType> recordTypes = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = :HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME
              AND IsActive = true
            LIMIT 1
        ];
        if (recordTypes.isEmpty()) {
            throw new HouseholdException(
                'HouseholdService: no active Account record type with DeveloperName "'
                + HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME + '" was found.'
            );
        }
        return recordTypes[0].Id;
    }

    /**
     * Account.Name is required on insert, so a placeholder is needed. It is only a seed:
     * NPSP's household naming process replaces it with the configured household name
     * (for example the family name) once the primary contact is set.
     */
    private static String getSeedName(Contact primaryContact) {
        if (!String.isBlank(primaryContact.LastName)) {
            return primaryContact.LastName;
        }
        if (!String.isBlank(primaryContact.FirstName)) {
            return primaryContact.FirstName;
        }
        return 'Household';
    }
}
