/**
 * @description
 * Converts an open NPSP donation (pledge) into a monthly installment plan.
 *
 * NPSP automatically creates one unpaid payment for the full amount of every new
 * open donation. Major-gift officers want to spread the outstanding balance over
 * a number of monthly installments, starting on a given date.
 *
 * Rules implemented:
 *  - Paid payments and written-off payments are history: they are never modified
 *    or deleted, and their amounts are excluded from the amount still to be collected.
 *  - Every other (open) payment on the opportunity is deleted and replaced with
 *    numberOfPayments new unpaid payments.
 *  - Payment i (0 based) is scheduled on firstPaymentDate.addMonths(i).
 *  - Each installment carries outstanding / numberOfPayments rounded DOWN to the cent
 *    (RoundingMode.DOWN); the last installment absorbs the rounding remainder so that
 *    the new payments add up exactly to the outstanding amount.
 *  - A PaymentPlanService.PaymentPlanException is thrown, without changing anything,
 *    when numberOfPayments is null or < 1, when the opportunity is closed, or when the
 *    outstanding amount is not greater than zero.
 */
public with sharing class PaymentPlanService {

    /** Exception raised by PaymentPlanService. */
    public class PaymentPlanException extends Exception {}

    /** Fallback currency scale used when the field describe does not expose one. */
    private static final Integer FALLBACK_CURRENCY_SCALE = 2;

    /** Payment method used when npe01__Payment_Method__c is required. */
    private static final String DEFAULT_PAYMENT_METHOD = 'Check';

    /**
     * @description Replaces the open payments of a donation with a monthly installment plan.
     *
     * @param opportunityId      Id of the donation (Opportunity) to schedule.
     * @param numberOfPayments  Number of monthly installments (must be >= 1).
     * @param firstPaymentDate  Scheduled date of the first installment.
     * @return The newly created payments, in schedule order.
     * @throws PaymentPlanException If the request is invalid or the DML fails.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId,
                                                                   Integer numberOfPayments,
                                                                   Date firstPaymentDate) {
        // ------------------------------------------------------------------
        // 1. Validate the request BEFORE touching any data.
        // ------------------------------------------------------------------
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity Id is required.');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be greater than zero.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        // ------------------------------------------------------------------
        // 2. Load the opportunity and its payments in a single query.
        // ------------------------------------------------------------------
        List<Opportunity> opportunities = [
            SELECT Id,
                   Name,
                   Amount,
                   StageName,
                   IsClosed,
                   npe01__OppPayment__r.Id,
                   npe01__OppPayment__r.npe01__Payment_Amount__c,
                   npe01__OppPayment__r.npe01__Paid__c,
                   npe01__OppPayment__r.npe01__Written_Off__c
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opportunity = opportunities[0];

        if (opportunity.IsClosed
            || 'Closed Won'.equals(opportunity.StageName)
            || 'Closed Lost'.equals(opportunity.StageName)) {
            throw new PaymentPlanException(
                'Cannot schedule installments on a closed opportunity: ' + opportunity.Name);
        }

        // ------------------------------------------------------------------
        // 3. Split history (kept) from open payments (replaced) and work out
        //    the outstanding amount.
        // ------------------------------------------------------------------
        Decimal opportunityAmount = (opportunity.Amount == null)
            ? Decimal.valueOf(0)
            : opportunity.Amount;
        Decimal settledAmount = Decimal.valueOf(0);
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : opportunity.npe01__OppPayment__r) {
            Decimal paymentAmount = (payment.npe01__Payment_Amount__c == null)
                ? Decimal.valueOf(0)
                : payment.npe01__Payment_Amount__c;
            Boolean isPaid = (payment.npe01__Paid__c == true);
            Boolean isWrittenOff = (payment.npe01__Written_Off__c == true);

            if (isPaid || isWrittenOff) {
                // History: counted once, never changed, never deleted.
                settledAmount = settledAmount + paymentAmount;
            } else {
                paymentsToDelete.add(payment);
            }
        }

        Decimal outstandingAmount = opportunityAmount - settledAmount;
        if (outstandingAmount <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero. Opportunity: ' + opportunity.Name
                + ' (amount: ' + opportunityAmount
                + ', already paid/written off: ' + settledAmount + ')');
        }

        // ------------------------------------------------------------------
        // 4. Build the installment schedule.
        // ------------------------------------------------------------------
        Integer scale = currencyScale();
        Decimal installmentAmount = outstandingAmount.divide(
            Decimal.valueOf(numberOfPayments), scale, RoundingMode.DOWN);
        installmentAmount = installmentAmount.setScale(scale, RoundingMode.DOWN);

        // The last installment absorbs the rounding remainder.
        Decimal lastPaymentAmount = outstandingAmount
            - (installmentAmount * Decimal.valueOf(numberOfPayments - 1));
        lastPaymentAmount = lastPaymentAmount.setScale(scale, RoundingMode.DOWN);

        String paymentMethod = resolvePaymentMethod();
        Boolean setPaid = isFieldWritable('npe01__Paid__c');
        Boolean setWrittenOff = isFieldWritable('npe01__Written_Off__c');
        Boolean paymentDateRequired = isFieldRequired('npe01__Payment_Date__c');

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        Date scheduledDate = firstPaymentDate;

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amountForPayment = (i == numberOfPayments - 1)
                ? lastPaymentAmount
                : installmentAmount;

            npe01__OppPayment__c newPayment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amountForPayment,
                npe01__Scheduled_Date__c = scheduledDate
            );
            if (paymentMethod != null) {
                newPayment.npe01__Payment_Method__c = paymentMethod;
            }
            if (setPaid) {
                newPayment.npe01__Paid__c = false;
            }
            if (setWrittenOff) {
                newPayment.npe01__Written_Off__c = false;
            }
            if (paymentDateRequired) {
                // Only stamp a payment date when the org requires one.
                newPayment.npe01__Payment_Date__c = scheduledDate;
            }

            newPayments.add(newPayment);
            scheduledDate = scheduledDate.addMonths(1);
        }

        // ------------------------------------------------------------------
        // 5. Delete the replaced (open) payments.
        // ------------------------------------------------------------------
        if (!paymentsToDelete.isEmpty()) {
            List<Database.DeleteResult> deleteResults = Database.delete(paymentsToDelete, false);
            for (Database.DeleteResult deleteResult : deleteResults) {
                if (!deleteResult.isSuccess()) {
                    throw new PaymentPlanException(
                        'Unable to delete the existing payments of opportunity ' + opportunity.Name
                        + ': ' + formatErrors(deleteResult.getErrors()));
                }
            }
        }

        // ------------------------------------------------------------------
        // 6. Insert the new installment payments.
        // ------------------------------------------------------------------
        List<Database.SaveResult> insertResults = Database.insert(newPayments, false);
        for (Integer i = 0; i < insertResults.size(); i++) {
            if (!insertResults[i].isSuccess()) {
                throw new PaymentPlanException(
                    'Unable to create installment ' + (i + 1) + ' of ' + numberOfPayments
                    + ' on opportunity ' + opportunity.Name
                    + ': ' + formatErrors(insertResults[i].getErrors()));
            }
        }

        // Returned in schedule order.
        return newPayments;
    }

    /**
     * @description Currency scale of the payment amount field (2 for most orgs).
     */
    private static Integer currencyScale() {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap()
            .get('npe01__Payment_Amount__c');
        if (field == null) {
            return FALLBACK_CURRENCY_SCALE;
        }
        Integer scale = field.getDescribe().getScale();
        if (scale == null || scale < 0) {
            scale = FALLBACK_CURRENCY_SCALE;
        }
        return scale;
    }

    /**
     * @description True when the given payment field can be written on insert.
     */
    private static Boolean isFieldWritable(String fieldName) {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap().get(fieldName);
        if (field == null) {
            return false;
        }
        Schema.SObjectFieldDescribe fieldDescribe = field.getDescribe();
        return fieldDescribe.isCreateable() && fieldDescribe.isUpdateable();
    }

    /**
     * @description True when the given payment field is required in this org.
     */
    private static Boolean isFieldRequired(String fieldName) {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap().get(fieldName);
        if (field == null) {
            return false;
        }
        Schema.SObjectFieldDescribe fieldDescribe = field.getDescribe();
        return fieldDescribe.isRequired();
    }

    /**
     * @description Payment method to stamp on the new payments.
     * Returns null when the field is optional so the org default applies.
     */
    private static String resolvePaymentMethod() {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap()
            .get('npe01__Payment_Method__c');
        if (field == null) {
            return null;
        }
        Schema.SObjectFieldDescribe fieldDescribe = field.getDescribe();
        if (!fieldDescribe.isRequired()) {
            return null;
        }
        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        for (Schema.PicklistEntry entry : entries) {
            if (DEFAULT_PAYMENT_METHOD.equals(entry.getValue())) {
                return entry.getValue();
            }
        }
        if (!entries.isEmpty()) {
            return entries[0].getValue();
        }
        return DEFAULT_PAYMENT_METHOD;
    }

    /**
     * @description Flattens Salesforce DML errors into a readable message.
     */
    private static String formatErrors(List<Database.Error> errors) {
        if (errors == null || errors.isEmpty()) {
            return 'Unknown error.';
        }
        List<String> messages = new List<String>();
        for (Database.Error error : errors) {
            messages.add(error.getStatusCode() + ' - ' + error.getMessage()
                + (error.getFields().isEmpty() ? '' : ' [' + String.join(error.getFields(), ', ') + ']'));
        }
        return String.join(messages, '; ');
    }
