/**
 * GiftService
 *
 * Records a gift (donation) that has already been received by a nonprofit running
 * NPSP with the Household Account model, and returns the Opportunity Id of the
 * recorded gift.
 *
 * The gift is credited the way NPSP expects:
 *   - the gift belongs to the contact's household account;
 *   - the donor is the gift's Primary Contact (npsp__Primary_Contact__c) and holds
 *     the 'Donor' contact role;
 *   - every other member of the household holds the 'Household Member' contact role;
 *   - the gift carries exactly one payment: paid, for the full amount, on the gift date.
 *
 * The method is defensive about duplication: contact roles and payments that already
 * exist on the gift (for example because NPSP automation created them) are reconciled
 * instead of being duplicated, so a contact never ends up with two contact roles on the
 * same gift and the gift never ends up with more than one payment.
 */
public with sharing class GiftService {

    /** NPSP contact role held by the donor of the gift. */
    private static final String DONOR_ROLE = 'Donor';

    /** NPSP contact role held by every other member of the donor's household. */
    private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';

    /** Standard value of Opportunity.StageName for a gift that has been received. */
    private static final String CLOSED_WON = 'Closed Won';

    private GiftService() {
    }

    /**
     * Records a gift that has already been received.
     *
     * @param contactId Id of the donor Contact. Required.
     * @param amount    Gift amount. Must be greater than zero. Required.
     * @param giftDate  Date the gift was received. Defaults to today when null.
     * @return          The Id of the Opportunity (gift) that was created.
     * @throws IllegalArgumentException if the contact does not exist, or if the amount
     *                                  is null, zero or negative.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // ------------------------------------------------------------------
        // Validate the input
        // ------------------------------------------------------------------
        if (contactId == null) {
            throw new IllegalArgumentException('A contact is required in order to record a gift.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be a positive number.');
        }

        Date effectiveGiftDate = (giftDate == null) ? Date.today() : giftDate;

        // ------------------------------------------------------------------
        // Load the donor
        // ------------------------------------------------------------------
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact ' + contactId + ' does not exist.');
        }
        Contact donor = donors[0];

        // ------------------------------------------------------------------
        // Load the other members of the donor's household
        // (with the Household Account model the household is the Contact's Account)
        // ------------------------------------------------------------------
        List<Contact> otherHouseholdMembers = new List<Contact>();
        if (donor.AccountId != null) {
            otherHouseholdMembers = [
                SELECT Id
                FROM Contact
                WHERE AccountId = :donor.AccountId
                  AND Id != :donor.Id
            ];
        }

        // ------------------------------------------------------------------
        // Create the gift
        // ------------------------------------------------------------------
        Opportunity gift = new Opportunity(
            Name                     = buildGiftName(donor, effectiveGiftDate),
            AccountId                = donor.AccountId,
            StageName                = CLOSED_WON,
            CloseDate                = effectiveGiftDate,
            Amount                   = amount,
            npsp__Primary_Contact__c = donor.Id
        );
        insert gift;

        // ------------------------------------------------------------------
        // Contact roles: exactly one role per household contact
        // ------------------------------------------------------------------
        alignContactRoles(gift.Id, donor.Id, otherHouseholdMembers);

        // ------------------------------------------------------------------
        // Exactly one payment: paid, for the full amount, on the gift date
        // ------------------------------------------------------------------
        recordPayment(gift.Id, amount, effectiveGiftDate);

        return gift.Id;
    }

    /**
     * Makes sure the gift has exactly one contact role per household contact:
     * the donor holds the 'Donor' role (as primary contact), every other household
     * member holds the 'Household Member' role. Any pre-existing role that is not
     * wanted, or that duplicates another role for the same contact, is removed.
     */
    private static void alignContactRoles(Id opportunityId, Id donorId, List<Contact> otherHouseholdMembers) {
        // The contact roles the gift should end up with, keyed by contact.
        Map<Id, OpportunityContactRole> desiredRoles = new Map<Id, OpportunityContactRole>();
        desiredRoles.put(donorId, new OpportunityContactRole(
            OpportunityId = opportunityId,
            ContactId     = donorId,
            Role          = DONOR_ROLE,
            IsPrimary     = true
        ));
        for (Contact member : otherHouseholdMembers) {
            if (desiredRoles.containsKey(member.Id)) {
                continue; // never create a second role for the same contact
            }
            desiredRoles.put(member.Id, new OpportunityContactRole(
                OpportunityId = opportunityId,
                ContactId     = member.Id,
                Role          = HOUSEHOLD_MEMBER_ROLE,
                IsPrimary     = false
            ));
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        Set<Id> contactsWithRole = new Set<Id>();

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ];

        for (OpportunityContactRole existing : existingRoles) {
            if (!desiredRoles.containsKey(existing.ContactId) || contactsWithRole.contains(existing.ContactId)) {
                // A role for a contact that must not have one, or a duplicate role.
                rolesToDelete.add(existing);
                continue;
            }
            contactsWithRole.add(existing.ContactId);

            OpportunityContactRole desired = desiredRoles.get(existing.ContactId);
            if (existing.Role != desired.Role || existing.IsPrimary != desired.IsPrimary) {
                existing.Role      = desired.Role;
                existing.IsPrimary = desired.IsPrimary;
                rolesToUpdate.add(existing);
            }
        }

        for (Id contactId : desiredRoles.keySet()) {
            if (!contactsWithRole.contains(contactId)) {
                rolesToInsert.add(desiredRoles.get(contactId));
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    /**
     * Records the single payment for the gift and removes any duplicate payment
     * that may already exist on it.
     */
    private static void recordPayment(Id opportunityId, Decimal amount, Date giftDate) {
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c     = opportunityId,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c   = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c           = true
        );
        insert payment;

        // Safety net: a gift must never carry more than one payment.
        List<npe01__OppPayment__c> payments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];
        if (payments.size() > 1) {
            List<npe01__OppPayment__c> duplicatePayments = new List<npe01__OppPayment__c>();
            for (npe01__OppPayment__c existing : payments) {
                if (existing.Id != payment.Id) {
                    duplicatePayments.add(existing);
                }
            }
            if (!duplicatePayments.isEmpty()) {
                delete duplicatePayments;
            }
        }
    }

    /**
     * Builds the NPSP style gift name: '&lt;FirstName&gt; &lt;LastName&gt; Donation &lt;yyyy-MM-dd&gt;'.
     * Example: 'Jane Smith Donation 2026-03-01'.
     */
    private static String buildGiftName(Contact donor, Date giftDate) {
        List<String> nameParts = new List<String>();
        if (String.isNotBlank(donor.FirstName)) {
            nameParts.add(donor.FirstName.trim());
        }
        if (String.isNotBlank(donor.LastName)) {
            nameParts.add(donor.LastName.trim());
        }
        nameParts.add('Donation');
        nameParts.add(formatDate(giftDate));
        return String.join(nameParts, ' ');
    }

    /**
     * Formats a Date as 'yyyy-MM-dd'.
     */
    private static String formatDate(Date dateToFormat) {
        return DateTime.newInstance(dateToFormat.year(), dateToFormat.month(), dateToFormat.day())
            .format('yyyy-MM-dd');
    }
}
