/**
 * OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management (TDTM) trigger handler that creates a follow-up
 * Task for major gifts.
 *
 * ---------------------------------------------------------------------------------------
 * NPSP Trigger Handler registration (NPSP Settings > Trigger Configuration):
 *   Class Name     : OPP_MajorGiftFollowUp_TDTM
 *   Object         : Opportunity
 *   Trigger Action : AfterInsert;AfterUpdate
 *   Load Order     : 5
 *   Is Asynchronous: false
 *
 * There is deliberately NO Apex trigger on Opportunity. This class is only ever executed
 * by NPSP's TDTM dispatcher (npsp.TDTM_Runnable) when an *active* Trigger Handler record
 * points at it, so deactivating (or deleting) that Trigger Handler record switches the
 * behaviour off immediately - no code changes and no redeploy required.
 * ---------------------------------------------------------------------------------------
 *
 * Business rule:
 *   Create exactly one Task when an Opportunity:
 *     * is inserted as Closed Won with Amount >= 5000, OR
 *     * is updated so that it becomes Closed Won with Amount >= 5000 and it was not
 *       both of those things before the update.
 *   Editing a gift that already qualified must NOT create a second Task.
 *
 * The Task created is:
 *   Subject     : Major gift thank-you call
 *   Priority    : High
 *   Status      : Not Started
 *   WhatId      : the Opportunity
 *   WhoId       : Opportunity.npsp__Primary_Contact__c (may be null)
 *   OwnerId     : the Opportunity owner
 *   ActivityDate: Opportunity.CloseDate + 3 days
 *
 * Bulk / governor-limit design:
 *   * 0 SOQL queries are needed for the normal path: the "before" state of each
 *     Opportunity comes from the old records TDTM hands us, indexed in memory by Id.
 *   * At most 1 SOQL query is used as a safety net: if TDTM did not supply the previous
 *     state of an Opportunity (for example a direct call to run()), we check for a
 *     thank-you Task that already exists so that we never create a duplicate.
 *   * Exactly 1 DML statement: all Tasks are inserted with a single bulk insert
 *     (insert myTasks;) - 200 Opportunities are handled in one transaction.
 */
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /** Minimum Opportunity Amount that is treated as a major gift. */
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    /** Opportunity Stage that qualifies a gift. */
    private static final String CLOSED_WON = 'Closed Won';

    /** Number of days after CloseDate on which the thank-you call is due. */
    private static final Integer FOLLOW_UP_DAYS = 3;

    /** Subject of the generated follow-up Task. */
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    /** Priority of the generated follow-up Task. */
    private static final String TASK_PRIORITY = 'High';

    /** Status of the generated follow-up Task. */
    private static final String TASK_STATUS = 'Not Started';

    /**
     * Entry point invoked by NPSP's TDTM dispatcher.
     *
     * @param newlist       records in their current (new) state
     * @param oldlist       records in their previous state (AfterUpdate only)
     * @param triggerAction the TDTM action being executed
     * @param objResult     describe information for the object being processed
     * @return a DmlWrapper for NPSP (the Tasks are inserted by this handler with a
     *         single DML statement, so no further DML is queued for NPSP to run)
     */
    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist,
                                                      List<SObject> oldlist,
                                                      npsp.TDTM_Runnable.Action triggerAction,
                                                      Schema.DescribeSObjectResult objResult) {

        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        // ------------------------------------------------------------------
        // Index the previous state of the records in memory (no SOQL query).
        // ------------------------------------------------------------------
        Map<Id, SObject> oldRecordsById = new Map<Id, SObject>();
        if (oldlist != null) {
            for (SObject oldRecord : oldlist) {
                if (oldRecord != null && oldRecord.Id != null) {
                    oldRecordsById.put(oldRecord.Id, oldRecord);
                }
            }
        }

        // ------------------------------------------------------------------
        // Work out which Opportunities need a thank-you call.
        // ------------------------------------------------------------------
        List<Opportunity> qualifyingOpps = new List<Opportunity>();
        Set<Id> oppIdsWithNoOldRecord = new Set<Id>();
        Set<Id> processedOppIds = new Set<Id>();

        for (SObject newRecord : newlist) {
            if (newRecord == null) {
                continue;
            }

            Opportunity opp = (Opportunity) newRecord;
            if (opp.Id == null || processedOppIds.contains(opp.Id)) {
                // guard against the same record appearing twice in the batch
                continue;
            }
            processedOppIds.add(opp.Id);

            // Only Closed Won opportunities of 5000 or more qualify.
            if (!isMajorGift(opp)) {
                continue;
            }

            SObject oldRecord = oldRecordsById.get(opp.Id);
            if (oldRecord != null) {
                // The gift already qualified before this change - do not thank twice.
                if (isMajorGift((Opportunity) oldRecord)) {
                    continue;
                }
            } else {
                // No previous state available - we will double check with a single query.
                oppIdsWithNoOldRecord.add(opp.Id);
            }

            qualifyingOpps.add(opp);
        }

        if (qualifyingOpps.isEmpty()) {
            return dmlWrapper;
        }

        // ------------------------------------------------------------------
        // Safety net: at most 1 SOQL query. Guarantees that an Opportunity that
        // already has a thank-you call Task never receives a second one.
        // ------------------------------------------------------------------
        if (!oppIdsWithNoOldRecord.isEmpty()) {
            Set<Id> oppIdsWithExistingTask = new Set<Id>();
            for (Task existingTask : [SELECT Id, WhatId
                                      FROM Task
                                      WHERE WhatId IN :oppIdsWithNoOldRecord
                                        AND Subject = :TASK_SUBJECT]) {
                if (existingTask.WhatId != null) {
                    oppIdsWithExistingTask.add(existingTask.WhatId);
                }
            }

            if (!oppIdsWithExistingTask.isEmpty()) {
                List<Opportunity> filteredOpps = new List<Opportunity>();
                for (Opportunity opp : qualifyingOpps) {
                    if (!oppIdsWithExistingTask.contains(opp.Id)) {
                        filteredOpps.add(opp);
                    }
                }
                qualifyingOpps = filteredOpps;
            }
        }

        // ------------------------------------------------------------------
        // Build the follow-up Tasks.
        // ------------------------------------------------------------------
        List<Task> followUpTasks = new List<Task>();
        for (Opportunity opp : qualifyingOpps) {
            followUpTasks.add(buildFollowUpTask(opp));
        }

        // ------------------------------------------------------------------
        // One single DML statement for the whole batch.
        // ------------------------------------------------------------------
        if (!followUpTasks.isEmpty()) {
            insert followUpTasks;
        }

        return dmlWrapper;
    }

    /**
     * @param opp the Opportunity to test
     * @return true when the Opportunity is Closed Won with an Amount of 5000 or more
     */
    private static Boolean isMajorGift(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        if (opp.StageName == null || opp.StageName != CLOSED_WON) {
            return false;
        }
        return opp.Amount != null && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    /**
     * Builds the thank-you call Task for a qualifying Opportunity.
     */
    private static Task buildFollowUpTask(Opportunity opp) {
        Date dueDate = null;
        if (opp.CloseDate != null) {
            dueDate = opp.CloseDate.addDays(FOLLOW_UP_DAYS);
        } else {
            // CloseDate is required on Opportunity, but never leave ActivityDate null.
            dueDate = Date.today().addDays(FOLLOW_UP_DAYS);
        }

        Task followUpTask = new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId != null ? opp.OwnerId : UserInfo.getUserId(),
            ActivityDate = dueDate
        );

        if (opp.Name != null) {
            followUpTask.Description =
                'Major gift follow-up call for Opportunity ' + opp.Name + '.';
        }

        return followUpTask;
    }
}
