/**
 * RecordAccessService
 *
 * Answers the question "which of these records may the running user actually edit?"
 * for bulk-edit style screens where a user selects many records at once.
 *
 * Why UserRecordAccess
 * --------------------
 * The `UserRecordAccess` object is the platform's own evaluation of the full
 * access model for a given user and record:
 *   - object permissions (CRUD) of the user's profile / permission sets,
 *   - record ownership,
 *   - all sharing rules (OWD, manual, Apex, criteria based),
 *   - the role / role hierarchy,
 *   - territory (forecast) hierarchies,
 *   - View All Data / Modify All Data.
 * Records the running user cannot see at all are simply *not returned* by a
 * UserRecordAccess query, so they can never leak into the result set.
 *
 * Behavioural contract
 * --------------------
 *   - A null or empty input returns an empty set (never null).
 *   - The returned set contains only ids that were passed in AND for which
 *     the running user has `HasEditAccess = true`.
 *   - A record may have more than one UserRecordAccess row (the user can
 *     reach it through different sharing paths / record types). The record is
 *     reported as editable when *any* of its rows reports HasEditAccess.
 *   - The method fails *closed*: if access cannot be proven (for example the
 *     UserRecordAccess query throws), the affected records are treated as not
 *     editable and are reported through the debug log.
 *   - The method is bulk safe: it is static, holds no state between calls and
 *     can be called from the same transaction as the rest of the logic.
 *
 * Query budget
 * ------------
 * Callers pass up to 2,000 ids per call and the whole method has to fit in
 * at most 20 SOQL queries. The ids are therefore evaluated in chunks of at
 * most MAX_IDS_PER_QUERY (100) ids per query: 2,000 / 100 = 20 queries.
 * The `RecordId` field of UserRecordAccess is polymorphic, so a single chunk
 * may contain ids of different object types; no per-object splitting is
 * needed (splitting per object would break the 20 query budget).
 *
 * Usage
 * -----
 *   Set<Id> selected = new Set<Id>{ ... };
 *   Set<Id> allowed = RecordAccessService.editableIds(selected);
 *   // only render / enable the bulk action for `allowed`
 */
public with sharing class RecordAccessService {

    /** Maximum number of record ids evaluated by one UserRecordAccess query. */
    private static final Integer MAX_IDS_PER_QUERY = 100;

    /** Hard ceiling on the number of SOQL queries a single call may issue. */
    private static final Integer MAX_QUERIES_PER_CALL = 20;

    /** Absolute upper bound for the ids-per-query chunk size. */
    private static final Integer MAX_CHUNK_SIZE = 1000;

    /**
     * Returns the subset of `recordIds` that the running user is allowed to edit.
     *
     * @param recordIds candidate record ids (may span several object types)
     * @return ids the running user can edit; never null, possibly empty
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        // 1. Defensive input handling: strip nulls and duplicates.
        Set<Id> candidateIds = new Set<Id>();
        if (recordIds != null) {
            for (Id recordId : recordIds) {
                if (recordId != null) {
                    candidateIds.add(recordId);
                }
            }
        }
        if (candidateIds.isEmpty()) {
            return editable;
        }

        // 2. No running user (pure system context) -> fail closed.
        Id userId = UserInfo.getUserId();
        if (userId == null) {
            System.debug(
                LoggingLevel.WARN,
                'RecordAccessService.editableIds: no running user context; returning no editable ids.'
            );
            return editable;
        }

        // 3. Evaluate the access in chunks so that the call stays inside the
        //    20 query budget (2,000 ids -> 20 queries of 100 ids).
        Integer chunkSize = resolveChunkSize(candidateIds.size());
        for (List<Id> chunk : toChunks(candidateIds, chunkSize)) {
            collectEditable(userId, chunk, editable);
        }

        return editable;
    }

    /**
     * Runs a single UserRecordAccess query for the given chunk and adds every
     * record with HasEditAccess = true to `editable`.
     *
     * Note: `RecordId` is the id of the record being evaluated (it is a
     * polymorphic reference, so records of different object types can be
     * queried in the same statement). `RecordId` is mandatory in the SELECT
     * list of a UserRecordAccess query.
     */
    private static void collectEditable(Id userId, List<Id> chunk, Set<Id> editable) {
        try {
            List<UserRecordAccess> accessRows = [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :userId
                  AND RecordId IN :chunk
            ];

            for (UserRecordAccess accessRow : accessRows) {
                if (accessRow != null && accessRow.RecordId != null && accessRow.HasEditAccess == true) {
                    editable.add(accessRow.RecordId);
                }
            }
        } catch (Exception e) {
            // Fail closed: access that cannot be proven is never offered.
            System.debug(
                LoggingLevel.ERROR,
                'RecordAccessService.editableIds: UserRecordAccess query failed for a chunk of '
                + chunk.size()
                + ' id(s); those records are reported as NOT editable. '
                + e.getMessage()
            );
        }
    }

    /**
     * Splits the ids into chunks of at most `chunkSize` ids.
     */
    private static List<List<Id>> toChunks(Set<Id> ids, Integer chunkSize) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> current = new List<Id>();
        for (Id recordId : ids) {
            current.add(recordId);
            if (current.size() >= chunkSize) {
                chunks.add(current);
                current = new List<Id>();
            }
        }
        if (!current.isEmpty()) {
            chunks.add(current);
        }
        return chunks;
    }

    /**
     * Determines how many ids are evaluated per query.
     * For the documented call size (2,000 ids) this yields 100 ids per query,
     * i.e. exactly 20 queries. Larger inputs are chunked a little bigger so
     * that the query count still stays within the budget.
     */
    private static Integer resolveChunkSize(Integer idCount) {
        Integer budgetChunk = (Integer) Math.ceil(idCount / (Double) MAX_QUERIES_PER_CALL);
        Integer chunkSize = Math.max(MAX_IDS_PER_QUERY, budgetChunk);
        return Math.min(chunkSize, MAX_CHUNK_SIZE);
    }
}
```

