/**
 * DiscountApprovalService
 *
 * Determines whether the running user may approve a given discount percentage.
 * Business rule:
 *   - Discounts up to and including 15% may be approved by any user.
 *   - Discounts above 15% may only be approved by users who hold the
 *     Approve_Large_Discount custom permission (which may be granted through
 *     any permission set or permission set group).
 */
public with sharing class DiscountApprovalService {
    /** Maximum discount percentage a user can approve without special permission. */
    private static final Decimal STANDARD_DISCOUNT_LIMIT = 15;

    /** Name of the custom permission required to approve discounts above the standard limit. */
    private static final String LARGE_DISCOUNT_PERMISSION = 'Approve_Large_Discount';

    /**
     * Returns true if the running user can approve the specified discount percentage.
     *
     * @param discountPercent Discount percentage to evaluate (null, negative, 0-15, or >15).
     * @return true if the running user is allowed to approve the discount; otherwise false.
     */
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        // Invalid input: nothing can be approved.
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }

        // Within the standard limit: any user may approve.
        if (discountPercent <= STANDARD_DISCOUNT_LIMIT) {
            return true;
        }

        // Above the standard limit: require the custom permission.
        // FeatureManagement.checkPermission evaluates the running user's effective
        // custom permissions, including those granted via permission sets and
        // permission set groups, without querying profiles or user records.
        return FeatureManagement.checkPermission(LARGE_DISCOUNT_PERMISSION);
    }
}
