/**
 * EmployeeDirectoryService
 *
 * Returns the FB_Employee__c records the running user can see through sharing
 * (sharing is respected, never bypassed), ordered by Name ascending.
 *
 * Field level security is honoured: Salary__c, Department__c and
 * Personal_Email__c are only projected (selected) when the running user really
 * has read access to them. A field the user cannot read is therefore absent
 * from the returned records rather than present with a null value, and a user
 * with partial field access still receives the records with the fields they
 * can read. The method never throws because of missing permissions.
 *
 * If the running user has no read access to FB_Employee__c at all, an empty
 * list is returned.
 */
public with sharing class EmployeeDirectoryService {
    private static final String OBJECT_NAME = 'FB_Employee__c';

    /** Custom fields whose readability varies by audience. */
    private static final List<String> OPTIONAL_FIELD_NAMES = new List<String>{
        'Department__c',
        'Salary__c',
        'Personal_Email__c'
    };

    public static List<FB_Employee__c> getDirectory() {
        List<FB_Employee__c> directory = new List<FB_Employee__c>();

        // Object level access (CRUD) for the running user.
        Schema.DescribeSObjectResult objectDescribe =
            Schema.SObjectType.FB_Employee__c.getDescribe();

        if (!objectDescribe.isAccessible()) {
            return directory;
        }

        // Field level access: only project the fields this user may read.
        Map<String, Schema.SObjectField> fieldsByName = objectDescribe.fields.getMap();

        List<String> selectFields = new List<String>{ 'Id', 'Name' };
        for (String fieldName : OPTIONAL_FIELD_NAMES) {
            Schema.SObjectField field = fieldsByName.get(fieldName);
            if (field == null) {
                continue;
            }
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (fieldDescribe.isAccessible()) {
                selectFields.add(fieldName);
            }
        }

        String query =
            'SELECT ' + String.join(selectFields, ', ') +
            ' FROM ' + OBJECT_NAME +
            ' ORDER BY Name ASC';

        try {
            // Dynamic SOQL so the projection matches the user's field access.
            for (FB_Employee__c employee : Database.query(query)) {
                directory.add(employee);
            }
        } catch (QueryException e) {
            // Permission / access related failures must not surface to the caller.
            return new List<FB_Employee__c>();
        } catch (Exception e) {
            return new List<FB_Employee__c>();
        }

        return directory;
    }
}
