```apex
/**
 * TA_Account_CreateOnboardingTask
 *
 * Trigger Action (Trigger Actions Framework 0.3.4, unlocked, no namespace).
 *
 * Purpose:
 *   On creation of an Account whose Type is 'Customer - Direct' or 'Customer - Channel',
 *   create an onboarding Task for the account's owner.
 *
 * Behaviour:
 *   - Runs only in the after-insert context (registered via Trigger_Action__mdt.After_Insert__c).
 *   - Accounts of any other type (or with no type) are ignored.
 *   - One single DML statement per trigger execution: all qualifying tasks are inserted in
 *     one bulk 'insert' (safe for 200-record data loads).
 *   - No DML is performed at all when no account qualifies.
 *   - No SOQL is executed (the Account Id and OwnerId come from the in-memory records).
 *
 * Note on OwnerId:
 *   The Task is owned by the Account's owner, which is not necessarily the running user.
 *   Trigger code executes in system context, so the owner assignment does not depend on the
 *   running user's sharing rights; the Account owner must still be an assignable owner
 *   (active User or queue) for the insert to succeed.
 */
public class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    /** Account Type values that trigger onboarding. */
    private static final Set<String> QUALIFYING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';
    private static final Integer ONBOARDING_DUE_DAYS = 7;

    /**
     * TAF after-insert entry point.
     *
     * @param triggerNew The Account records that were just inserted.
     */
    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Date dueDate = Date.today().addDays(ONBOARDING_DUE_DAYS);
        List<Task> tasks = new List<Task>();

        for (SObject record : triggerNew) {
            // TAF invokes this action from the Account trigger only.
            Account account = (Account) record;

            // Set.contains(null) is false, so accounts without a Type are skipped.
            if (!QUALIFYING_ACCOUNT_TYPES.contains(account.Type)) {
                continue;
            }

            tasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = dueDate,
                    Status = TASK_STATUS,
                    Priority = TASK_PRIORITY
                )
            );
        }

        // No qualifying account -> no DML.
        if (tasks.isEmpty()) {
            return;
        }

        // Single DML statement for the whole batch.
        insert tasks;
    }
}
