 *  - Contact is NOT bypassed: every Contact trigger action runs normally for the Contact update.
 *  - The Account bypass is always removed in a `finally` block, so Account automation behaves
 *    normally again for the remainder of the transaction, whether the reassignment succeeded
 *    or failed.
 *  - DML is all-or-none and exceptions are never caught, swallowed or re-wrapped: a failure
 *    rolls the transaction back and the platform exception propagates to the caller unchanged.
 *  - Volume independent: exactly two SOQL queries and at most two DML statements are used,
 *    no matter how many Accounts or Contacts are involved.
 */
public with sharing class AccountOwnershipService {

    /** Documented maximum number of Accounts a single call is expected to handle. */
    public static final Integer MAX_ACCOUNTS_PER_CALL = 200;

    /** Apex transaction limit: maximum number of rows that may be updated in one transaction. */
    private static final Integer MAX_DML_ROWS_PER_TRANSACTION = 10000;

    /** sObject whose TAF trigger actions are bypassed for the ownership change. */
    private static final String ACCOUNT_SOBJECT_NAME = 'Account';

    private AccountOwnershipService() {
        // Utility class: no instances.
    }

    /**
     * Re-owns the given Accounts and all of their Contacts to newOwnerId.
     *
     * @param accountIds  Ids of the Accounts to reassign (callers pass up to 200).
     * @param newOwnerId  Id of the new owner (user or queue).
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (newOwnerId == null) {
            throw new DmlException('AccountOwnershipService.reassign: newOwnerId is required.');
        }
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Defensive copy so the caller's collection is never mutated; drop stray nulls.
        Set<Id> targetAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                targetAccountIds.add(accountId);
            }
        }
        if (targetAccountIds.isEmpty()) {
            return;
        }

        // SOQL 1 of 2: the Accounts that have to change owner.
        List<Account> accounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :targetAccountIds
        ];

        // SOQL 2 of 2: every Contact of those Accounts.
        List<Contact> contacts = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :targetAccountIds
        ];

        // Only two DML statements are allowed, so the load cannot be split: fail fast with a
        // clear message instead of blowing up half way through the transaction.
        if (accounts.size() + contacts.size() > MAX_DML_ROWS_PER_TRANSACTION) {
            throw new DmlException(
                'AccountOwnershipService.reassign: ' + (accounts.size() + contacts.size())
                + ' records would be updated, which exceeds the ' + MAX_DML_ROWS_PER_TRANSACTION
                + ' row DML limit of a transaction. Reassign fewer Accounts per call.'
            );
        }

        for (Account account : accounts) {
            account.OwnerId = newOwnerId;
        }
        for (Contact contact : contacts) {
            contact.OwnerId = newOwnerId;
        }

        try {
            // TAF transaction bypass for the whole Account sObject: no Account trigger action
            // (territory recalculation, roll-ups, ...) runs for this ownership change.
            TriggerBase.bypass(ACCOUNT_SOBJECT_NAME);

            // DML 1 of 2: Accounts. All-or-none; on any failure the platform throws and the
            // whole transaction is rolled back.
            if (!accounts.isEmpty()) {
                Database.update(accounts, true);
            }

            // DML 2 of 2: Contacts. No bypass on Contact, so every Contact trigger action runs
            // normally. All-or-none as well.
            if (!contacts.isEmpty()) {
                Database.update(contacts, true);
            }
        } finally {
            // Account automation must behave normally for the rest of the transaction,
            // whether the reassignment succeeded or failed.
            TriggerBase.clearBypass(ACCOUNT_SOBJECT_NAME);
        }
    }
}
