```apex
/**
 * @description
 * TAF DML Finalizer that pushes Opportunities to the ERP.
 *
 * The framework calls every registered finalizer at the end of every DML operation it handles,
 * whatever the sObject involved, and only once per DML operation (no matter how many times the
 * trigger recursion fired). This finalizer therefore:
 *
 *  1. Drains the Opportunity Ids collected by TA_Opportunity_CollectForErpSync during that DML
 *     operation (a single insert of 250 Opportunities runs the trigger in two chunks, 200 + 50, so
 *     the buffer holds all 250 Ids at that point).
 *  2. Enqueues exactly ONE OpportunityErpSyncJob carrying those Ids.
 *  3. Enqueues nothing at all when no Opportunity of that DML operation needs a sync (empty buffer),
 *     e.g. when the DML operation was performed on another sObject or when no StageName changed.
 *
 * Draining the buffer (instead of only reading it) guarantees that two separate DML statements in
 * the same transaction produce two jobs, each carrying only its own records.
 *
 * Note: a finalizer must not perform DML. Enqueueing a Queueable job is not DML, so it is allowed
 * here (the finalizer always runs in an after-trigger context).
 *
 * @see TA_Opportunity_CollectForErpSync
 * @see OpportunityErpSyncJob
 */
public with sharing class OpportunityErpSyncFinalizer extends FinalizerHandler implements TriggerAction.DmlFinalizer {
    /** @description Name of this finalizer, used with the bypass mechanism. */
    private static final String FINALIZER_NAME = 'OpportunityErpSyncFinalizer';

    /**
     * @description Enqueues the ERP synchronization job for the DML operation being finalized.
     * @param context The DML finalization context provided by the framework.
     */
    public void execute(FinalizerHandler.Context context) {
        if (FinalizerHandler.isBypassed(FINALIZER_NAME)) {
            return;
        }
        enqueueErpSyncJobIfNeeded();
    }

    /**
     * @description Alternate entry point used by the framework for finalizers registered as
     * FinalizerHandler subclasses. It performs the very same (drained) work as execute(), so the
     * buffer can only be consumed once per DML operation: exactly one job is enqueued.
     */
    public override void handleDynamicFinalizers() {
        if (FinalizerHandler.isBypassed(FINALIZER_NAME)) {
            return;
        }
        enqueueErpSyncJobIfNeeded();
    }

    /**
     * @description Drains the collected Opportunity Ids and enqueues one job with them.
     * Nothing is enqueued when no Opportunity of this DML operation needs a sync.
     */
    private void enqueueErpSyncJobIfNeeded() {
        // Only the Ids collected during this DML operation are returned; the buffer is emptied.
        Set<Id> opportunityIds = TA_Opportunity_CollectForErpSync.drainPendingOpportunityIds();
        if (opportunityIds.isEmpty()) {
            // Nothing to sync for this DML operation -> no job at all.
            return;
        }

        try {
            // Enqueueing a Queueable job is not DML, so it is allowed in a DML finalizer.
            System.enqueueJob(new OpportunityErpSyncJob(opportunityIds));
        } catch (Exception e) {
            System.debug(
                LoggingLevel.ERROR,
                'OpportunityErpSyncFinalizer: unable to enqueue OpportunityErpSyncJob for '
                    + opportunityIds.size()
                    + ' Opportunity(s). '
                    + e.getMessage()
            );
        }
    }
}
