```apex
/**
 * Concrete TriggerRecord implementation for the Account object.
 *
 * The Trigger Actions Framework builds one instance of this class for every record
 * in the trigger batch and populates newSobject / oldSobject on it. The entry
 * criteria formula of a Trigger_Action__mdt record is then evaluated against that
 * instance, so every value referenced by the formula has to be exposed as a
 * property of this class.
 *
 * The class only reads the two records it is handed: no SOQL and no DML, so it is
 * completely bulk safe.
 *
 * Properties:
 *   newRating - value of Account.Rating after the change
 *   oldRating - value of Account.Rating before the change (null when the account
 *               had no rating yet, and in the insert context where there is no
 *               old record at all)
 */
public class AccountTriggerRecord extends TriggerRecord {
    private Boolean newRatingProvided = false;
    private Boolean oldRatingProvided = false;
    private String newRatingValue;
    private String oldRatingValue;

    public AccountTriggerRecord() {
    }

    public AccountTriggerRecord(SObject newSobject, SObject oldSobject) {
        this.newSobject = newSobject;
        this.oldSobject = oldSobject;
    }

    /**
     * The Account after the change.
     */
    public Account newAccount {
        get {
            return newSobject == null ? null : (Account) newSobject;
        }
        set {
            newSobject = value;
        }
    }

    /**
     * The Account before the change. Null in the insert context.
     */
    public Account oldAccount {
        get {
            return oldSobject == null ? null : (Account) oldSobject;
        }
        set {
            oldSobject = value;
        }
    }

    /**
     * Value of Account.Rating after the change.
     */
    public String newRating {
        get {
            if (newRatingProvided) {
                return newRatingValue;
            }
            return readRating(newSobject);
        }
        set {
            newRatingValue = value;
            newRatingProvided = true;
        }
    }

    /**
     * Value of Account.Rating before the change. Null when the account had no
     * rating before the update (and in the insert context).
     */
    public String oldRating {
        get {
            if (oldRatingProvided) {
                return oldRatingValue;
            }
            return readRating(oldSobject);
        }
        set {
            oldRatingValue = value;
            oldRatingProvided = true;
        }
    }

    private static String readRating(SObject record) {
        if (record == null) {
            return null;
        }
        Object rating = record.get('Rating');
        return rating == null ? null : String.valueOf(rating);
    }
}
