```apex
/**
 * TA_Case_RollupOpenCount
 *
 * Trigger Action (Trigger Actions Framework 0.3.4) that keeps
 * Account.FB_Open_Case_Count__c equal to the number of Cases that belong to the
 * Account and are still open (Case.IsClosed = false).
 *
 * Registered through Trigger_Action__mdt in every context in which the count can change:
 *   TA_Case_RollupOpenCount_AI   -> after insert   (open or already closed case)
 *   TA_Case_RollupOpenCount_AU   -> after update   (closed, reopened, moved to another account)
 *   TA_Case_RollupOpenCount_AD   -> after delete
 *   TA_Case_RollupOpenCount_AUD  -> after undelete
 *
 * Design notes:
 * - The count is always recomputed from the database (never incremented/decremented), so the
 *   field is self-healing and correct even when cases are moved between accounts, closed,
 *   reopened, deleted or undeleted.
 * - Every Account touched by the batch (old account and new account of every affected case)
 *   is refreshed, so an Account whose last open case disappears is set to 0 (never blank).
 * - Cases without an Account are ignored.
 * - Governor limits: at most 2 SOQL queries (1 aggregate on Case + 1 on Account) and
 *   1 DML statement (the Account update) per trigger execution.
 * - There is no trigger on Account, so updating the Account cannot re-enter this action.
 */
public inherited sharing class TA_Case_RollupOpenCount implements
    TriggerAction.AfterInsert,
    TriggerAction.AfterUpdate,
    TriggerAction.AfterDelete,
    TriggerAction.AfterUndelete {

    /* ------------------------------------------------------------------ *
     * Trigger Action entry points
     * ------------------------------------------------------------------ */

    /**
     * After insert: a new case may be open or already closed. The Account is refreshed in
     * both cases so that its value always mirrors the real number of open cases.
     */
    public void afterInsert(List<SObject> triggerNew) {
        rollupOpenCaseCounts(collectAccountIds(triggerNew));
    }

    /**
     * After update: a case can be closed, reopened or moved to another Account. Only a change
     * of Account or of the open/closed state can change a count, so records that changed
     * neither are skipped (no query, no DML). When the case moved, both the previous and the
     * new Account are refreshed.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();

        Integer recordCount = triggerNew.size();
        for (Integer i = 0; i < recordCount; i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];

            // Nothing that influences the roll-up changed -> nothing to recompute.
            if (newCase.AccountId == oldCase.AccountId && newCase.IsClosed == oldCase.IsClosed) {
                continue;
            }

            if (newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
            // The old Account loses the case when the case was moved to a different Account.
            if (oldCase.AccountId != null && oldCase.AccountId != newCase.AccountId) {
                accountIds.add(oldCase.AccountId);
            }
        }

        rollupOpenCaseCounts(accountIds);
    }

    /** After delete: the deleted cases are gone, so their Accounts are recounted. */
    public void afterDelete(List<SObject> triggerOld) {
        rollupOpenCaseCounts(collectAccountIds(triggerOld));
    }

    /** After undelete: the restored cases are visible again, so their Accounts are recounted. */
    public void afterUndelete(List<SObject> triggerNew) {
        rollupOpenCaseCounts(collectAccountIds(triggerNew));
    }

    /* ------------------------------------------------------------------ *
     * Helpers
     * ------------------------------------------------------------------ */

    /** Collects the Account ids of the given cases, ignoring cases without an Account. */
    private static Set<Id> collectAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : records) {
            Id accountId = ((Case) record).AccountId;
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }
        return accountIds;
    }

    /**
     * Recomputes and stores the number of open cases for every Account in the set.
     * Uses one aggregate query on Case, one query on Account and at most one DML statement.
     */
    private static void rollupOpenCaseCounts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Query 1: number of open cases per Account.
        // Accounts without any open case are simply not returned and count as 0.
        List<AggregateResult> openCaseAggregates = [
                SELECT AccountId accountId, COUNT(Id) caseCount
                FROM Case
                WHERE AccountId IN :accountIds
                  AND IsClosed = false
                GROUP BY AccountId
        ];

        Map<Id, Integer> openCaseCounts = new Map<Id, Integer>();
        for (AggregateResult result : openCaseAggregates) {
            Id accountId = (Id) result.get('accountId');
            Integer caseCount = (Integer) result.get('caseCount');
            if (accountId != null && caseCount != null) {
                openCaseCounts.put(accountId, caseCount);
            }
        }

        // Query 2: current values on the Accounts that may have to be refreshed.
        List<Account> accounts = [
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds
        ];

        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : accounts) {
            Integer openCaseCount = openCaseCounts.containsKey(account.Id)
                    ? openCaseCounts.get(account.Id)
                    : 0;
            Decimal currentValue = account.FB_Open_Case_Count__c;

            // A blank (null) value is written as 0 so the field is never left empty.
            if (currentValue == null || currentValue.intValue() != openCaseCount) {
                account.FB_Open_Case_Count__c = openCaseCount;
                accountsToUpdate.add(account);
            }
        }

        // Single DML statement for the whole batch.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
