/**
 * Singleton cache of the parent Accounts needed by the Contact trigger actions.
 *
 * Why this exists
 * ---------------
 * The Contact before-insert actions need the parent Account (billing address and
 * AccountSource), but the actions themselves must not run SOQL. The nested
 * {@link TA_Contact_Queries.Service} action is registered with the lowest
 * Order__c so that it always executes first, loads every Account referenced by
 * the contacts of the current trigger execution with a single query, and stores
 * the result here. The other actions then read the cached Accounts.
 *
 * The cache is reloaded on every trigger execution (the map is replaced, not
 * merged), because later DML in the same transaction can involve other Accounts.
 *
 * Usage
 * -----
 *   Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;
 */
public with sharing class TA_Contact_Queries {
    /** Single instance for the current transaction. */
    private static TA_Contact_Queries instance;

    /**
     * Parent Accounts of the contacts handled by the current trigger execution,
     * keyed by Account Id. Never null; empty when the batch has no Account ids.
     */
    public Map<Id, Account> accountsById { get; set; }

    /** Private constructor: use getInstance(). */
    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    /**
     * @return the singleton instance for the current transaction.
     */
    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Loads the parent Accounts of the given contacts with a single query and
     * replaces the cached map. Bulk safe: one query per trigger execution,
     * regardless of the number of records in the batch.
     *
     * @param triggerNew the contacts of the current trigger execution.
     */
    public static void loadAccounts(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            if (record.get('AccountId') != null) {
                accountIds.add((Id) record.get('AccountId'));
            }
        }

        Map<Id, Account> accounts = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            for (Account account : [
                SELECT Id,
                       AccountSource,
                       BillingStreet,
                       BillingCity,
                       BillingPostalCode,
                       BillingCountry
                FROM Account
                WHERE Id IN :accountIds
            ]) {
                accounts.put(account.Id, account);
            }
        }

        TA_Contact_Queries self = getInstance();
        self.accountsById = accounts;
    }

    /**
     * Trigger action that populates the Account cache.
     *
     * Registered as Trigger_Action__mdt record "TA_Contact_Queries_Service"
     * (Apex_Class_Name__c = TA_Contact_Queries.Service) with Order__c 1 so that
     * it runs before any action that consumes the cached Accounts.
     *
     * Declared static so the framework can instantiate it by name
     * (Type.forName('TA_Contact_Queries.Service').newInstance()) without an
     * instance of the outer class.
     */
    public static class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.loadAccounts(triggerNew);
        }
    }
}
